.floating-lyrics{--duration:.35s}
.floating-lyrics .lyrics-bg{display:none}
.floating-lyrics .btn-close{opacity:.5;color:#ffffffb3;background:#0000004d;transition:opacity .2s}
.floating-lyrics:hover .btn-close{opacity:1}
body.has-floating-lyrics{padding-bottom:50px}
@media (width>=768px){body.has-floating-lyrics{padding-bottom:70px}}
