/* ============================================
 * 花园漫步 — 文章底部区
 *
 * 显示：字数、阅读时间、最后更新距今天数、随机漫步
 * ============================================ */

.garden-walk {
  margin: 24px 0;
  padding: 16px 18px;
  border-radius: 12px;
  background: var(--red-5-5, rgba(255,228,228,0.08));
  border: 1px solid var(--red-5, rgba(255,228,228,0.2));
  position: relative;
  overflow: hidden;
}

.garden-walk-header {
  font-size: 15px;
  font-weight: 700;
  color: var(--red-1, #ff5252);
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.garden-walk-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 12px;
  font-size: 13px;
  opacity: 0.7;
}

.garden-stat {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.garden-walk-random {
  display: flex;
  gap: 8px;
}

.garden-walk-btn {
  flex: 1;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--red-3, #ffafaf);
  background: transparent;
  color: var(--highlight-foreground, #666);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.garden-walk-btn:hover {
  background: linear-gradient(135deg, var(--red-1, #ff5252), #ff8a65);
  color: #fff;
  border-color: transparent;
  transform: translateY(-1px);
}

/* ============================================
 * 加密增强系统样式
 *
 * 包含：解密彩蛋、密码迷宫、知识问答、双人解密 UI
 * ============================================ */

/* ---- 密码线索面板 ---- */
.hbe-clues-panel {
  margin: 12px 0;
  padding: 12px 14px;
  border-radius: 10px;
  background: var(--red-5-5, rgba(255,228,228,0.1));
  border: 1px dashed var(--red-3, #ffafaf);
  font-size: 13px;
  line-height: 1.7;
}

/* ---- 知识问答 ---- */
.hbe-quiz-wrap {
  margin: 12px 0;
}

#hbe-quiz-input:focus {
  border-color: var(--red-1, #ff5252) !important;
  box-shadow: 0 0 0 3px rgba(255, 82, 82, 0.15);
}

#hbe-quiz-btn:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

#hbe-quiz-btn:active {
  transform: translateY(0);
}

/* ---- 双人解密 ---- */
.hbe-dual-wrap input:focus {
  border-color: var(--red-1, #ff5252) !important;
  box-shadow: 0 0 0 3px rgba(255, 82, 82, 0.15);
}

/* ========================================================================
   日历 · calendar.css
   月历网格 + 年度热力图。全部基于主题 CSS 变量，自动适配明暗与配色主题。
   ------------------------------------------------------------------------ */

.calendar-page {
  --cal-radius: 14px;
  --cal-gap: clamp(14px, 2vw, 24px);
  max-width: 1080px;
  margin: 0 auto;
  padding: 8px 4px 80px;
}

/* --- HERO --- */
.cal-hero {
  padding: 48px 8px 36px;
  border-bottom: 1px solid var(--red-5);
}
.cal-hero__eyebrow {
  font-size: 12px;
  letter-spacing: 0.28em;
  color: var(--red-3);
  text-transform: uppercase;
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.cal-hero__eyebrow::before {
  content: "";
  display: block;
  width: 24px;
  height: 1px;
  background: var(--red-2);
}
.cal-hero__title {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 500;
  line-height: 1.3;
  color: var(--red-1);
  margin: 0 0 10px;
}
.cal-hero__sub {
  color: var(--red-3);
  font-size: 14px;
  margin: 0;
}
.cal-hero__stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--cal-gap);
  margin-top: 32px;
}
.cal-stat {
  background: var(--color-wrap);
  border: 1px solid var(--red-5);
  border-radius: var(--cal-radius);
  padding: 18px 16px;
  text-align: center;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.cal-stat:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 24px var(--color-hover-shadow);
}
.cal-stat__num {
  font-size: clamp(22px, 3vw, 32px);
  font-weight: 700;
  color: var(--red-1);
  line-height: 1.2;
}
.cal-stat__label {
  font-size: 12px;
  color: var(--red-3);
  margin-top: 6px;
  letter-spacing: 0.08em;
}

/* --- SECTION --- */
.cal-section {
  margin-top: 44px;
  background: var(--color-wrap);
  border: 1px solid var(--red-5);
  border-radius: var(--cal-radius);
  padding: clamp(18px, 3vw, 30px);
}
.cal-section__title {
  font-size: 17px;
  font-weight: 600;
  color: var(--red-1);
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.cal-section__title i {
  color: var(--red-2);
}

/* --- HEATMAP --- */
.cal-heatmap-wrap {
  margin-top: 20px;
  overflow-x: auto;
  padding-bottom: 6px;
}
.cal-heatmap {
  display: grid;
  grid-template-rows: repeat(7, 13px);
  grid-auto-flow: column;
  grid-auto-columns: 13px;
  gap: 3px;
  width: max-content;
}
.cal-hm-cell {
  width: 13px;
  height: 13px;
  border-radius: 3px;
  background: var(--red-5);
  cursor: default;
  transition: transform 0.12s ease;
}
.cal-hm-cell[data-level="0"] { background: var(--red-5); }
.cal-hm-cell[data-level="1"] { background: var(--red-4); }
.cal-hm-cell[data-level="2"] { background: var(--red-3); }
.cal-hm-cell[data-level="3"] { background: var(--red-2); }
.cal-hm-cell[data-level="4"] { background: var(--red-1); }
.cal-hm-cell--future {
  opacity: 0.35;
}
.cal-hm-cell:hover {
  transform: scale(1.3);
  outline: 1px solid var(--red-2);
}
.cal-heatmap-legend {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 14px;
  font-size: 12px;
  color: var(--red-3);
}
.cal-heatmap-legend .cal-hm-cell {
  cursor: default;
}
.cal-heatmap-legend .cal-hm-cell:hover {
  transform: none;
  outline: none;
}

.cal-tooltip {
  position: fixed;
  z-index: 200;
  pointer-events: none;
  background: var(--red-1);
  color: var(--red-6);
  font-size: 12px;
  line-height: 1.5;
  padding: 6px 10px;
  border-radius: 8px;
  box-shadow: 0 6px 20px var(--color-hover-shadow);
  white-space: nowrap;
}

/* --- TOOLBAR / NAV --- */
.cal-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
}
.cal-nav {
  display: flex;
  align-items: center;
  gap: 8px;
}
.cal-nav__btn,
.cal-nav__today {
  background: var(--red-5-5);
  border: 1px solid var(--red-5);
  color: var(--red-2);
  border-radius: 10px;
  height: 34px;
  min-width: 34px;
  padding: 0 12px;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.cal-nav__btn:hover,
.cal-nav__today:hover {
  background: var(--red-1);
  color: var(--red-6);
  border-color: var(--red-1);
}
.cal-nav__label {
  font-size: 16px;
  font-weight: 600;
  color: var(--red-1);
  min-width: 108px;
  text-align: center;
}

/* --- FILTERS --- */
.cal-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 18px;
}
.cal-filter {
  background: transparent;
  border: 1px solid var(--red-5);
  color: var(--red-3);
  border-radius: 9999px;
  padding: 6px 14px;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.cal-filter:hover {
  border-color: var(--red-3);
  color: var(--red-1);
}
.cal-filter.active {
  background: var(--red-1);
  border-color: var(--red-1);
  color: var(--red-6);
}

/* --- MONTH GRID --- */
.cal-weekdays,
.cal-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 6px;
}
.cal-weekdays {
  margin-top: 20px;
}
.cal-weekdays span {
  text-align: center;
  font-size: 12px;
  color: var(--red-3);
  padding-bottom: 6px;
  letter-spacing: 0.1em;
}
.cal-grid {
  margin-top: 4px;
}
.cal-day {
  position: relative;
  min-height: 74px;
  background: var(--red-5-5);
  border: 1px solid var(--red-5);
  border-radius: 10px;
  padding: 8px;
  cursor: default;
  transition: all 0.2s ease;
  overflow: hidden;
}
.cal-day--empty {
  background: transparent;
  border-color: transparent;
}
.cal-day--has-events {
  cursor: pointer;
}
.cal-day--has-events:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 18px var(--color-hover-shadow);
  border-color: var(--red-4);
}
.cal-day--today {
  border-color: var(--red-2);
  box-shadow: inset 0 0 0 1px var(--red-2);
}
.cal-day--selected {
  background: var(--red-1);
  border-color: var(--red-1);
}
.cal-day--selected .cal-day__num {
  color: var(--red-6);
}
.cal-day__num {
  font-size: 13px;
  font-weight: 600;
  color: var(--red-2);
  line-height: 1;
}
.cal-day--today .cal-day__num::after {
  content: " 今天";
  font-size: 10px;
  font-weight: 400;
  color: var(--red-3);
}
.cal-day--selected.cal-day--today .cal-day__num::after {
  color: var(--red-5);
}
.cal-day__dots {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
  margin-top: 8px;
  font-size: 13px;
  line-height: 1;
}
.cal-day__count {
  position: absolute;
  right: 8px;
  bottom: 6px;
  font-size: 10px;
  color: var(--red-3);
}

/* --- DAY DETAIL --- */
.cal-day-detail {
  margin-top: 18px;
  border: 1px dashed var(--red-4);
  border-radius: var(--cal-radius);
  padding: 18px 20px;
  background: var(--red-5-5);
  animation: cal-fade-in 0.25s ease;
}
@keyframes cal-fade-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}
.cal-day-detail__head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}
.cal-day-detail__date {
  font-size: 15px;
  font-weight: 600;
  color: var(--red-1);
  margin: 0;
}
.cal-day-detail__close {
  background: transparent;
  border: none;
  color: var(--red-3);
  cursor: pointer;
  font-size: 14px;
  padding: 4px 8px;
  border-radius: 8px;
  transition: all 0.2s ease;
}
.cal-day-detail__close:hover {
  background: var(--red-5);
  color: var(--red-1);
}
.cal-day-detail__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.cal-event {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 10px 14px;
  background: var(--color-wrap);
  border: 1px solid var(--red-5);
  border-radius: 10px;
  transition: all 0.2s ease;
}
.cal-event:hover {
  border-color: var(--red-3);
  transform: translateX(3px);
}
.cal-event__icon {
  flex: 0 0 auto;
  font-size: 15px;
}
.cal-event__body {
  flex: 1;
  min-width: 0;
}
.cal-event__title {
  font-size: 14px;
  color: var(--red-1);
  word-break: break-all;
}
a.cal-event__title {
  text-decoration: none;
}
a.cal-event__title:hover {
  color: var(--red-2);
  text-decoration: underline;
}
.cal-event__detail {
  font-size: 12px;
  color: var(--red-3);
  margin-top: 3px;
}
.cal-event__tag {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--red-3);
  border: 1px solid var(--red-5);
  border-radius: 9999px;
  padding: 2px 9px;
}

/* --- EMPTY --- */
.cal-empty {
  margin-top: 32px;
  text-align: center;
  color: var(--red-3);
  font-size: 14px;
}

/* --- RESPONSIVE --- */
@media (max-width: 768px) {
  .cal-hero__stats {
    grid-template-columns: repeat(2, 1fr);
  }
  .cal-day {
    min-height: 56px;
    padding: 6px;
  }
  .cal-day__dots {
    font-size: 10px;
  }
  .cal-day--today .cal-day__num::after {
    content: "";
  }
  .cal-toolbar {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* ============================================
 * Konami Code 彩蛋样式
 * 触发条件：↑ ↑ ↓ ↓ ← → ← → B A
 * ============================================ */

/* --- 樱花 Canvas 覆盖层 --- */
#konami-sakura-canvas {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  z-index: 99999;
  pointer-events: none; /* 不阻挡用户点击 */
  opacity: 0;
  animation: konami-fade-in 0.6s ease-out forwards;
}

/* --- 主题色彩虹旋转（添加到 html 元素） --- */
html.konami-active {
  animation: konami-hue 3s linear infinite;
}

@keyframes konami-hue {
  0%   { filter: hue-rotate(0deg); }
  100% { filter: hue-rotate(360deg); }
}

/* --- 弹窗卡片 --- */
#konami-popup {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0.7);
  z-index: 100000;
  padding: 36px 48px;
  max-width: 420px;
  text-align: center;

  /* 毛玻璃 */
  background: rgba(255, 255, 255, 0.25);
  backdrop-filter: blur(18px) saturate(180%);
  -webkit-backdrop-filter: blur(18px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.45);
  border-radius: 20px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12),
              0 0 0 1px rgba(255, 255, 255, 0.1) inset;

  /* 动画 */
  opacity: 0;
  animation: konami-popup-in 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) 0.3s forwards;
}

[data-theme="dark"] #konami-popup {
  background: rgba(40, 40, 40, 0.45);
  border-color: rgba(255, 255, 255, 0.15);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35),
              0 0 0 1px rgba(255, 255, 255, 0.06) inset;
}

#konami-popup .konami-emoji {
  font-size: 48px;
  line-height: 1;
  margin-bottom: 16px;
  display: block;
  animation: konami-bounce 1s ease infinite;
}

#konami-popup .konami-text {
  font-size: 18px;
  font-weight: 600;
  line-height: 1.6;
  color: #333;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.5);
}

[data-theme="dark"] #konami-popup .konami-text {
  color: #eee;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
}

#konami-popup .konami-hint {
  margin-top: 16px;
  font-size: 12px;
  color: #999;
}

/* --- 动画关键帧 --- */
@keyframes konami-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes konami-popup-in {
  from {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.7);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}

@keyframes konami-bounce {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-8px); }
}

/* --- 淡出（JS 添加此 class 后触发） --- */
#konami-sakura-canvas.konami-fade-out,
#konami-popup.konami-fade-out {
  animation: konami-fade-out-kf 0.8s ease forwards;
}

@keyframes konami-fade-out-kf {
  from { opacity: 1; }
  to   { opacity: 0; }
}

/* ============================================
 * Live2D 对话气泡自定义样式
 * 描述: 暗夜星空魔法款 + 打字机效果
 * 使用超高特异性选择器压制主题默认样式
 * ============================================ */

/* —— 默认隐藏 —— */
html body div#live2d-tips {
  opacity: 0 !important;
  visibility: hidden !important;
  transition: opacity 0.5s ease, visibility 0.5s ease !important;
  pointer-events: none !important;
}

/* —— 说话时显示（星空魔法款） —— */
html body div#live2d-tips.live2d-tips-active {
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;

  color: #F8EEFF !important;
  font-size: 14px !important;
  font-weight: 600 !important;
  padding: 12px 16px !important;
  max-width: 260px !important;
  word-break: break-word !important;
  border-radius: 16px !important;
  border: 1px solid rgba(180, 150, 255, 0.4) !important;
  z-index: 9999 !important;

  /* 星空背景 */
  background:
    radial-gradient(circle at 20% 30%, rgba(255,255,255,.9) 1px, transparent 2px),
    radial-gradient(circle at 70% 20%, rgba(255,255,255,.7) 1px, transparent 2px),
    radial-gradient(circle at 80% 70%, rgba(255,255,255,.8) 1px, transparent 2px),
    radial-gradient(circle at 40% 80%, rgba(255,255,255,.6) 1px, transparent 2px),
    linear-gradient(135deg, rgba(55,35,90,.95), rgba(30,20,55,.95)) !important;
  background-image:
    radial-gradient(circle at 20% 30%, rgba(255,255,255,.9) 1px, transparent 2px),
    radial-gradient(circle at 70% 20%, rgba(255,255,255,.7) 1px, transparent 2px),
    radial-gradient(circle at 80% 70%, rgba(255,255,255,.8) 1px, transparent 2px),
    radial-gradient(circle at 40% 80%, rgba(255,255,255,.6) 1px, transparent 2px),
    linear-gradient(135deg, rgba(55,35,90,.95), rgba(30,20,55,.95)) !important;

  box-shadow:
    0 0 20px rgba(138, 43, 226, 0.4),
    inset 0 0 15px rgba(255, 255, 255, 0.05) !important;

  text-shadow: 0 0 8px rgba(177, 156, 217, 0.8) !important;

  animation:
    tipsBounce 0.4s ease,
    starTwinkle 3s infinite !important;
}

/* —— 打字机光标 —— */
html body div#live2d-tips.live2d-tips-active::after {
  content: "▋";
  margin-left: 2px;
  color: #B19CD9;
  animation: cursorBlink 0.8s infinite;
}

/* —— 弹出动画 —— */
@keyframes tipsBounce {
  0%   { transform: translateY(-8px) scale(0.95); }
  60%  { transform: translateY(2px) scale(1.02); }
  100% { transform: translateY(0) scale(1); }
}

/* —— 星光闪烁 —— */
@keyframes starTwinkle {
  0%, 100% {
    box-shadow:
      0 0 20px rgba(138, 43, 226, 0.4),
      inset 0 0 15px rgba(255, 255, 255, 0.05);
  }
  50% {
    box-shadow:
      0 0 30px rgba(177, 156, 217, 0.8),
      inset 0 0 20px rgba(255, 255, 255, 0.1);
  }
}

/* —— 光标闪烁 —— */
@keyframes cursorBlink {
  50% { opacity: 0; }
}

/* ============================================
 * Miku 互动小游戏 — 样式
 *
 * 包含：热区定位、侧边栏面板、猜拳（星空质感）、骰子
 * ============================================ */

/* ---- 热区容器（覆盖在 canvas 上） ---- */
#live2d-hit-zone {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 90;
}

/* ---- 各部位热区（透明不可见） ---- */
.miku-hitzone {
  position: absolute;
  pointer-events: auto;
  cursor: pointer;
}

#live2d-hit-head {
  top: 5%;
  left: 25%;
  width: 50%;
  height: 28%;
  border-radius: 50%;
}

#live2d-hit-body {
  top: 32%;
  left: 15%;
  width: 70%;
  height: 38%;
}

#live2d-hit-feet {
  top: 68%;
  left: 25%;
  width: 50%;
  height: 25%;
}

/* ---- 侧边栏统计行 ---- */
.miku-stat-row {
  display: flex;
  justify-content: space-between;
  padding: 3px 0;
  font-size: 13px;
  opacity: 0.85;
}

.miku-stat-row .miku-stat-val {
  color: var(--red-1, #ff5252);
  font-weight: 700;
  font-family: monospace;
}

/* ---- 游戏主按钮 ---- */
.miku-game-btn {
  width: 100%;
  padding: 10px;
  background: linear-gradient(135deg, var(--red-1, #ff5252), #ff8a65);
  color: #fff;
  border: none;
  border-radius: 10px;
  font-size: 0.9em;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 12px rgba(255, 78, 106, 0.25);
}

.miku-game-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(255, 78, 106, 0.4);
}

.miku-game-btn:active {
  transform: translateY(0);
}

/* ---- 游戏 Tab 切换 ---- */
.miku-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 10px;
}

.miku-tab {
  flex: 1;
  padding: 6px 4px;
  border-radius: 8px;
  border: 1px solid var(--red-3, #ffafaf);
  background: transparent;
  color: var(--highlight-foreground, #666);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.miku-tab.active {
  background: linear-gradient(135deg, var(--red-1, #ff5252), #ff8a65);
  color: #fff;
  border-color: transparent;
}

.miku-tab:hover:not(.active) {
  border-color: var(--red-1, #ff5252);
  color: var(--red-1, #ff5252);
}

/* ============================================
 * 星空玻璃质感 RPS 按钮
 * ============================================ */

/* --- 基础风格 --- */
.miku-rps-choice {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 1.5px solid rgba(180, 150, 255, 0.4);
  background:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,0.15) 1px, transparent 2px),
    radial-gradient(circle at 70% 40%, rgba(255,255,255,0.10) 1px, transparent 2px),
    radial-gradient(circle at 50% 80%, rgba(255,255,255,0.12) 1px, transparent 2px),
    linear-gradient(135deg, rgba(55,35,90,0.85), rgba(30,20,55,0.92));
  font-size: 24px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #F8EEFF;
  text-shadow: 0 0 6px rgba(177, 156, 217, 0.6);
  box-shadow:
    0 0 10px rgba(138, 43, 226, 0.25),
    inset 0 0 8px rgba(255, 255, 255, 0.05);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  overflow: visible;
  outline: none;
}

.miku-rps-choice:hover {
  transform: scale(1.15);
  border-color: rgba(200, 170, 255, 0.7);
  animation: rpsGlow 2s infinite ease-in-out;
}

.miku-rps-choice:active {
  transform: scale(0.92);
  transition-duration: 0.05s;
}

.miku-rps-choice.miku-rps-flash {
  transform: scale(0.85);
  background:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,0.35) 1px, transparent 2px),
    radial-gradient(circle at 70% 40%, rgba(255,255,255,0.25) 1px, transparent 2px),
    radial-gradient(circle at 50% 80%, rgba(255,255,255,0.30) 1px, transparent 2px),
    linear-gradient(135deg, rgba(100, 60, 180, 0.95), rgba(60, 40, 110, 0.95));
  box-shadow:
    0 0 30px rgba(177, 156, 217, 0.8),
    0 0 60px rgba(138, 43, 226, 0.5);
  transition-duration: 0.1s;
}

@keyframes rpsGlow {
  0%, 100% {
    box-shadow:
      0 0 20px rgba(138, 43, 226, 0.5),
      0 0 40px rgba(177, 156, 217, 0.3),
      inset 0 0 12px rgba(255, 255, 255, 0.08);
  }
  50% {
    box-shadow:
      0 0 30px rgba(177, 156, 217, 0.7),
      0 0 55px rgba(138, 43, 226, 0.4),
      inset 0 0 16px rgba(255, 255, 255, 0.12);
  }
}

@keyframes vsPop {
  0%   { transform: scale(0); opacity: 0; }
  60%  { transform: scale(1.3); }
  100% { transform: scale(1); opacity: 1; }
}

/* ============================================
 * 粒子爆发
 * ============================================ */
.rps-particle {
  position: fixed;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  pointer-events: none;
  z-index: 10001;
  animation: rpsParticleFly 0.6s ease-out forwards;
}

@keyframes rpsParticleFly {
  0%   { opacity: 1; transform: translate(0,0) scale(1); }
  100% { opacity: 0; transform: translate(var(--dx),var(--dy)) scale(0); }
}

/* 骰子游戏
   ============================================ */

.miku-die { display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;margin:0 3px;border-radius:6px;background:#fff;border:1.5px solid rgba(180,150,255,0.5);color:#333;font-size:18px;font-weight:700;box-shadow:0 2px 6px rgba(0,0,0,0.1); }
.miku-die.rolling { animation:diceRoll 0.1s infinite alternate; }

@keyframes diceRoll {
  0%   { transform: rotate(-10deg) scale(1); }
  25%  { transform: rotate(10deg) scale(1.1); }
  50%  { transform: rotate(-5deg) scale(0.95); }
  75%  { transform: rotate(15deg) scale(1.05); }
  100% { transform: rotate(0deg) scale(1); }
}

.miku-dice-section { margin-bottom:6px; }
.miku-dice-area { display:flex;justify-content:center;gap:4px;margin:4px 0;min-height:38px;align-items:center; }
.miku-dice-label { font-size:11px;opacity:0.6;font-weight:600;margin-bottom:2px; }
.miku-dice-result { font-size:14px;font-weight:700;color:var(--red-1,#ff5252);margin-bottom:6px;min-height:20px; }
.miku-dice-vs { font-size:11px;font-weight:800;color:rgba(180,150,255,0.6);margin:2px 0; }
.miku-die.yahtzee { border-color:#ffd700;box-shadow:0 0 10px rgba(255,215,0,0.5);color:#b8860b; }

/* 老虎机
   ============================================ */

.miku-slot-machine { margin-bottom:8px; }
.miku-slot-display { display:flex;justify-content:center;gap:6px;margin:8px 0; }
.miku-slot-reel {
  width:44px;height:48px;border-radius:8px;
  background: linear-gradient(135deg, rgba(55,35,90,0.85), rgba(30,20,55,0.92));
  border:1.5px solid rgba(180,150,255,0.5);
  color:#F8EEFF;
  font-size:24px;line-height:48px;text-align:center;
  box-shadow:0 0 10px rgba(138,43,226,0.3);
  overflow:hidden;
  position:relative;
}
.miku-slot-reel.rolling { animation:slotSpin 0.1s infinite linear; }
@keyframes slotSpin {
  0%   { transform:translateY(-2px); }
  50%  { transform:translateY(2px); }
  100% { transform:translateY(-2px); }
}
.miku-slot-reel.win-highlight {
  border-color:#ffd700;
  box-shadow:0 0 20px rgba(255,215,0,0.6);
  animation:slotWin 0.5s ease 3;
}
@keyframes slotWin {
  0%,100% { transform:scale(1); }
  50% { transform:scale(1.15); }
}
.miku-slot-prize {
  font-size:13px;font-weight:700;margin:6px 0;min-height:20px;
}
.miku-slot-chances {
  font-size:11px;opacity:0.6;margin-bottom:6px;
}
.miku-slot-free-msg {
  font-size:12px;opacity:0.6;margin:4px 0;
}

/* ============================================
 * 留言板浮窗（聊天室风格）— 复刻参考站设计
 * 深色毛玻璃 + 绿色点缀 + 气泡消息流
 * 配合 messages-wall.css 使用（本文件负责浮窗容器与气泡化）
 * ============================================ */

/* ---- 浮窗容器 ---- */
.msg-modal {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  box-sizing: border-box;
  visibility: hidden;
  pointer-events: none;
}

.msg-modal.open {
  visibility: visible;
  pointer-events: auto;
}

html.msg-modal-open,
html.msg-modal-open body {
  overflow: hidden !important;
}

.msg-modal-mask {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.msg-modal.open .msg-modal-mask {
  opacity: 1;
}

/* ---- 窗口 ---- */
.msg-modal-window {
  position: relative;
  width: min(1060px, 100%);
  max-height: min(86vh, 860px);
  display: flex;
  flex-direction: column;
  border-radius: 18px;
  overflow: hidden;
  background: linear-gradient(160deg, rgba(24, 26, 32, 0.92), rgba(12, 13, 18, 0.95));
  backdrop-filter: blur(24px) saturate(140%);
  -webkit-backdrop-filter: blur(24px) saturate(140%);
  border: 1px solid rgba(255, 255, 255, 0.09);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  opacity: 0;
  transform: translateY(26px) scale(0.96);
  transition: opacity 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}

.msg-modal.open .msg-modal-window {
  opacity: 1;
  transform: none;
}

/* ---- 标题栏 ---- */
.msg-modal-titlebar {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.02);
}

.msg-modal-title {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: #e8eaed;
}

.msg-modal-logo {
  color: #34d399;
  flex-shrink: 0;
}

.msg-modal-name {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 1px;
}

.msg-modal-slogan {
  font-size: 12px;
  color: rgba(232, 234, 237, 0.45);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.msg-modal-meta {
  margin-left: auto;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  color: #34d399;
  opacity: 0.85;
  font-variant-numeric: tabular-nums;
}

.msg-modal-dot {
  color: rgba(232, 234, 237, 0.3);
}

.msg-modal-close {
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: rgba(232, 234, 237, 0.55);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}

.msg-modal-close:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

/* ---- 内容区：列表滚动 + 编辑器固定底部 ---- */
.msg-modal-content {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ---- 浮窗内的 #msg-board 变量覆盖（深色 + 绿色点缀）---- */
.msg-modal #msg-board {
  --msg-border: rgba(255, 255, 255, 0.08);
  --msg-card: rgba(255, 255, 255, 0.03);
  --msg-text: #d4d7dc;
  --msg-muted: rgba(212, 215, 220, 0.45);
  --msg-accent: #22c55e;
  --msg-accent-soft: #34d399;
  --msg-hover: rgba(255, 255, 255, 0.05);
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  max-width: none;
  margin: 0;
  padding: 14px 16px 18px;
  box-sizing: border-box;
}

.msg-modal .msg-header {
  display: none;
}

.msg-modal .msg-body {
  flex: 1;
  min-height: 0;
  align-items: stretch;
}

/* 列表区独立滚动 */
.msg-modal .msg-main {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.msg-modal .msg-list {
  flex: 1;
  min-height: 160px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 6px;
}

.msg-modal .msg-list::-webkit-scrollbar {
  width: 8px;
}

.msg-modal .msg-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 4px;
}

/* ---- 通知栏 ---- */
.msg-modal .msg-notice {
  background: rgba(255, 255, 255, 0.03);
  border-color: rgba(255, 255, 255, 0.07);
  box-shadow: none;
}

.msg-modal .msg-notice-tag {
  background: rgba(52, 211, 153, 0.85);
}

.msg-modal .msg-notice-tag-warn {
  background: rgba(245, 158, 11, 0.9);
}

/* ---- 主体双栏 ---- */
.msg-modal .msg-main {
  background: transparent;
  border: none;
  box-shadow: none;
  padding: 4px 2px;
}

.msg-modal .msg-members {
  flex-basis: 230px;
  display: flex;
  flex-direction: column;
  background: rgba(255, 255, 255, 0.03);
  border-color: rgba(255, 255, 255, 0.07);
  box-shadow: none;
}

.msg-modal .msg-member-list {
  flex: 1;
  min-height: 0;
  max-height: none;
  overflow-y: auto;
}

.msg-modal .msg-member-list::-webkit-scrollbar {
  width: 6px;
}

.msg-modal .msg-member-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 3px;
}

.msg-modal .msg-members-count {
  background: rgba(52, 211, 153, 0.85);
}

.msg-modal .msg-member-badge {
  background: #22c55e;
}

/* ---- 气泡化消息流 ---- */
.msg-modal .msg-list .msg-card {
  border-top: none;
  padding: 10px 0;
}

.msg-modal .msg-card {
  align-items: flex-start;
}

.msg-modal .msg-card .msg-avatar {
  width: 38px;
  height: 38px;
  border-color: rgba(255, 255, 255, 0.12);
}

/* 气泡本体 */
.msg-modal .msg-card .msg-card-content {
  display: inline-block;
  padding: 10px 14px;
  border-radius: 4px 14px 14px 14px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.06);
  color: #e4e6ea;
}

.msg-modal .msg-card-head {
  gap: 6px;
}

.msg-modal .msg-nick {
  color: #34d399;
  font-size: 13px;
}

.msg-modal .msg-badge {
  background: #22c55e;
}

.msg-modal .msg-badge-owner {
  background: #f59e0b;
}

/* 站长/主人：整行右对齐，气泡换绿色调 */
.msg-modal .msg-card-admin {
  flex-direction: row-reverse;
}

.msg-modal .msg-card-admin .msg-card-body {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.msg-modal .msg-card-admin .msg-card-content {
  border-radius: 14px 4px 14px 14px;
  background: rgba(34, 197, 94, 0.14);
  border-color: rgba(34, 197, 94, 0.25);
}

.msg-modal .msg-card-admin .msg-card-meta {
  flex-direction: row-reverse;
}

.msg-modal .msg-card-admin .msg-reply-btn {
  margin-left: 0;
  margin-right: auto;
}

/* 回复引用 */
.msg-modal .msg-at {
  color: #34d399;
}

/* 回复按钮 */
.msg-modal .msg-reply-btn {
  border-color: rgba(255, 255, 255, 0.1);
}

.msg-modal .msg-reply-btn:hover {
  color: #34d399;
  border-color: rgba(52, 211, 153, 0.5);
  background: rgba(52, 211, 153, 0.08);
}

/* 嵌套回复 */
.msg-modal .msg-children {
  border-left-color: rgba(255, 255, 255, 0.1);
  align-self: stretch;
}

.msg-modal .msg-card-admin .msg-children {
  border-left: none;
  border-right: 2px solid rgba(34, 197, 94, 0.25);
  padding-left: 0;
  padding-right: 14px;
}

/* 加载更多 */
.msg-modal .msg-load-more {
  border-color: rgba(255, 255, 255, 0.12);
  color: #34d399;
}

.msg-modal .msg-load-more:hover {
  background: rgba(52, 211, 153, 0.08);
  border-color: rgba(52, 211, 153, 0.5);
}

/* ---- 编辑器 ---- */
.msg-modal .msg-editor {
  margin-top: 14px;
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 255, 255, 0.1);
  border-radius: 14px;
}

.msg-modal .msg-editor:focus-within {
  border-color: rgba(52, 211, 153, 0.55);
  box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.12);
}

.msg-modal .msg-input,
.msg-modal .msg-textarea {
  background: rgba(0, 0, 0, 0.25);
  border-color: rgba(255, 255, 255, 0.09);
  color: #e4e6ea;
}

.msg-modal .msg-input::placeholder,
.msg-modal .msg-textarea::placeholder {
  color: rgba(212, 215, 220, 0.35);
}

.msg-modal .msg-input:focus,
.msg-modal .msg-textarea:focus {
  border-color: rgba(52, 211, 153, 0.55);
}

.msg-modal .msg-guest-tag {
  flex-shrink: 0;
  padding: 4px 12px;
  border-radius: 999px;
  border: 1px solid rgba(52, 211, 153, 0.35);
  color: #34d399;
  font-size: 12px;
  background: rgba(52, 211, 153, 0.08);
  user-select: none;
}

.msg-modal .msg-send-btn {
  background: #22c55e;
  border-radius: 10px;
  padding: 8px 26px;
}

.msg-modal .msg-send-btn:hover:not(:disabled) {
  background: #16a34a;
  opacity: 1;
}

.msg-modal .msg-send-btn:disabled {
  background: rgba(255, 255, 255, 0.08);
  color: rgba(212, 215, 220, 0.35);
}

.msg-modal .msg-emoji-panel {
  background: rgba(20, 22, 28, 0.98);
  border-color: rgba(255, 255, 255, 0.1);
}

.msg-modal .msg-reply-tip {
  background: rgba(52, 211, 153, 0.1);
  color: #34d399;
}

/* ---- 移动端成员抽屉 & 悬浮按钮 ---- */
.msg-modal .msg-members-fab {
  position: fixed;
  right: 18px;
  bottom: 90px;
  z-index: 2100;
  background: #22c55e;
  display: none;
}

.msg-modal.open .msg-members-fab {
  display: none;
}

@media (max-width: 960px) {
  .msg-modal {
    padding: 0;
  }

  .msg-modal-window {
    width: 100%;
    max-height: 100vh;
    height: 100vh;
    border-radius: 0;
  }

  /* 抵消 messages-wall.css 的移动端 block 布局，保持列表滚动 + 编辑器固定底部 */
  .msg-modal .msg-body {
    display: flex;
  }

  .msg-modal .msg-members {
    background: rgba(14, 15, 20, 0.98);
  }

  #msg-board.members-open .msg-members .msg-member-list {
    height: auto;
  }

  .msg-modal.open .msg-members-fab {
    display: block;
  }

  #msg-board.members-open .msg-members-fab {
    display: none;
  }

  .msg-modal-slogan,
  .msg-modal-meta {
    display: none;
  }
}

@media (max-width: 600px) {
  .msg-modal #msg-board {
    padding: 10px 12px 14px;
  }

  .msg-modal .msg-editor-actions {
    flex-wrap: wrap;
  }
}

/* ============================================
 * 微信风改造：三模式身份面板 + 单行输入条 + 顶部加载提示
 * ============================================ */

/* ---- 顶部提示条（上滑加载 / 已到最早） ---- */
.msg-top-hint {
  flex-shrink: 0;
  text-align: center;
  padding: 8px 0 10px;
  font-size: 11.5px;
