  user-select: none;
}

/* ---- 身份选择面板 ---- */
.msg-modal .msg-auth {
  padding: 4px 2px 2px;
}

.msg-auth-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 14px;
}

.msg-auth-tab {
  flex: 1;
  padding: 8px 0;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.03);
  color: rgba(212, 215, 220, 0.6);
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s;
}

.msg-auth-tab:hover {
  border-color: rgba(52, 211, 153, 0.4);
