/* 阅读体验与响应式增强：仅覆盖主题表现层，不改变内容结构 */
:root {
  --reading-measure: 72ch;
  --reading-line-height: 1.85;
  --reading-font-size: 17px;
}

/* 正文保持舒适行宽，长文不横向铺满大屏 */
.article-entry {
  font-size: var(--reading-font-size);
  line-height: var(--reading-line-height);
  letter-spacing: 0.012em;
  overflow-wrap: anywhere;
}

.article-entry > p,
.article-entry > h1,
.article-entry > h2,
.article-entry > h3,
.article-entry > h4,
.article-entry > h5,
.article-entry > h6,
.article-entry > ul,
.article-entry > ol,
.article-entry > blockquote,
.article-entry > details,
.article-entry > table {
  max-width: var(--reading-measure);
  margin-left: auto;
  margin-right: auto;
}

.article-entry p {
  margin-top: 1em;
  margin-bottom: 1em;
}

.article-entry h2 {
  margin-top: 2.2em;
  margin-bottom: 0.9em;
  scroll-margin-top: 90px;
}

.article-entry h3,
.article-entry h4 {
  margin-top: 1.8em;
  margin-bottom: 0.7em;
  scroll-margin-top: 90px;
}

.article-entry img,
.article-entry video,
.article-entry iframe {
  max-width: 100%;
  height: auto;
}

.article-entry img {
  border-radius: 10px;
}

/* 横向内容允许独立滚动，不挤破移动端布局 */
.article-entry table,
.article-entry .highlight,
.article-entry pre {
  max-width: 100%;
}

.article-entry table {
  display: block;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.article-entry .highlight {
  border-radius: 10px;
  contain: inline-size;
}

.article-entry .highlight pre,
.article-entry pre,
.article-entry code {
  font-variant-ligatures: none;
  tab-size: 2;
}

.article-entry .highlight pre,
.article-entry pre {
  line-height: 1.65;
}

/* 目录当前项更明显，同时保留主题原有层级展开逻辑 */
.sidebar-toc-wrapper {
  scrollbar-gutter: stable;
}

.sidebar-toc-wrapper .active > a,
.sidebar-toc-wrapper .current > a {
  font-weight: 700;
  text-shadow: 0 0 10px color-mix(in srgb, var(--red-1) 35%, transparent);
}

/* 暗黑切换只过渡视觉属性，避免 all 导致布局抖动 */
body,
#wrap,
.article-inner,
.widget-wrap,
.sidebar-wrap,
.article-entry,
.article-entry blockquote,
.article-entry code {
  transition-property: color, background-color, border-color, box-shadow;
  transition-duration: 0.25s;
  transition-timing-function: ease;
}

/* 键盘用户可见焦点 */
a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
summary:focus-visible {
  outline: 3px solid var(--red-1);
  outline-offset: 3px;
}

@media (max-width: 767px) {
  :root {
    --reading-font-size: 16px;
    --reading-line-height: 1.78;
  }

  .article-entry {
    letter-spacing: 0;
    padding-left: 18px;
    padding-right: 18px;
  }

  .article-entry h1 { font-size: 1.75em; }
  .article-entry h2 { font-size: 1.45em; }
  .article-entry h3 { font-size: 1.22em; }

  .article-entry .highlight,
  .article-entry pre {
    border-radius: 8px;
  }

  .article-entry blockquote {
    margin-left: 0;
    margin-right: 0;
  }
}

@media (max-width: 479px) {
  .article-entry {
    padding-left: 14px;
    padding-right: 14px;
  }

  .post-title,
  .article-title {
    overflow-wrap: anywhere;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

