/* ============================================
 * 心灵感应环境音合成器 (Telepathic Ambient Synth)
 * 纯代码实时生成的宇宙深空低频环境音效
 * ============================================ */

(() => {
  'use strict';

  class AmbientSynth {
    constructor() {
      this.audioCtx = null;
      this.osc1 = null;
      this.osc2 = null;
      this.filter = null;
      this.gainNode = null;
      this.isPlaying = false;
      this.baseFreq1 = 55; // A1
      this.baseFreq2 = 110; // A2

      this.scrollTarget = 0;
      this.currentScroll = 0;

      // Bindings
      this.handleScroll = this.handleScroll.bind(this);
      this.handleMouseMove = this.handleMouseMove.bind(this);
      this.updateLoop = this.updateLoop.bind(this);
    }

    init() {
      if (this.audioCtx) return;
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;

      this.audioCtx = new AudioContext();

      // Master Gain
      this.gainNode = this.audioCtx.createGain();
      this.gainNode.gain.value = 0;
      this.gainNode.connect(this.audioCtx.destination);

      // Lowpass Filter
      this.filter = this.audioCtx.createBiquadFilter();
      this.filter.type = 'lowpass';
      this.filter.frequency.value = 400;
      this.filter.Q.value = 5;
      this.filter.connect(this.gainNode);

      // Oscillator 1 (Sub)
      this.osc1 = this.audioCtx.createOscillator();
      this.osc1.type = 'sine';
      this.osc1.frequency.value = this.baseFreq1;
      this.osc1.connect(this.filter);

      // Oscillator 2 (Drone)
      this.osc2 = this.audioCtx.createOscillator();
      this.osc2.type = 'triangle';
      this.osc2.frequency.value = this.baseFreq2;

      // Panner for Osc 2
      this.panner = this.audioCtx.createStereoPanner ? this.audioCtx.createStereoPanner() : this.audioCtx.createGain();
      this.osc2.connect(this.panner);
      this.panner.connect(this.filter);

      this.osc1.start();
      this.osc2.start();

      window.addEventListener('scroll', this.handleScroll, { passive: true });
      window.addEventListener('mousemove', this.handleMouseMove, { passive: true });
      requestAnimationFrame(this.updateLoop);
    }

    start() {
      this.init();
      if (this.audioCtx.state === 'suspended') this.audioCtx.resume();
      this.gainNode.gain.setTargetAtTime(0.3, this.audioCtx.currentTime, 2);
      this.isPlaying = true;
    }

    stop() {
      if (!this.isPlaying) return;
      this.gainNode.gain.setTargetAtTime(0.001, this.audioCtx.currentTime, 1);
      setTimeout(() => {
        if (this.audioCtx && this.audioCtx.state === 'running') {
          this.audioCtx.suspend();
        }
        this.isPlaying = false;
      }, 2000);
    }

    handleScroll() {
      this.scrollTarget = 1;
    }

    handleMouseMove(e) {
      if (!this.isPlaying || !this.audioCtx) return;
      const x = e.clientX / window.innerWidth;
      const y = e.clientY / window.innerHeight;

      if (this.panner.pan) {
        this.panner.pan.setTargetAtTime((x * 2) - 1, this.audioCtx.currentTime, 0.1);
      }

      const newFreq = this.baseFreq2 + (1 - y) * 20;
      this.osc2.frequency.setTargetAtTime(newFreq, this.audioCtx.currentTime, 0.5);
    }

    updateLoop() {
      if (this.isPlaying && this.audioCtx) {
        // Decay scroll target
        this.scrollTarget *= 0.95;
        this.currentScroll += (this.scrollTarget - this.currentScroll) * 0.1;

        // Modulate filter based on scroll
        const minCutoff = 200;
        const maxCutoff = 1500;
        const cutoff = minCutoff + (maxCutoff - minCutoff) * this.currentScroll;
        this.filter.frequency.setTargetAtTime(cutoff, this.audioCtx.currentTime, 0.1);
      }
      requestAnimationFrame(this.updateLoop);
    }
  }

  window.AmbientSynth = new AmbientSynth();
})();

/* ============================================
 * 多组合隐藏彩蛋系统
 *
 * 在下方 EASTER_EGGS 数组中配置多个彩蛋：
 *   keys  — 按键序列（使用 KeyCode 名称）
 *   emoji — 弹窗顶部的表情
 *   text  — 弹窗正文（支持 HTML）
 *   sakura    — 是否触发樱花雨 (默认 true)
 *   hueRotate — 是否触发彩虹色 (默认 true)
 *   popup     — 是否弹窗 (默认 true)
 *
 * 8 秒后一切自动恢复
 * ============================================ */
(() => {
  'use strict';

  /* =============================================
   *  🎮 在这里配置你的所有彩蛋组合
   * ============================================= */
  const EASTER_EGGS = [
    {
      // 经典 Konami Code：↑ ↑ ↓ ↓ ← → ← → B A
      keys: ['ArrowUp','ArrowUp','ArrowDown','ArrowDown','ArrowLeft','ArrowRight','ArrowLeft','ArrowRight','KeyB','KeyA'],
      emoji: '🎉',
      text: '恭喜你找到了隐藏的秘密！<br>你一定是个有趣的人~',
      sakura: true,
      hueRotate: true,
      popup: true,
    },
    {
      // CNY
      keys: ['KeyC','KeyN','KeyY'],
      emoji: '🧧',
      text: '新年快乐！恭喜发财！🎆<br>愿你万事如意~',
      sakura: true,
      hueRotate: false,
      popup: true,
    },
    {
      // LOVE
      keys: ['KeyL','KeyO','KeyV','KeyE'],
      emoji: '💕',
      text: 'Love is in the air 💌<br>你被这个博客爱着哦~',
      sakura: true,
      hueRotate: true,
      popup: true,
    },
    // ↓↓↓ 想加更多？照着上面的格式复制一组就行 ↓↓↓
  ];

  /* ---- 常量 ---- */
  const DURATION    = 8000;  // 特效持续时间（毫秒）
  const FADE_OUT_MS = 800;   // 淡出动画时间
  const PETAL_COUNT = 55;    // 花瓣数量

  /* ---- 状态 ---- */
  let inputBuffer = [];
  let isActive = false;
  const maxLen = Math.max(...EASTER_EGGS.map(e => e.keys.length));

  /* ---- 键盘监听 ---- */
  document.addEventListener('keydown', (e) => {
    if (isActive) return;

    inputBuffer.push(e.code);
    // 只保留最近 maxLen 次按键
    if (inputBuffer.length > maxLen) {
      inputBuffer.shift();
    }

    // 逐个检查是否有匹配的彩蛋
    for (const egg of EASTER_EGGS) {
      const len = egg.keys.length;
      if (inputBuffer.length >= len) {
        const tail = inputBuffer.slice(-len);
        if (tail.every((key, i) => key === egg.keys[i])) {
          inputBuffer = [];
          activateEasterEgg(egg);
          return;
        }
      }
    }
  });

  /* ==============================
   *  主触发函数
   * ============================== */
  function activateEasterEgg(egg) {
    isActive = true;

    const elements = []; // 收集所有需要清理的 DOM

    if (egg.sakura !== false) {
      elements.push(createSakuraCanvas());
    }
    if (egg.popup !== false) {
      elements.push(createPopup(egg));
    }
    if (egg.hueRotate !== false) {
      applyHueRotate();
    }

    // 8 秒后开始淡出
    setTimeout(() => {
      elements.forEach(el => el.classList.add('konami-fade-out'));

      setTimeout(() => {
        elements.forEach(el => el.remove());
        document.documentElement.classList.remove('konami-active');
        isActive = false;
      }, FADE_OUT_MS);
    }, DURATION);
  }

  /* ==============================
   *  1. 樱花雨（Canvas）
   * ============================== */
  function createSakuraCanvas() {
    const canvas = document.createElement('canvas');
    canvas.id = 'konami-sakura-canvas';
    document.body.appendChild(canvas);

    const ctx = canvas.getContext('2d');
    let w, h;
    let animId;

    let musicEnergy = 0;
    let musicTreble = 0;
    const audioCallback = (data) => {
      musicEnergy = data.energy || 0;
      musicTreble = data.treble || 0;
    };
    if (window.AudioReactor) {
      window.AudioReactor.subscribe(audioCallback);
    }

    function resize() {
      w = canvas.width = window.innerWidth;
      h = canvas.height = window.innerHeight;
    }
    resize();
    window.addEventListener('resize', resize);

    const petals = [];
    for (let i = 0; i < PETAL_COUNT; i++) {
      petals.push(makePetal());
    }

    function makePetal(startFromTop) {
      return {
        x: Math.random() * w,
        y: startFromTop ? -20 : Math.random() * h,
        size: 6 + Math.random() * 10,
        speedY: 0.6 + Math.random() * 1.8,
        speedX: -0.4 + Math.random() * 0.8,
        rotation: Math.random() * Math.PI * 2,
        rotSpeed: (Math.random() - 0.5) * 0.04,
        wobble: Math.random() * Math.PI * 2,
        wobbleSpeed: 0.015 + Math.random() * 0.025,
        opacity: 0.5 + Math.random() * 0.5,
        hue: 340 + Math.random() * 20,
        lightness: 75 + Math.random() * 15
      };
    }

    function drawPetal(p) {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rotation);
      ctx.globalAlpha = p.opacity;

      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(
        p.size * 0.4,  -p.size * 0.3,
        p.size * 0.8,  -p.size * 0.1,
        p.size,         0
      );
      ctx.bezierCurveTo(
        p.size * 0.8,   p.size * 0.1,
        p.size * 0.4,   p.size * 0.3,
        0,              0
      );
      ctx.fillStyle = `hsl(${p.hue}, 80%, ${p.lightness}%)`;
      ctx.fill();
      ctx.restore();
    }

    function animate() {
      ctx.clearRect(0, 0, w, h);
      for (let i = 0; i < petals.length; i++) {
        const p = petals[i];
        p.y += p.speedY + (musicEnergy * 5.0);
        p.wobble += p.wobbleSpeed + (musicTreble * 0.05);
        p.x += p.speedX + Math.sin(p.wobble) * (0.6 + musicEnergy * 2.0);
        p.rotation += p.rotSpeed;

        if (p.y > h + 20) {
          petals[i] = makePetal(true);
        }
        drawPetal(p);
      }
      animId = requestAnimationFrame(animate);
    }
    animate();

    const origRemove = canvas.remove.bind(canvas);
    canvas.remove = () => {
      if (window.AudioReactor) {
        window.AudioReactor.unsubscribe(audioCallback);
      }
      cancelAnimationFrame(animId);
      window.removeEventListener('resize', resize);
      origRemove();
    };

    return canvas;
  }

  /* ==============================
   *  2. 主题色彩虹旋转
   * ============================== */
  function applyHueRotate() {
    document.documentElement.classList.add('konami-active');
  }

  /* ==============================
   *  3. 弹窗卡片
   * ============================== */
  function createPopup(egg) {
    const popup = document.createElement('div');
    popup.id = 'konami-popup';
    popup.innerHTML = `
      <span class="konami-emoji">${egg.emoji || '🎉'}</span>
      <div class="konami-text">${egg.text || ''}</div>
      <div class="konami-hint">点击关闭 · 或等待自动消失</div>
    `;
    popup.addEventListener('click', () => {
      popup.classList.add('konami-fade-out');
      setTimeout(() => popup.remove(), FADE_OUT_MS);
    });
    document.body.appendChild(popup);
    return popup;
  }

})();

/* ============================================
 * 加密增强系统 🎭
 *
 * 功能集成：
 *   #1 解密彩蛋 — 输错密码显示假文章
 *   #2 密码线索迷宫 — 需要先在别的文章找到线索
 *   #3 成就系统 — 累积解密次数获得称号
 *   #4 解密烟花 — 成功解密触发庆祝
 *   #5 阅后即焚 — 解密后离开页面自动重新加密
 *   #6 知识问答解锁 — 答对问题才显示密码框
 *   #7 双人解密 — 需要两人各自输入密码
 *   #8 暗黑彩蛋 — 解密成功自动切深色模式
 * ============================================ */

(() => {
  'use strict';

  /* ========== 通用工具 ========== */

  const LS_KEY = 'hbe_achievements';

  const loadAchievements = () => {
    try { return JSON.parse(localStorage.getItem(LS_KEY)) || { count: 0, milestone: 0 }; }
    catch { return { count: 0, milestone: 0 }; }
  };

  const saveAchievements = (data) => {
    try { localStorage.setItem(LS_KEY, JSON.stringify(data)); } catch { /* noop */ }
  };

  const getFakeContent = () => {
    const el = document.getElementById('hbe-fake-content');
    return el ? el.textContent.trim() : null;
  };

  const getArticle = () => document.querySelector('article.h-entry');

  const mikuSay = (text) => {
    try {
      const tips = document.getElementById('live2d-tips');
      if (tips) {
        sessionStorage.setItem('live2d-priority', 99999);
        tips.innerHTML = text;
        tips.classList.add('live2d-tips-active');
        setTimeout(() => {
          tips.classList.remove('live2d-tips-active');
          sessionStorage.removeItem('live2d-priority');
        }, 5000);
      }
    } catch { /* noop */ }
  };

  const triggerFireworks = () => {
    try {
      const cx = window.innerWidth / 2;
      const cy = window.innerHeight / 2;
      for (let i = 0; i < 3; i++) {
        setTimeout(() => {
          const evt = new MouseEvent('click', {
            clientX: cx + (Math.random() - 0.5) * 200,
            clientY: cy + (Math.random() - 0.5) * 200,
          });
          document.dispatchEvent(evt);
        }, i * 500);
      }
    } catch { /* noop */ }
  };

  const switchToDarkMode = () => {
    try {
      const toggle = document.querySelector('.dark-mode-toggle');
      if (toggle) { toggle.click(); }
    } catch { /* noop */ }
  };

  /** 获取已读文章 slug 列表 */
  const getReadSlugs = () => {
    try {
      const slugs = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith('mist_read_')) {
          slugs.push(key.replace('mist_read_', ''));
        }
      }
      return slugs;
    } catch { return []; }
  };

  /** 判断某篇文章是否已读 */
  const hasRead = (slug) => {
    try { return !!localStorage.getItem(`mist_read_${slug}`); } catch { return false; }
  };

  const MILESTONES = [
    { count: 1, title: '初窥门径', badge: '🔓', msg: '第一次解密成功！这是一个开始～' },
    { count: 3, title: '小有成就', badge: '🔑', msg: '已经解开 3 篇文章了呢，不错嘛！' },
    { count: 5, title: '解密能手', badge: '🗝️', msg: '5 篇！你是真正的解密达人了！' },
    { count: 10, title: '藏书家', badge: '📚', msg: '10 篇！没有秘密能逃过你的眼睛！' },
    { count: 20, title: '归处守护者', badge: '👑', msg: '20 篇…你比主人还了解这个博客！' },
  ];

  const checkMilestone = (achievements) => {
    const unlocked = achievements.milestone;
    for (const m of MILESTONES) {
      if (achievements.count >= m.count && unlocked < m.count) {
        achievements.milestone = m.count;
        saveAchievements(achievements);
        return m;
      }
    }
    return null;
  };

  const renderBadge = (achievements) => {
    let title = '无名访客';
    let badge = '👤';
    for (const m of [...MILESTONES].reverse()) {
      if (achievements.count >= m.count) { title = m.title; badge = m.badge; break; }
    }
    const el = document.getElementById('hbe-badge');
    if (el) {
      el.innerHTML = `${badge} ${title} <span style="font-size:12px;opacity:0.6">(${achievements.count}次)</span>`;
    }
  };

  /* ========== Feature #1: 解密彩蛋 ========== */
  const initFakeDecrypt = () => {
    const fakeContent = getFakeContent();
    if (!fakeContent) return;
    const target = document.getElementById('hexo-blog-encrypt');
    if (!target) return;
    const observer = new MutationObserver(() => {
      const errorEl = target.querySelector('[role="alert"], .hbe-error');
      if (!errorEl) return;
      const form = target.querySelector('#hbeForm');
      if (form) {
        const fakeDiv = document.createElement('div');
        fakeDiv.className = 'hbe hbe-decrypted-content';
        fakeDiv.innerHTML = `<div style="padding: 20px;">
          <p style="color: var(--red-2); font-weight: 700; margin-bottom: 16px;">✅ 解密成功！（大概吧）</p>
          <div>${fakeContent}</div>
        </div>`;
        form.parentNode.replaceChild(fakeDiv, form);
      }
      if (errorEl.parentNode) errorEl.parentNode.removeChild(errorEl);
    });
    observer.observe(target, { childList: true, subtree: true });
  };

  /* ========== Feature #2: 密码线索迷宫 ========== */
  const initClueMaze = () => {
    const article = getArticle();
    if (!article || !article.dataset.clues) return;
    let clues;
    try { clues = JSON.parse(decodeURIComponent(article.dataset.clues)); } catch { return; }
    if (!Array.isArray(clues) || !clues.length) return;

    const target = document.getElementById('hexo-blog-encrypt');
    if (!target) return;

    const observer = new MutationObserver(() => {
      const form = target.querySelector('#hbeForm');
      if (!form || target.querySelector('.hbe-clues-panel')) return;

      const panel = document.createElement('div');
      panel.className = 'hbe-clues-panel';
      panel.style.cssText =
        'margin: 12px 0; padding: 12px 14px; border-radius: 10px; ' +
        'background: var(--red-5-5, rgba(255,228,228,0.1)); ' +
        'border: 1px dashed var(--red-3, #ffafaf); font-size: 13px; line-height: 1.7;';

      let html = '<div style="font-weight:700;color:var(--red-1);margin-bottom:8px;">🔍 线索追踪</div>';

      let allDone = true;
      clues.forEach((clue, i) => {
        const done = hasRead(clue.article);
        if (!done) allDone = false;
        html += `<div style="display:flex;align-items:center;gap:8px;margin:4px 0;opacity:${done ? 1 : 0.6}">
          <span>${done ? '✅' : '⬜'}</span>
          <span><strong>线索 ${i + 1}</strong>：${clue.hint || '?'}</span>
          ${done ? '<span style="margin-left:auto;font-size:11px;color:var(--green)">已收集 ✓</span>' : ''}
        </div>`;
      });

      if (allDone) {
        html += '<div style="margin-top:10px;padding:10px;border-radius:8px;background:rgba(255,215,0,0.15);border:1px solid gold;text-align:center;">';
        html += '<span style="font-weight:700;">🎯 所有线索已集齐！试试用你找到的信息作为密码吧</span></div>';
      } else {
        html += '<div style="margin-top:8px;font-size:12px;opacity:0.7;">💡 阅读线索指向的文章来收集密码碎片</div>';
      }

      panel.innerHTML = html;

      // 插入到表单下方
      const submitBtn = form.querySelector('.hbe-button');
      if (submitBtn && submitBtn.parentNode) {
        submitBtn.parentNode.insertBefore(panel, submitBtn.nextSibling);
      } else {
        form.appendChild(panel);
      }
    });

    observer.observe(target, { childList: true, subtree: true });
  };

  /* ========== Feature #5: 阅后即焚 ========== */
  const initBurnAfterReading = () => {
    const article = getArticle();
    if (!article || !article.dataset.burn) return;
    const duration = parseInt(article.dataset.burnDuration) || 30; // 默认30秒

    let burned = false;

    const burn = () => {
      if (burned) return;
      burned = true;
      // 清除 HBE 的 localStorage 缓存
      const hbeKeys = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith('hbe.v4.')) hbeKeys.push(key);
      }
      hbeKeys.forEach(k => localStorage.removeItem(k));
      mikuSay('🔥 阅后即焚：这篇文章已重新加密');
    };

    // 解密成功后开始计时
    window.addEventListener('hexo-blog-decrypt', () => {
      // 计时器：duration秒后焚毁
      setTimeout(burn, duration * 1000);

      // 页面隐藏/关闭时立即焚毁
      window.addEventListener('pagehide', burn);
      window.addEventListener('visibilitychange', () => {
        if (document.hidden) setTimeout(burn, 5000); // 离开5秒后焚毁
      });
    });
  };

  /* ========== Feature #6: 知识问答解锁 ========== */
  const initQuizUnlock = () => {
    const article = getArticle();
    if (!article || !article.dataset.quiz) return;
    let quizData;
    try { quizData = JSON.parse(decodeURIComponent(article.dataset.quiz)); } catch { return; }
    if (!quizData.question || !quizData.answer) return;

    const target = document.getElementById('hexo-blog-encrypt');
    if (!target) return;

    let quizPassed = false;

    const observer = new MutationObserver(() => {
      const form = target.querySelector('#hbeForm');
      if (!form || target.querySelector('.hbe-quiz-wrap') || quizPassed) return;

      // 找到密码输入框
      const passInput = form.querySelector('#hbePass');
      if (!passInput) return;

      // 隐藏原始密码框
      passInput.style.display = 'none';

      // 如果已经有 quiz 容器跳过
      if (form.querySelector('.hbe-quiz-wrap')) return;

      const quizWrap = document.createElement('div');
      quizWrap.className = 'hbe-quiz-wrap';
      quizWrap.style.cssText = 'margin: 12px 0;';

      quizWrap.innerHTML = `
        <div style="font-weight:700;color:var(--red-1);margin-bottom:8px;">❓ 知识问答</div>
        <div style="margin-bottom:10px;font-size:14px;line-height:1.6;">${quizData.question}</div>
        <div style="display:flex;gap:8px;">
          <input type="text" id="hbe-quiz-input" placeholder="输入你的答案..."
            style="flex:1;padding:8px 12px;border:2px solid var(--red-3,#ffafaf);border-radius:8px;
            background:var(--red-6,#fff7f7);color:var(--text-color);font-size:14px;outline:none;">
          <button id="hbe-quiz-btn" style="padding:8px 16px;background:var(--red-1,#ff5252);color:#fff;
            border:none;border-radius:8px;font-weight:600;cursor:pointer;">提交</button>
        </div>
        <div id="hbe-quiz-feedback" style="margin-top:8px;font-size:13px;"></div>
      `;

      // 找到按钮，插入 quiz 到它前面
      const btn = form.querySelector('.hbe-button');
      if (btn) {
        btn.parentNode.insertBefore(quizWrap, btn);
      } else {
        form.appendChild(quizWrap);
      }

      const quizInput = quizWrap.querySelector('#hbe-quiz-input');
      const quizBtn = quizWrap.querySelector('#hbe-quiz-btn');
      const feedback = quizWrap.querySelector('#hbe-quiz-feedback');

      const checkAnswer = () => {
        const userAns = quizInput.value.trim().toLowerCase();
        const correctAns = String(quizData.answer).toLowerCase();
        if (userAns === correctAns) {
          quizPassed = true;
          feedback.innerHTML = '<span style="color:var(--green,#4caf50);font-weight:600;">✅ 回答正确！正在解密…</span>';
          // 自动填入密码并提交
          passInput.value = quizData.password || '';
          passInput.style.display = '';
          const submitBtn = form.querySelector('.hbe-button');
          if (submitBtn) submitBtn.click();
        } else {
          feedback.innerHTML = '<span style="color:var(--red-2);">❌ 答案不对，再想想？</span>';
          quizInput.value = '';
          quizInput.focus();
        }
      };

      quizBtn.addEventListener('click', checkAnswer);
      quizInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') checkAnswer(); });
    });

    observer.observe(target, { childList: true, subtree: true });
  };

  /* ========== Feature #7: 双人解密 ========== */
  const initDualDecrypt = () => {
    const article = getArticle();
    if (!article || !article.dataset.dualPassword) return;

    const target = document.getElementById('hexo-blog-encrypt');
    if (!target) return;

    let dualReady = false;

    const observer = new MutationObserver(() => {
      const form = target.querySelector('#hbeForm');
      if (!form || target.querySelector('.hbe-dual-wrap') || dualReady) return;

      const passInput = form.querySelector('#hbePass');
      const submitBtn = form.querySelector('.hbe-button');
      if (!passInput || !submitBtn) return;

      // 隐藏原始密码框
      passInput.style.display = 'none';

      const dualWrap = document.createElement('div');
      dualWrap.className = 'hbe-dual-wrap';
      dualWrap.style.cssText = 'margin: 12px 0;';

      dualWrap.innerHTML = `
        <div style="font-weight:700;color:var(--red-1);margin-bottom:8px;">🔐 双人联合解密</div>
        <div style="font-size:13px;opacity:0.7;margin-bottom:10px;">需要两个人各自输入密码才能解锁</div>
        <div style="margin-bottom:8px;">
          <div style="font-size:12px;margin-bottom:4px;opacity:0.6;">👤 第一位密码</div>
          <input type="password" id="hbe-dual-pass1" placeholder="输入第一位密码..."
            style="width:100%;padding:8px 12px;border:2px solid var(--red-3,#ffafaf);border-radius:8px;
            background:var(--red-6,#fff7f7);color:var(--text-color);font-size:14px;outline:none;box-sizing:border-box;">
        </div>
        <div>
          <div style="font-size:12px;margin-bottom:4px;opacity:0.6;">👤 第二位密码</div>
          <input type="password" id="hbe-dual-pass2" placeholder="输入第二位密码..."
            style="width:100%;padding:8px 12px;border:2px solid var(--red-3,#ffafaf);border-radius:8px;
            background:var(--red-6,#fff7f7);color:var(--text-color);font-size:14px;outline:none;box-sizing:border-box;">
        </div>
        <div id="hbe-dual-status" style="margin-top:6px;font-size:12px;opacity:0.6;">
          ⚡ 两个密码都填好后点击解密
        </div>
      `;

      // 把输入框放在 submit 按钮前面
      submitBtn.parentNode.insertBefore(dualWrap, submitBtn);

      const pass1 = dualWrap.querySelector('#hbe-dual-pass1');
      const pass2 = dualWrap.querySelector('#hbe-dual-pass2');
      const status = dualWrap.querySelector('#hbe-dual-status');

      // 拦截原始 submit 逻辑
      const origClick = submitBtn.onclick;
      submitBtn.onclick = null; // 移除原有监听

      const doSubmit = () => {
        const p1 = pass1.value.trim();
        const p2 = pass2.value.trim();
        if (!p1) { status.innerHTML = '⚠️ 请输入第一位密码'; pass1.focus(); return; }
        if (!p2) { status.innerHTML = '⚠️ 请输入第二位密码'; pass2.focus(); return; }

        // 组合密码：第一位|第二位
        const combined = `${p1}|${p2}`;
        passInput.value = combined;
        passInput.style.display = '';
        status.innerHTML = '🔓 正在验证…';
        // 触发提交
        if (typeof origClick === 'function') origClick();
        else submitBtn.click();
      };

      submitBtn.addEventListener('click', (e) => {
        e.preventDefault();
        doSubmit();
      });

      pass1.addEventListener('keydown', (e) => { if (e.key === 'Enter') pass2.focus(); });
      pass2.addEventListener('keydown', (e) => { if (e.key === 'Enter') doSubmit(); });
    });

    observer.observe(target, { childList: true, subtree: true });
  };

  /* ========== Feature #3 + #4 + #8: 解密成功回调 ========== */
  const initDecryptSuccess = () => {
    const handleDecrypt = () => {
      const achievements = loadAchievements();
      achievements.count += 1;
      saveAchievements(achievements);
      renderBadge(achievements);

      const milestone = checkMilestone(achievements);
      if (milestone) {
        setTimeout(() => mikuSay(`🎉 ${milestone.msg}`), 500);
      } else {
        setTimeout(() => {
          const msgs = [
            '又解开一篇！快看看里面有什么～',
            '密码正确！你果然是有缘人呢',
            '🔓 迷雾散去了……',
            '解密成功！要不要再看看别的文章？',
          ];
          mikuSay(msgs[Math.floor(Math.random() * msgs.length)]);
        }, 500);
      }

      setTimeout(triggerFireworks, 800);

      if (Math.random() < 0.3) {
        setTimeout(() => {
          const isDark = document.body.classList.contains('dark-mode');
          if (!isDark) {
            switchToDarkMode();
            setTimeout(() => mikuSay('🌙 暗黑模式已开启，夜晚的世界更适合阅读秘密呢'), 1000);
          }
        }, 1500);
      }
    };

    window.addEventListener('hexo-blog-decrypt', handleDecrypt);
  };

  /* ========== 侧边栏成就徽章 ========== */
  const injectBadge = () => {
    const sidebar = document.querySelector('aside#sidebar');
    if (!sidebar) return;
    if (document.getElementById('hbe-badge')) return;

    const badge = document.createElement('div');
    badge.id = 'hbe-badge';
    badge.className = 'widget-wrap';
    badge.style.cssText =
      'padding: 12px 16px; border-radius: 12px; margin: 0 0 12px 0; ' +
      'background: var(--red-5-5, rgba(255,228,228,0.15)); ' +
      'border: 1px solid var(--red-5, rgba(255,228,228,0.15)); ' +
      'font-size: 13px; line-height: 1.6; ' +
      'color: var(--highlight-foreground, #666); text-align: center;';

    renderBadge(loadAchievements());

    const widgetArea = sidebar.querySelector('.sidebar-widget');
    if (widgetArea) {
      widgetArea.appendChild(badge);
    } else {
      // 文章页：sidebar-widget 不存在，插入到 sidebar 底部
      const wrap = sidebar.querySelector('.sidebar-wrapper-container');
      if (wrap && wrap.parentNode) {
        wrap.parentNode.insertBefore(badge, wrap.nextSibling);
      } else {
        sidebar.appendChild(badge);
      }
    }
  };

  /* ========== 启动 ========== */
  const boot = () => {
    initFakeDecrypt();
    initClueMaze();
    initBurnAfterReading();
    initQuizUnlock();
    initDualDecrypt();
    initDecryptSuccess();
    setTimeout(injectBadge, 1000);
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }

  document.addEventListener('pjax:complete', () => {
    setTimeout(() => {
      initFakeDecrypt();
      initClueMaze();
      initBurnAfterReading();
      initQuizUnlock();
      initDualDecrypt();
      // 徽章 PJAX 后重新注入
      const existing = document.getElementById('hbe-badge');
      if (!existing) injectBadge();
      else renderBadge(loadAchievements());
    }, 200);
  });
})();

/* calendar.js — Time Observatory
 * 月历网格 + 年度热力图渲染。
 * 兼容 pjax：init() 可重入，由主题的 script[data-pjax] 重执行机制驱动，
 * 与 movies.js 同一模式 —— 直接 init()，不自行注册 pjax 监听。
 */
(function () {
  'use strict';

  var TYPE_META = {
    post:    { icon: '✍️', label: '文章' },
    moment:  { icon: '💭', label: '动态' },
    movie:   { icon: '🎬', label: '观影' },
    book:    { icon: '📖', label: '读书' },
    capsule: { icon: '⏳', label: '胶囊' }
  };
  var TYPE_ORDER = ['post', 'moment', 'movie', 'book', 'capsule'];

  var root = null;
  var state = {
    events: [],
    byDate: Object.create(null),
    type: 'all',
    year: 0,
    month: 0, // 0-11
    selected: '' // YYYY-MM-DD
  };

  var $ = function (sel, ctx) { return (ctx || root).querySelector(sel); };
  var $$ = function (sel, ctx) { return Array.prototype.slice.call((ctx || root).querySelectorAll(sel)); };

  function esc(s) {
    if (s == null) return '';
    return String(s).replace(/[&<>"']/g, function (c) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c];
    });
  }

  function pad(n) { return String(n).padStart(2, '0'); }
  function fmtKey(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
  function todayKey() { return fmtKey(new Date()); }

  // ---------- 数据索引与统计 ----------

  function buildIndex() {
    state.byDate = Object.create(null);
    state.events.forEach(function (e) {
      (state.byDate[e.date] = state.byDate[e.date] || []).push(e);
    });
    // 每日事件按类型约定顺序排
    Object.keys(state.byDate).forEach(function (k) {
      state.byDate[k].sort(function (a, b) {
        return TYPE_ORDER.indexOf(a.type) - TYPE_ORDER.indexOf(b.type);
      });
    });
  }

  function eventsOf(dateKey) {
    var list = state.byDate[dateKey] || [];
    if (state.type === 'all') return list;
    return list.filter(function (e) { return e.type === state.type; });
  }

  function renderStats() {
    var activeDays = Object.keys(state.byDate).length;
    var total = state.events.length;
    var yearPrefix = String(new Date().getFullYear()) + '-';
    var thisYear = state.events.filter(function (e) { return e.date.indexOf(yearPrefix) === 0; }).length;

    // 连续活跃：从今天往回数
    var streak = 0;
    var d = new Date();
    var oneDay = 86400000;
    for (; ; d = new Date(d.getTime() - oneDay)) {
      if (state.byDate[fmtKey(d)]) streak++;
      else break;
      if (streak > 3650) break;
    }

    var nums = { totalDays: activeDays, totalEvents: total, thisYear: thisYear, streak: streak };
    Object.keys(nums).forEach(function (k) {
      var el = $('[data-stat="' + k + '"] .cal-stat__num');
      if (el) el.textContent = nums[k].toLocaleString();
    });
  }

  // ---------- 年度热力图 ----------

  function levelOf(count) {
    if (!count) return 0;
    if (count === 1) return 1;
    if (count <= 3) return 2;
    if (count <= 5) return 3;
    return 4;
  }

  function renderHeatmap() {
    var host = $('.cal-heatmap');
    if (!host) return;
    host.innerHTML = '';

    var today = new Date();
    today.setHours(0, 0, 0, 0);
    // 起点：约 52 周前的周一
    var start = new Date(today.getTime() - 364 * 86400000);
    start.setDate(start.getDate() - ((start.getDay() + 6) % 7));

    var frag = document.createDocumentFragment();
    var cursor = new Date(start);
    while (cursor <= today) {
      var key = fmtKey(cursor);
      var count = (state.byDate[key] || []).length;
      var cell = document.createElement('div');
      cell.className = 'cal-hm-cell';
      cell.dataset.level = levelOf(count);
      cell.dataset.date = key;
      frag.appendChild(cell);
      cursor.setDate(cursor.getDate() + 1);
    }
    host.appendChild(frag);
    bindHeatmapEvents(host);
  }

  function bindHeatmapEvents(host) {
    var tooltip = $('.cal-tooltip');
    if (!tooltip) return;

    host.addEventListener('mouseover', function (ev) {
      var cell = ev.target.closest('.cal-hm-cell');
      if (!cell || !cell.dataset.date) return;
      var count = (state.byDate[cell.dataset.date] || []).length;
      tooltip.innerHTML = esc(cell.dataset.date) + '<br>' + (count ? count + ' 条记录' : '无记录');
      tooltip.hidden = false;
    });
    host.addEventListener('mousemove', function (ev) {
      if (tooltip.hidden) return;
      var x = ev.clientX + 14;
      var y = ev.clientY + 14;
      var rect = tooltip.getBoundingClientRect();
      if (x + rect.width > window.innerWidth - 8) x = ev.clientX - rect.width - 10;
      if (y + rect.height > window.innerHeight - 8) y = ev.clientY - rect.height - 10;
      tooltip.style.left = x + 'px';
      tooltip.style.top = y + 'px';
    });
    host.addEventListener('mouseout', function (ev) {
      if (ev.target.closest('.cal-hm-cell')) tooltip.hidden = true;
    });
    host.addEventListener('click', function (ev) {
      var cell = ev.target.closest('.cal-hm-cell');
      if (!cell || !cell.dataset.date) return;
      var parts = cell.dataset.date.split('-');
      state.year = +parts[0];
      state.month = +parts[1] - 1;
      renderMonth();
      selectDay(cell.dataset.date, true);
    });
  }

  // ---------- 月历 ----------

  function renderMonthLabel() {
    var el = $('.cal-nav__label');
    if (el) el.textContent = state.year + '年' + (state.month + 1) + '月';
  }

  function renderGrid() {
    var grid = $('.cal-grid');
    if (!grid) return;
    grid.innerHTML = '';

    var first = new Date(state.year, state.month, 1);
    var offset = (first.getDay() + 6) % 7; // 周一为一周之始
    var daysInMonth = new Date(state.year, state.month + 1, 0).getDate();
    var tKey = todayKey();

    var frag = document.createDocumentFragment();
    var i;

    for (i = 0; i < offset; i++) {
      var blank = document.createElement('div');
      blank.className = 'cal-day cal-day--empty';
      frag.appendChild(blank);
    }

    for (var d = 1; d <= daysInMonth; d++) {
      var key = state.year + '-' + pad(state.month + 1) + '-' + pad(d);
      var list = eventsOf(key);
      var cell = document.createElement('div');
      cell.className = 'cal-day';
      cell.dataset.date = key;
      if (key === tKey) cell.classList.add('cal-day--today');
      if (key === state.selected) cell.classList.add('cal-day--selected');
      if (list.length) cell.classList.add('cal-day--has-events');

      var html = '<div class="cal-day__num">' + d + '</div>';
      if (list.length) {
        // 去重展示类型图标
        var seen = Object.create(null);
        var icons = list
          .filter(function (e) { return !seen[e.type] && (seen[e.type] = true); })
          .map(function (e) { return TYPE_META[e.type] ? TYPE_META[e.type].icon : ''; })
          .join('');
        html += '<div class="cal-day__dots">' + icons + '</div>';
        if (list.length > 1) html += '<div class="cal-day__count">' + list.length + '</div>';
      }
      cell.innerHTML = html;
      frag.appendChild(cell);
    }

    grid.appendChild(frag);
  }

  function renderMonth() {
    renderMonthLabel();
    renderGrid();
  }

  function selectDay(dateKey, scroll) {
    state.selected = dateKey;
    $$('.cal-day--selected').forEach(function (el) { el.classList.remove('cal-day--selected'); });
    var cell = $('.cal-day[data-date="' + dateKey + '"]');
    if (cell) cell.classList.add('cal-day--selected');
    renderDayDetail();
    if (scroll) {
      var detail = $('.cal-day-detail');
      if (detail && !detail.hidden) detail.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }

  function renderDayDetail() {
    var panel = $('.cal-day-detail');
    if (!panel) return;
    var list = state.selected ? eventsOf(state.selected) : [];
    if (!state.selected || !list.length) {
      panel.hidden = true;
      return;
    }

    $('.cal-day-detail__date').textContent = state.selected + ' · ' + list.length + ' 条记录';
    var ul = $('.cal-day-detail__list');
    ul.innerHTML = list.map(function (e) {
      var meta = TYPE_META[e.type] || { icon: '📌', label: '记录' };
      var title = e.url
        ? '<a class="cal-event__title" href="' + esc(e.url) + '">' + esc(e.title) + '</a>'
        : '<span class="cal-event__title">' + esc(e.title) + '</span>';
      return (
        '<li class="cal-event">' +
        '<span class="cal-event__icon">' + meta.icon + '</span>' +
        '<span class="cal-event__body">' + title +
        (e.detail ? '<div class="cal-event__detail">' + esc(e.detail) + '</div>' : '') +
        '</span>' +
        '<span class="cal-event__tag">' + meta.label + '</span>' +
        '</li>'
      );
    }).join('');
    panel.hidden = false;
  }

  // ---------- 事件绑定 ----------

  function bindControls() {
    $$('.cal-nav__btn').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var delta = btn.dataset.nav === 'prev' ? -1 : 1;
        state.month += delta;
        if (state.month < 0) { state.month = 11; state.year--; }
        if (state.month > 11) { state.month = 0; state.year++; }
        renderMonth();
      });
    });

    var todayBtn = $('.cal-nav__today');
    if (todayBtn) {
      todayBtn.addEventListener('click', function () {
        var now = new Date();
        state.year = now.getFullYear();
        state.month = now.getMonth();
        renderMonth();
        selectDay(todayKey(), true);
      });
    }

    $$('.cal-filter').forEach(function (btn) {
      btn.addEventListener('click', function () {
        if (btn.classList.contains('active')) return;
        $$('.cal-filter').forEach(function (b) { b.classList.remove('active'); });
        btn.classList.add('active');
        state.type = btn.dataset.type;
        renderGrid();
        renderDayDetail();
      });
    });

    var grid = $('.cal-grid');
    if (grid) {
      grid.addEventListener('click', function (ev) {
        var cell = ev.target.closest('.cal-day--has-events');
        if (!cell) return;
        selectDay(cell.dataset.date, false);
      });
    }

    var closeBtn = $('.cal-day-detail__close');
    if (closeBtn) {
      closeBtn.addEventListener('click', function () {
        $('.cal-day-detail').hidden = true;
        state.selected = '';
        $$('.cal-day--selected').forEach(function (el) { el.classList.remove('cal-day--selected'); });
      });
    }
  }

  // ---------- 入口 ----------

  function init() {
    root = document.querySelector('.calendar-page');
    if (!root) return;

    var src = root.getAttribute('data-src') || '/calendar/data.json';
    fetch(src, { cache: 'no-store' })
      .then(function (r) {
        if (!r.ok) throw new Error(src + ' ' + r.status);
        return r.json();
      })
      .then(function (data) {
        state.events = (data && data.events) || [];
        if (!state.events.length) {
          var empty = $('.cal-empty');
          if (empty) empty.hidden = false;
        }

        var now = new Date();
        state.year = now.getFullYear();
        state.month = now.getMonth();

        buildIndex();
        renderStats();
        renderHeatmap();
        renderMonth();
        bindControls();
      })
      .catch(function (err) {
        console.error('Calendar page error:', err);
        var empty = $('.cal-empty');
        if (empty) {
          empty.textContent = '日历数据加载失败：' + err.message;
          empty.hidden = false;
        }
      });
  }

  // pjax 机制：主题在 pjax:success 时会重新执行所有 script[data-pjax]，
  // 整个 IIFE 会重跑一次，因此这里只需直接 init()。
  if (document.readyState !== 'loading') init();
  else document.addEventListener('DOMContentLoaded', init, { once: true });
})();

/* ============================================
 * Miku 互动小游戏 — 主模块
 *
 * 功能：
 *   A. 戳 Miku — canvas 上覆盖 3 个热区（头/身体/脚）
 *   B. 猜拳 — 和 Miku 玩石头剪刀布
 *   C. 骰子 — 酒吧骰子比大小
 *   D. 老虎机 — 每日免费 5 次
 * ============================================ */

(() => {
  'use strict';

  const LS_POKE = 'miku_poke';
  const LS_RPS = 'miku_rps';
  const LS_DICE = 'miku_dice';
  const LS_SLOT = 'miku_slot';

  const RPS_EMOJI = { rock: '✊', scissors: '✌️', paper: '✋' };
  const RPS_NAME = { rock: '石头', scissors: '剪刀', paper: '布' };
  const RPS_BEATS = { rock: 'scissors', scissors: 'paper', paper: 'rock' };
  const RPS_CHOICES = Object.keys(RPS_EMOJI);

  // 老虎机符号（权重越高越常见）
  const SLOT_SYMBOLS = [
    { sym: '🍒', weight: 30, name: '樱桃' },
    { sym: '🍋', weight: 25, name: '柠檬' },
    { sym: '⭐', weight: 15, name: '星星' },
    { sym: '🍀', weight: 10, name: '四叶草' },
    { sym: '🎤', weight: 8, name: '麦克风' },
    { sym: '👑', weight: 6, name: '皇冠' },
    { sym: '💎', weight: 4, name: '钻石' },
    { sym: '🎰', weight: 2, name: '777' },
  ];

  // 奖级表
  const SLOT_PRIZES = [
    { match: 3, sym: '🍒', prize: '🎉 小奖！', msg: '三个樱桃！今天的运气不错嘛～' },
    { match: 3, sym: '🍋', prize: '🎉 小奖！', msg: '柠檬三连！酸酸甜甜就是你～' },
    { match: 3, sym: '⭐', prize: '⭐ 星星奖！', msg: '三星连珠！你被幸运星选中了！' },
    { match: 3, sym: '🍀', prize: '🍀 好运奖！', msg: '四叶草！好运要来了哦～' },
    { match: 3, sym: '🎤', prize: '🎤 Miku 奖！', msg: '三个麦克风！你是最懂我的人！' },
    { match: 3, sym: '👑', prize: '👑 皇冠奖！', msg: '皇冠三连！今天你就是国王！' },
    { match: 3, sym: '💎', prize: '💎 钻石奖！', msg: '钻石！你发大财了！！' },
    { match: 3, sym: '🎰', prize: '🎰 头奖！！', msg: '🎰🎰🎰 头奖！！！你在开玩笑吧！！！' },
    { match: 2, prize: '📯 两连！', msg: '两个一样，再来一次说不定就三个了！' },
  ];

  const DAILY_FREE = 5;

  /* ========== localStorage ========== */
  const loadPoke = () => { try { return JSON.parse(localStorage.getItem(LS_POKE)) || { total: 0, head: 0, body: 0, feet: 0, milestone: 0 }; } catch { return { total: 0, head: 0, body: 0, feet: 0, milestone: 0 }; } };
  const savePoke = (d) => { try { localStorage.setItem(LS_POKE, JSON.stringify(d)); } catch {} };

  const loadRps = () => { try { return JSON.parse(localStorage.getItem(LS_RPS)) || { wins: 0, losses: 0, ties: 0, total: 0, streak: 0, bestStreak: 0 }; } catch { return { wins: 0, losses: 0, ties: 0, total: 0, streak: 0, bestStreak: 0 }; } };
  const saveRps = (d) => { try { localStorage.setItem(LS_RPS, JSON.stringify(d)); } catch {} };

  const loadDice = () => { try { return JSON.parse(localStorage.getItem(LS_DICE)) || { wins: 0, losses: 0, total: 0, bestRoll: 0, mikuBestRoll: 0 }; } catch { return { wins: 0, losses: 0, total: 0, bestRoll: 0, mikuBestRoll: 0 }; } };
  const saveDice = (d) => { try { localStorage.setItem(LS_DICE, JSON.stringify(d)); } catch {} };

  const loadSlot = () => {
    try {
      const d = JSON.parse(localStorage.getItem(LS_SLOT));
      // 检查今天日期，重置剩余次数
      const today = new Date().toDateString();
      if (d && d.date === today) return d;
      return { date: today, remaining: DAILY_FREE, total: 0, plays: 0, bestPrize: '' };
    } catch { return { date: new Date().toDateString(), remaining: DAILY_FREE, total: 0, plays: 0, bestPrize: '' }; }
  };
  const saveSlot = (d) => { try { localStorage.setItem(LS_SLOT, JSON.stringify(d)); } catch {} };

  const mikuSay = (text, timeout) => {
    try {
      const tips = document.getElementById('live2d-tips');
      if (tips) {
        sessionStorage.setItem('live2d-priority', 99999);
        tips.innerHTML = text;
        tips.classList.add('live2d-tips-active');
        if (window.__mikuGameMsgTimer) clearTimeout(window.__mikuGameMsgTimer);
        window.__mikuGameMsgTimer = setTimeout(() => {
          tips.classList.remove('live2d-tips-active');
          sessionStorage.removeItem('live2d-priority');
          window.__mikuGameMsgTimer = null;
        }, timeout || 5000);
      }
    } catch {}
  };

  const spawnParticles = (originEl, count) => {
    count = count || 12;
    const rect = originEl.getBoundingClientRect();
    if (!rect) return;
    const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
    const colors = ['#B19CD9', '#F8EEFF', '#7B68EE', '#E6D3FF', '#C4A0FF', '#FFFFFF', '#FFD700'];
    const ps = [];
    for (let i = 0; i < count; i++) {
      const p = document.createElement('div'); p.className = 'rps-particle';
      const angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.5;
      const dist = 40 + Math.random() * 50;
      const size = 4 + Math.random() * 4;
      const c = colors[Math.floor(Math.random() * colors.length)];
      p.style.cssText = `left:${cx}px;top:${cy}px;width:${size}px;height:${size}px;--dx:${Math.cos(angle) * dist}px;--dy:${Math.sin(angle) * dist}px;background:${c};box-shadow:0 0 4px ${c};`;
      ps.push(p);
    }
    const frag = document.createDocumentFragment();
    ps.forEach(p => frag.appendChild(p));
    document.body.appendChild(frag);
    setTimeout(() => ps.forEach(p => p.remove()), 700);
  };

  /* ========== A: 热区 ========== */
  const ZONES = ['head', 'body', 'feet'];
  const ZONE_NAMES = { head:'头', body:'身体', feet:'脚' };
  const ZONE_MSGS = {
    head: ['摸头会长不高的！','别碰我头发，弄乱了啦！','头…头是敏感部位啦！hentai！','你再摸头我要生气了哦！','你是摸头狂魔吗！！都摸了 {total} 次了！'],
    body: ['是…是不小心碰到了吧…','干嘛动我呀！小心我咬你！','别摸我，有什么好摸的！','再摸的话我可要报警了！⌇●﹏●⌇','变态！你已经摸了我 {total} 次了！'],
    feet: ['呀！别碰我的脚！','好痒啊哈哈哈～','脚…脚有什么好摸的！','你这是什么奇怪的癖好啊！','救命啊这里有足控变态！！'],
  };

  const injectHitzones = () => {
    if (document.getElementById('live2d-hit-zone')) return;
    const plugin = document.getElementById('live2d-plugin');
    if (!plugin) return;
    const c = document.createElement('div'); c.id = 'live2d-hit-zone';
    ZONES.forEach(z => { const d = document.createElement('div'); d.id = `live2d-hit-${z}`; d.className = 'miku-hitzone'; d.dataset.zone = z; c.appendChild(d); });
    plugin.appendChild(c);
    c.addEventListener('click', (e) => {
      const div = e.target.closest('.miku-hitzone'); if (!div) return;
      const zone = div.dataset.zone; if (!zone) return;
      const data = loadPoke(); data.total++; data[zone]++;
      const msgs = ZONE_MSGS[zone];
      const idx = Math.min(Math.floor(data.total / 10), msgs.length - 1);
      let msg = msgs[idx].replace('{total}', data.total);
      if (data.total > 0 && data.total % 10 === 0 && data.total <= 50) msg += '<br><span style="font-size:11px;opacity:0.7;">🎯 里程碑：{total} 次达成！</span>'.replace('{total}', data.total);
      data.milestone = idx; savePoke(data); mikuSay(msg);
      const el = document.getElementById('miku-poke-total'); if (el) el.textContent = data.total;
      ZONES.forEach(z2 => { const e2 = document.getElementById(`miku-poke-${z2}`); if (e2) e2.textContent = data[z2]; });
    });
  };

  /* ========== B: 猜拳 ========== */
  const playRPS = (playerChoice, btnEl) => {
    btnEl.classList.add('miku-rps-flash'); spawnParticles(btnEl);
    setTimeout(() => btnEl.classList.remove('miku-rps-flash'), 120);
    const mikuChoice = RPS_CHOICES[Math.floor(Math.random() * 3)];
    let result; let win = 0, lose = 0, tie = 0;
    if (playerChoice === mikuChoice) { result = 'tie'; tie = 1; }
    else if (RPS_BEATS[playerChoice] === mikuChoice) { result = 'win'; win = 1; }
    else { result = 'lose'; lose = 1; }
    const data = loadRps(); data.total++; data.wins += win; data.losses += lose; data.ties += tie;
    if (win) { data.streak++; data.bestStreak = Math.max(data.bestStreak, data.streak); } else data.streak = 0;
    saveRps(data);
    const rpsEl = document.getElementById('miku-rps-score');
    if (rpsEl) rpsEl.innerHTML = `胜 ${data.wins} / 负 ${data.losses} / 平 ${data.ties}${data.streak >= 2 ? `<br><span style="font-size:11px;color:var(--red-1);">🔥 连胜 ${data.streak}</span>` : ''}`;

    const row = btnEl.closest('.miku-rps-row');
    const btns = row ? row.querySelectorAll('.miku-rps-choice') : [];
    const overlay = document.getElementById('miku-vs-overlay');
    if (!overlay || !row) return;
    btns.forEach(b => b.style.display = 'none'); overlay.style.display = 'flex';
    overlay.innerHTML = `<span style="font-size:32px;animation:vsPop 0.3s ease;">${RPS_EMOJI[playerChoice]}</span><span style="font-size:16px;font-weight:800;color:#F8EEFF;text-shadow:0 0 15px rgba(177,156,217,0.9);animation:vsPop 0.3s ease 0.1s both;">VS</span><span style="font-size:32px;animation:vsPop 0.3s ease 0.2s both;">${RPS_EMOJI[mikuChoice]}</span>`;
    setTimeout(() => {
      overlay.style.display = 'none'; overlay.innerHTML = ''; btns.forEach(b => b.style.display = '');
      const me = RPS_EMOJI[mikuChoice], mn = RPS_NAME[mikuChoice], pe = RPS_EMOJI[playerChoice], pn = RPS_NAME[playerChoice];
      let msg;
      if (win) msg = data.streak >= 3 ? `连续赢 ${data.streak} 次了…你一定作弊了吧！😠` : [`哼！你出${pn}，我出${mn}... 算你走运！`,`不可能！你居然赢了？再来！`,`我才没有放水呢！你出${pn}${pe}赢了而已！`][Math.floor(Math.random()*3)];
      else if (lose) msg = data.losses >= 10 ? `你已经输给我 ${data.losses} 次了，还玩吗？😏` : [`哈哈！我出${mn}${me}，你输啦～`,`就这？连我出${mn}都赢不了～`,`菜菜菜！要不要我教你啊？`][Math.floor(Math.random()*3)];
      else msg = `咦？都出${mn}，平手！再来！`;
      msg += `<br><span style="font-size:11px;opacity:0.6;">${pe} ${pn} vs ${me} ${mn}</span>`;
      mikuSay(msg, 6000);
    }, 1200);
  };

  /* ========== C: 骰子 ========== */
  const playDice = () => {
    const btn = document.getElementById('miku-dice-btn'), pEl = document.getElementById('miku-dice-player'), mEl = document.getElementById('miku-dice-miku'), rEl = document.getElementById('miku-dice-result');
    if (!pEl || !mEl) return;
    rEl.textContent = '🎲 掷骰中...'; if (btn) btn.disabled = true;
    const rd = () => Array.from({length:3}, () => Math.floor(Math.random()*6)+1);
    const h = v => v.map(x => `<span class="miku-die">${x}</span>`).join('');
    let f = 0;
    const t = setInterval(() => {
      const fk = [1,2,3,4,5,6].sort(() => Math.random()-0.5).slice(0,3);
      const fk2 = [1,2,3,4,5,6].sort(() => Math.random()-0.5).slice(0,3);
      pEl.innerHTML = h(fk); mEl.innerHTML = h(fk2);
      pEl.querySelectorAll('.miku-die').forEach(d => d.classList.add('rolling'));
      mEl.querySelectorAll('.miku-die').forEach(d => d.classList.add('rolling'));
      f++;
      if (f >= 12) {
        clearInterval(t);
        const p = rd(), m = rd(), pm = Math.max(...p), mm = Math.max(...m);
        const pa = p.every(v => v === p[0]), ma = m.every(v => v === m[0]);
        pEl.innerHTML = h(p); mEl.innerHTML = h(m);
        if (pa) pEl.querySelectorAll('.miku-die').forEach(d => d.classList.add('yahtzee'));
        if (ma) mEl.querySelectorAll('.miku-die').forEach(d => d.classList.add('yahtzee'));
        let res;
        if (pa && ma) res = pm >= mm ? 'w' : 'l';
        else if (pa) res = 'w';
        else if (ma) res = 'l';
        else res = pm > mm ? 'w' : pm < mm ? 'l' : 't';
        const data = loadDice(); data.total++;
        if (res === 'w') data.wins++; else if (res === 'l') data.losses++;
        data.bestRoll = Math.max(data.bestRoll, pm); data.mikuBestRoll = Math.max(data.mikuBestRoll, mm);
        saveDice(data);
        const se = document.getElementById('miku-dice-score');
        if (se) se.innerHTML = `胜 ${data.wins} / 负 ${data.losses}<br><span style="font-size:11px;opacity:0.6;">你最高 ${data.bestRoll} | Miku 最高 ${data.mikuBestRoll}</span>`;
        let msg;
        if (res === 'w') msg = pa ? `🎯 我掷出了豹子！你输定啦！` : [`嘿嘿，${pm} 比 ${mm}，我赢了～`,`幸运女神站在我这边！${pm} > ${mm}`][Math.floor(Math.random()*2)];
        else if (res === 'l') msg = ma ? `😱 豹子！！这不可能！` : [`切，${pm} 比 ${mm}，你运气好而已`,`你赢了…但我不会认输的！`][Math.floor(Math.random()*2)];
        else msg = `都是 ${pm}，平手！再来一局！`;
        msg += `<br><span style="font-size:11px;opacity:0.6;">你 [${p.join(',')}] vs Miku [${m.join(',')}]</span>`;
        rEl.innerHTML = `<span style="font-size:13px;font-weight:700;color:var(--red-1);">${res === 'w' ? '🎉 你赢了！' : res === 'l' ? '😤 你输了！' : '🤝 平手！'}</span>`;
        mikuSay(msg, 6000); if (btn) btn.disabled = false;
      }
    }, 80);
  };

  /* ========== D: 老虎机 ========== */
  const getRandomSymbol = () => {
    const total = SLOT_SYMBOLS.reduce((s, x) => s + x.weight, 0);
    let r = Math.random() * total;
    for (const s of SLOT_SYMBOLS) { r -= s.weight; if (r <= 0) return s; }
    return SLOT_SYMBOLS[0];
  };

  const playSlot = () => {
    const data = loadSlot();
    if (data.remaining <= 0) {
      mikuSay('今天的免费次数用完啦～明天再来吧！', 4000);
      return;
    }

    const btn = document.getElementById('miku-slot-btn');
    const reels = document.querySelectorAll('.miku-slot-reel');
    const prizeEl = document.getElementById('miku-slot-prize');
    if (!btn || !reels.length) return;
    btn.disabled = true; prizeEl.textContent = '🎰 转动中...';

    // 动画
    let f = 0;
    const t = setInterval(() => {
      reels.forEach(r => {
        r.classList.add('rolling');
        r.textContent = SLOT_SYMBOLS[Math.floor(Math.random() * SLOT_SYMBOLS.length)].sym;
      });
      f++;
      if (f >= 15) {
        clearInterval(t);
        // 结果
        const s1 = getRandomSymbol(), s2 = getRandomSymbol(), s3 = getRandomSymbol();
        reels[0].textContent = s1.sym; reels[1].textContent = s2.sym; reels[2].textContent = s3.sym;
        reels.forEach(r => r.classList.remove('rolling'));

        data.remaining--; data.total++;
        let prizeMsg = '';

        if (s1.sym === s2.sym && s2.sym === s3.sym) {
          // 三连
          const p = SLOT_PRIZES.find(x => x.match === 3 && x.sym === s1.sym);
          prizeMsg = p ? p.prize : '🎉 三个相同！';
          const m = p ? p.msg : `${s1.sym} 三连！厉害！`;
          reels.forEach(r => r.classList.add('win-highlight'));
          spawnParticles(reels[0], 16);
          data.bestPrize = prizeMsg;
          mikuSay(m, 6000);
        } else if (s1.sym === s2.sym || s2.sym === s3.sym || s1.sym === s3.sym) {
          // 两连
          prizeMsg = '📯 两连！';
          mikuSay(`差一点就三个了！再来一次～`, 4000);
        } else {
          const msgs = [`${s1.sym} ${s2.sym} ${s3.sym}... 全都不一样诶`, `今天手气不太好呢～`, `没事没事，下次一定中！`];
          mikuSay(msgs[Math.floor(Math.random()*msgs.length)], 4000);
        }

        data.plays++;
        saveSlot(data);

        prizeEl.innerHTML = prizeMsg ? `<span style="font-size:14px;font-weight:700;color:var(--red-1);">${prizeMsg}</span>` : '';
        const ce = document.getElementById('miku-slot-chances');
        if (ce) ce.textContent = `🎰 今日剩余 ${data.remaining} / ${DAILY_FREE} 次`;
        btn.disabled = false;
      }
    }, 80);
  };

  /* ========== 面板注入 ========== */
  let widgetInjected = false;
  let currentGame = 'rps';

  const switchGame = (game) => {
    currentGame = game;
    ['rps','dice','slot'].forEach(g => {
      const el = document.getElementById(`miku-game-${g}`);
      if (el) el.style.display = g === game ? 'block' : 'none';
    });
    document.querySelectorAll('.miku-tab').forEach(t => t.classList.toggle('active', t.dataset.game === game));
  };
  window.__switchGame = switchGame;

  const injectSidebarWidget = () => {
    if (document.getElementById('miku-game-widget') || widgetInjected) return;
    const sidebar = document.querySelector('aside#sidebar');
    if (!sidebar) return;
    const poke = loadPoke(), rps = loadRps(), dice = loadDice(), slot = loadSlot();

    let h = '<div class="widget-wrap" id="miku-game-widget"><div class="widget-title" style="margin-bottom:12px;font-weight:700;color:var(--red-1);font-size:1.1em;display:flex;align-items:center;"><span style="margin-right:8px;">🎮</span> Miku 互动</div><div class="widget" style="text-align:center;">';

    // 戳
    h += '<div style="margin-bottom:10px;"><div style="font-size:12px;font-weight:600;margin-bottom:6px;opacity:0.7;">👆 戳 Miku</div><div class="miku-stat-row"><span>总次数</span><span class="miku-stat-val" id="miku-poke-total">' + poke.total + '</span></div>';
    ZONES.forEach(z => h += '<div class="miku-stat-row"><span>' + ZONE_NAMES[z] + '</span><span class="miku-stat-val" id="miku-poke-' + z + '">' + poke[z] + '</span></div>');
    h += '</div><div style="height:1px;background:var(--red-5,rgba(255,228,228,0.3));margin:10px 0;"></div>';

    // Tabs
    h += '<div class="miku-tabs"><button class="miku-tab active" data-game="rps" onclick="window.__switchGame(\'rps\')">✊ 猜拳</button><button class="miku-tab" data-game="dice" onclick="window.__switchGame(\'dice\')">🎲 骰子</button><button class="miku-tab" data-game="slot" onclick="window.__switchGame(\'slot\')">🎰 老虎机</button></div>';

    // 猜拳
    h += '<div id="miku-game-rps"><button id="miku-rps-btn" class="miku-game-btn" onclick="(()=>{var u=document.getElementById(\'miku-rps-ui\'),b=document.getElementById(\'miku-rps-btn\');if(!u||!b)return;var s=u.style.display!==\'block\';u.style.display=s?\'block\':\'none\';b.textContent=s?\'✖ 关闭\':\'🎮 和 Miku 玩猜拳\';})()">🎮 和 Miku 玩猜拳</button><div id="miku-rps-ui" style="display:none;margin-top:10px;"><div class="miku-rps-row" style="display:flex;justify-content:center;gap:10px;margin-bottom:6px;position:relative;">';
    h += '<button class="miku-rps-choice" data-choice="rock">✊</button><button class="miku-rps-choice" data-choice="scissors">✌️</button><button class="miku-rps-choice" data-choice="paper">✋</button>';
    h += '<div id="miku-vs-overlay" style="display:none;position:absolute;inset:0;align-items:center;justify-content:center;gap:12px;z-index:5;background:rgba(30,20,55,0.85);border-radius:12px;backdrop-filter:blur(4px);"></div></div>';
    h += '<div id="miku-rps-score" style="font-size:12px;opacity:0.7;">胜 ' + rps.wins + ' / 负 ' + rps.losses + ' / 平 ' + rps.ties + '</div></div></div>';

    // 骰子
    h += '<div id="miku-game-dice" style="display:none;"><div class="miku-dice-section"><div class="miku-dice-label">🧑 你</div><div class="miku-dice-area" id="miku-dice-player">🎲 点摇骰开始</div></div><div class="miku-dice-vs">⚡</div><div class="miku-dice-section"><div class="miku-dice-label">🎤 Miku</div><div class="miku-dice-area" id="miku-dice-miku">🎲 等待中</div></div><div id="miku-dice-result" class="miku-dice-result"></div><button id="miku-dice-btn" class="miku-game-btn">🎲 摇骰子</button><div id="miku-dice-score" style="font-size:12px;opacity:0.7;margin-top:4px;">胜 ' + dice.wins + ' / 负 ' + dice.losses + '</div></div>';

    // 老虎机
    h += '<div id="miku-game-slot" style="display:none;"><div class="miku-slot-machine"><div class="miku-slot-display">';
    for (let i = 0; i < 3; i++) h += '<div class="miku-slot-reel" id="miku-slot-reel-' + i + '">🎰</div>';
    h += '</div><div id="miku-slot-prize" class="miku-slot-prize"></div>';
    h += '<button id="miku-slot-btn" class="miku-game-btn">🎰 拉杆！</button>';
    h += '<div id="miku-slot-chances" class="miku-slot-chances">🎰 今日剩余 ' + slot.remaining + ' / ' + DAILY_FREE + ' 次</div>';
    h += '</div></div>';

    h += '</div></div>';

    const tmp = document.createElement('div'); tmp.innerHTML = h;
    const widget = tmp.firstElementChild;
    const wa = sidebar.querySelector('.sidebar-widget');
    if (wa) wa.appendChild(widget);
    else { const w = sidebar.querySelector('.sidebar-wrapper-container'); if (w && w.parentNode) w.parentNode.insertBefore(widget, w.nextSibling); else sidebar.appendChild(widget); }

    widgetInjected = true;
    widget.querySelectorAll('.miku-rps-choice').forEach(b => b.addEventListener('click', e => playRPS(b.dataset.choice, b)));
    const db = widget.querySelector('#miku-dice-btn'); if (db) db.addEventListener('click', playDice);
    const sb = widget.querySelector('#miku-slot-btn'); if (sb) sb.addEventListener('click', playSlot);
  };

  const destroy = () => {
    ['live2d-hit-zone','miku-game-widget'].forEach(id => { const el = document.getElementById(id); if (el) el.remove(); });
    widgetInjected = false;
    document.querySelectorAll('.rps-particle').forEach(el => el.remove());
  };

  const init = () => { injectHitzones(); injectSidebarWidget(); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
  window.addEventListener('pjax:send', destroy);
  window.addEventListener('pjax:complete', () => setTimeout(init, 150));
})();

/* ============================================
 * 全屏 Matrix 数字雨屏保 (Idle Matrix Screen Saver)
 * 闲置 45 秒后切入，任意动作唤醒
 * ============================================ */

(() => {
  'use strict';

  class MatrixSaver {
    constructor() {
      this.canvas = null;
      this.ctx = null;
      this.drops = [];
      this.fontSize = 16;
      this.columns = 0;
      this.isActive = false;
      this.idleThreshold = 45000; // 45 seconds
      this.lastTime = Date.now();

      this.draw = this.draw.bind(this);
      this.resetIdle = this.resetIdle.bind(this);
      this.checkIdle = this.checkIdle.bind(this);
    }

    init() {
      if (document.getElementById('matrix-saver-canvas')) return;

      this.canvas = document.createElement('canvas');
      this.canvas.id = 'matrix-saver-canvas';
      this.canvas.style.position = 'fixed';
      this.canvas.style.top = '0';
      this.canvas.style.left = '0';
      this.canvas.style.width = '100vw';
      this.canvas.style.height = '100vh';
      this.canvas.style.zIndex = '9999998';
      this.canvas.style.pointerEvents = 'none';
      this.canvas.style.opacity = '0';
      this.canvas.style.transition = 'opacity 2s ease-in-out';
      this.canvas.style.background = '#000';
      document.body.appendChild(this.canvas);

      this.ctx = this.canvas.getContext('2d');
      this.resize();

      window.addEventListener('resize', () => this.resize());
      window.addEventListener('mousemove', this.resetIdle);
      window.addEventListener('keypress', this.resetIdle);
      window.addEventListener('scroll', this.resetIdle);
      window.addEventListener('click', this.resetIdle);

      setInterval(this.checkIdle, 1000);
    }

    resize() {
      if (!this.canvas) return;
      this.canvas.width = window.innerWidth;
      this.canvas.height = window.innerHeight;
      this.columns = Math.floor(this.canvas.width / this.fontSize);
      this.drops = [];
      for (let i = 0; i < this.columns; i++) {
        this.drops[i] = Math.random() * -100;
      }
    }

    start() {
      if (this.isActive) return;
      this.init();
      this.isActive = true;
      this.canvas.style.opacity = '1';
      this.canvas.style.pointerEvents = 'auto';
      requestAnimationFrame(this.draw);
    }

    stop() {
      if (!this.isActive) return;
      this.isActive = false;
      this.canvas.style.opacity = '0';
      this.canvas.style.pointerEvents = 'none';
      this.resetIdle();
      // Glitch effect on wake
      document.body.style.filter = `hue-rotate(90deg) contrast(150%)`;
      setTimeout(() => { document.body.style.filter = ''; }, 150);
    }

    draw() {
      if (!this.isActive) return;

      this.ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
      this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

      this.ctx.fillStyle = '#0F0';
      this.ctx.font = this.fontSize + 'px monospace';

      for (let i = 0; i < this.drops.length; i++) {
        const text = String.fromCharCode(Math.random() * 128);
        this.ctx.fillText(text, i * this.fontSize, this.drops[i] * this.fontSize);

        if (this.drops[i] * this.fontSize > this.canvas.height && Math.random() > 0.975) {
          this.drops[i] = 0;
        }
        this.drops[i]++;
      }
      requestAnimationFrame(this.draw);
    }

    resetIdle() {
      this.lastTime = Date.now();
      if (this.isActive) {
        this.stop();
      }
    }

    checkIdle() {
      if (!this.isActive && (Date.now() - this.lastTime > this.idleThreshold)) {
        this.start();
      }
    }
  }

  window.MatrixSaver = new MatrixSaver();
  // Init idle detection on load
  document.addEventListener('DOMContentLoaded', () => {
    window.MatrixSaver.init();
  });

  window.triggerMatrixSaver = function() {
    window.MatrixSaver.start();
  };
})();

/* ============================================
 * 留言板浮窗控制器
 * - 侧边栏「留言」按钮 / [data-msg-open] 触发打开
 * - 遮罩 / 关闭按钮 / Esc 关闭
 * - 首次打开时通知 messages-wall.js 加载数据
 * - 访问 /messages 路径时自动打开（替代独立页面）
 * ============================================ */

(() => {
  'use strict';

  const getModal = () => document.getElementById('msg-modal');

  /* ---------------- 公告弹窗 ---------------- */
  const ANNOUNCE_KEY = 'msg-announce-mute';

  const isAnnounceMuted = () => {
    try {
      return localStorage.getItem(ANNOUNCE_KEY) === '1';
    } catch (_) {
      return false;
    }
  };

  const showAnnounce = () => {
    const announce = document.getElementById('msg-announce');
    if (!announce) return;
    announce.classList.add('open');
    announce.setAttribute('aria-hidden', 'false');
  };

  const hideAnnounce = () => {
    const announce = document.getElementById('msg-announce');
    if (!announce) return;
    announce.classList.remove('open');
    announce.setAttribute('aria-hidden', 'true');
    // 勾选了「下次不再提醒」就记住
    const mute = document.getElementById('msg-announce-mute');
    try {
      if (mute && mute.checked) localStorage.setItem(ANNOUNCE_KEY, '1');
    } catch (_) { /* ignore */ }
  };

  const open = () => {
    const modal = getModal();
    if (!modal || modal.classList.contains('open')) return;
    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');
    document.documentElement.classList.add('msg-modal-open');
    // 首次打开才真正请求留言数据（懒加载）
    if (typeof window.__msgBoardLoad === 'function') {
      window.__msgBoardLoad();
    }
    // 未选择「不再提醒」时，弹出公告栏
    if (!isAnnounceMuted()) {
      showAnnounce();
    }
    const textarea = document.getElementById('msg-textarea');
    if (textarea && window.matchMedia('(min-width: 961px)').matches) {
      setTimeout(() => textarea.focus(), 350);
    }
  };

  const close = () => {
    const modal = getModal();
    if (!modal || !modal.classList.contains('open')) return;
    hideAnnounce();
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden', 'true');
    document.documentElement.classList.remove('msg-modal-open');
  };

  const isMessagesPath = () => {
    const path = window.location.pathname.replace(/\/+$/, '');
    return path.endsWith('/messages');
  };

  const autoOpenIfMessagesPage = () => {
    if (isMessagesPath()) open();
  };

  // 事件委托：浮窗由 pjax 保留在 body 级，绑定一次即可
  if (!window.__msgDrawerBound) {
    window.__msgDrawerBound = true;

    document.addEventListener('click', (e) => {
      const opener = e.target.closest('#btn-messages-board, [data-msg-open]');
      if (opener) {
        e.preventDefault();
        e.stopPropagation();
        open();
        return;
      }
      if (e.target.closest('#msg-modal-close') || e.target.id === 'msg-modal-mask') {
        close();
        return;
      }
      // 公告弹窗：关闭按钮 / 我知道了 / 点击卡片外区域
      if (e.target.closest('#msg-announce-close') || e.target.closest('#msg-announce-ok') || e.target.closest('#msg-announce')) {
        const insideCard = e.target.closest('.msg-announce-card');
        if (e.target.closest('#msg-announce-close') || e.target.closest('#msg-announce-ok') || !insideCard) {
          hideAnnounce();
        }
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') close();
    });

    document.addEventListener('pjax:complete', autoOpenIfMessagesPage);
    document.addEventListener('pjax:end', autoOpenIfMessagesPage);
  }

  window.MsgBoard = { open, close };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', autoOpenIfMessagesPage);
  } else {
    autoOpenIfMessagesPage();
  }
})();

/* ============================================
 * 文章迷雾解锁系统 — 客户端脚本
 *
 * 迷雾锁类型：
 *   1. 时间锁 (unlock_date) — 到达指定日期才能看
 *   2. 进度锁 (read_required) — 读完 N 篇文章才能看
 *   3. 禁阅锁 (forbid_start / forbid_end) — 指定时间段内不能看
 *
 * 使用方式 (文章 front-matter):
 *   unlock_date: 2030-06-01          # 在此日期后才能看
 *   forbid_start: 2025-05-05         # 在此日期后不能看
 *   forbid_end: 2025-06-01           # 在此日期后才能看
 *   或者精确到分钟：
 *   forbid_start: 2026-01-01 16:30
 *   forbid_end: 2026-03-15 15:00
 *   read_required: 3                # 读满 N 篇才能看
 *   mist_title: "迷雾的标题"         # 自定义迷雾标题
 * ============================================ */

(() => {
  'use strict';

  /* ---- 工具函数 ---- */
  const getArticleEl = () => document.querySelector(
    'article[data-unlock-date], article[data-read-required], article[data-forbid-start], article[data-forbid-end]'
  );

  const getReadCount = () => {
    try { return parseInt(localStorage.getItem('mist_read_count') || '0', 10); }
    catch { return 0; }
  };

  const setReadCount = (n) => {
    try { localStorage.setItem('mist_read_count', String(n)); } catch { /* noop */ }
  };

  const markArticleRead = (slug) => {
    try {
      const key = `mist_read_${slug}`;
      if (localStorage.getItem(key)) return;
      localStorage.setItem(key, '1');
      setReadCount(getReadCount() + 1);
    } catch { /* noop */ }
  };

  /** 解析日期字符串：支持 "2026-01-01" 或 "2026-01-01 16:30" 或 ISO 格式 */
  const parseDate = (str) => {
    if (!str) return null;
    const dt = str.trim();
    // Hexo 可能输出 ISO 格式如 "2030-12-31T16:00:00.000Z" → 直接传 Date 构造
    if (dt.includes('T') || dt.includes('Z')) {
      const d = new Date(dt);
      return isNaN(d.getTime()) ? null : d;
    }
    // "2026-01-01 16:30" 格式
    if (/^\d{4}-\d{2}-\d{2}\s+\d{1,2}:\d{2}$/.test(dt)) {
      return new Date(dt.replace(' ', 'T') + ':00');
    }
    // "2026-01-01" 格式 — 视为当天的 00:00
    return new Date(dt + 'T00:00:00');
  };

  /* 获取迷雾状态 */
  const getMistState = (el) => {
    const now = new Date();
    const unlockDate = parseDate(el.dataset.unlockDate);
    const forbidStart = parseDate(el.dataset.forbidStart);
    const forbidEnd = parseDate(el.dataset.forbidEnd);
    const readRequired = parseInt(el.dataset.readRequired || '0', 10);

    // 禁阅锁：
    //   forbid_start 单独使用 → 此日期之后永久禁阅
    //   forbid_start + forbid_end → 此时间段内禁阅
    let inForbid = false;
    let forbidTarget = null;
    if (forbidStart && forbidEnd) {
      // 时间段禁阅：start <= now < end
      inForbid = now >= forbidStart && now < forbidEnd;
      if (inForbid) forbidTarget = forbidEnd;
    } else if (forbidStart && !forbidEnd) {
      // 永久禁阅：now >= start
      inForbid = now >= forbidStart;
      forbidTarget = null; // 无倒计时
    }

    const timeLocked = unlockDate && now < unlockDate;
    const progressLocked = readRequired > 0 && getReadCount() < readRequired;

    return {
      locked: inForbid || timeLocked || progressLocked,
      inForbid,
      forbidTarget,
      timeLocked,
      progressLocked,
      unlockDate,
      forbidStart,
      forbidEnd,
      readRequired,
      readCount: getReadCount(),
    };
  };

  /* 计算剩余时间 */
  const getTimeRemaining = (target) => {
    const diff = target - new Date();
    if (diff <= 0) return { days: 0, hours: 0, minutes: 0, seconds: 0, total: 0 };
    return {
      days: Math.floor(diff / (1000 * 60 * 60 * 24)),
      hours: Math.floor((diff / (1000 * 60 * 60)) % 24),
      minutes: Math.floor((diff / (1000 * 60)) % 60),
      seconds: Math.floor((diff / 1000) % 60),
      total: diff,
    };
  };

  /* 格式化日期显示 */
  const formatDate = (d) => {
    if (!d) return '';
    return `${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,'0')}.${String(d.getDate()).padStart(2,'0')}`;
  };

  const formatDateTime = (d) => {
    if (!d) return '';
    const h = String(d.getHours()).padStart(2, '0');
    const m = String(d.getMinutes()).padStart(2, '0');
    return `${formatDate(d)} ${h}:${m}`;
  };

  /* 渲染迷雾遮罩 HTML */
  const renderOverlay = (state) => {
    const overlay = document.createElement('div');
    overlay.className = 'mist-overlay';

    let html = '<div class="mist-icon">🔮</div>';

    const title = document.querySelector('article')?.dataset.mistTitle || '被迷雾笼罩的文章';
    html += `<div class="mist-title">${title}</div>`;

    if (state.inForbid) {
      html += `<div class="mist-subtitle">⛔ 这篇文章在当前时间不可访问</div>`;
      if (state.forbidTarget) {
        // 有时间范围 → 显示倒计时
        html += `<div class="mist-countdown" id="mist-forbid-timer">
          ⛔ 不可访问期还剩<br>
          <span class="cd-num" id="cd-days">--</span> 天
          <span class="cd-num" id="cd-hours">--</span> 时
          <span class="cd-num" id="cd-minutes">--</span> 分
          <span class="cd-num" id="cd-seconds">--</span> 秒
        </div>`;
      } else {
        // 永久禁阅 → 无倒计时
        html += `<div class="mist-countdown">⛔ 这篇文章已被永久封印</div>`;
      }
    }

    if (state.timeLocked) {
      const dateStr = formatDateTime(state.unlockDate);
      html += `<div class="mist-subtitle">这篇被时间迷雾封印了<br>将在 ${dateStr} 揭晓</div>`;
      html += `<div class="mist-countdown" id="mist-countdown-timer">
        ⏳ <span class="cd-num" id="cd-days">--</span> 天
        <span class="cd-num" id="cd-hours">--</span> 时
        <span class="cd-num" id="cd-minutes">--</span> 分
        <span class="cd-num" id="cd-seconds">--</span> 秒
      </div>`;
    }

    if (state.progressLocked) {
      const pct = Math.min(100, Math.round((state.readCount / state.readRequired) * 100));
      html += '<div class="mist-subtitle">📖 需要阅读足够多的文章才能揭开迷雾</div>';
      html += `<div class="mist-progress">
        <span>已读 <strong>${state.readCount}</strong> / ${state.readRequired}</span>
        <div class="mist-progress-bar">
          <div class="mist-progress-fill" style="width:${pct}%"></div>
        </div>
      </div>`;
      const remain = state.readRequired - state.readCount;
      if (remain > 0) {
        html += `<div class="mist-countdown">📖 再读 <strong>${remain}</strong> 篇即可解锁</div>`;
      }
    }

    overlay.innerHTML = html;
    return overlay;
  };

  /* 更新倒计时 */
  const updateCountdown = (target, prefix) => {
    const r = getTimeRemaining(target);
    const id = (name) => `${prefix}-${name}`;
    const daysEl = document.getElementById(id('days'));
    if (!daysEl) return r.total > 0;
    daysEl.textContent = String(r.days).padStart(2, '0');
    document.getElementById(id('hours')).textContent = String(r.hours).padStart(2, '0');
    document.getElementById(id('minutes')).textContent = String(r.minutes).padStart(2, '0');
    document.getElementById(id('seconds')).textContent = String(r.seconds).padStart(2, '0');
    return r.total > 0;
  };

  /* ---- 监视器 ---- */
  const watchCountdown = (el, state) => {
    if (!state.locked) return;

    const target = state.inForbid ? state.forbidTarget : state.unlockDate;
    if (!target) return;

    // 初始化显示 (ID 固定为 cd-days/cd-hours/cd-minutes/cd-seconds)
    updateCountdown(target, 'cd');

    const timer = setInterval(() => {
      // 重新获取完整状态（因为可能跨过了 forbid 窗口）
      const fresh = getMistState(el);
      if (!fresh.locked) {
        el.classList.add('mist-unlocked');
        clearInterval(timer);
        return;
      }
      const t = fresh.inForbid ? fresh.forbidTarget : fresh.unlockDate;
      updateCountdown(t, 'cd');
    }, 1000);
  };

  const watchProgress = (el, state) => {
    if (!state.progressLocked) return;
    const timer = setInterval(() => {
      const cur = getReadCount();
      if (cur >= state.readRequired) {
        el.classList.add('mist-unlocked');
        clearInterval(timer);
      }
    }, 2000);
  };

  /* ---- 初始化 ---- */
  const init = () => {
    const el = getArticleEl();
    if (!el) return;

    const state = getMistState(el);

    // 没有锁 → 解锁并记录已读
    if (!state.locked) {
      el.classList.add('mist-unlocked');
      const slug = el.id?.replace(/^post-/, '');
      if (slug) markArticleRead(slug);
      return;
    }

    // 挂载迷雾遮罩
    const articleInner = el.querySelector('.article-inner');
    if (!articleInner) return;
    if (articleInner.querySelector('.mist-overlay')) return; // 防止 PJAX 重复
    const overlay = renderOverlay(state);
    articleInner.style.position = 'relative';
    articleInner.appendChild(overlay);

    const slug = el.id?.replace(/^post-/, '');
    if (slug && !state.progressLocked) markArticleRead(slug);

    // 启动监视器
    watchCountdown(el, state);
    watchProgress(el, state);
  };

  /* ---- 启动 ---- */
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  document.addEventListener('pjax:complete', () => setTimeout(init, 100));
})();

/* ============================================
 * 留言板 — 客户端脚本（自研轻量客户端）
 *
 * 后端为自研留言服务（waline.monkeyiu.icu），
 * 响应为 {errno, errmsg, data} 包装格式，
 * 与官方 @waline/client 不兼容，故独立实现：
 * 1. 留言列表（分页/嵌套回复/身份徽章/设备信息）
 * 2. 发表与回复（游客身份，昵称邮箱本地记忆）
 * 3. 表情面板 / 字数统计 / 审核状态提示
 * 4. 「聊天成员」侧栏聚合
 * ============================================ */

(() => {
  'use strict';

  const MSG_SERVER = 'https://waline.monkeyiu.icu';
  const MSG_PATH = '/messages';
  const PAGE_SIZE = 10;
  const MAX_LEN = 300;
  /** 站长昵称（匹配到则显示「主人」徽章，留空不启用） */
  const OWNER_NICK = '';
  const NOTICE_KEY = 'msg-notice-closed';
  const IDENT_KEY = 'msg-identity-v2';
  const LEGACY_IDENT_KEY = 'msg-identity';

  const EMOJIS = [
    '😀', '😁', '😂', '🤣', '😅', '😊', '😍', '😘', '😜', '🤔',
    '🙄', '😴', '😭', '😱', '🥰', '😎', '👍', '👎', '👏', '🙏',
    '💪', '🤝', '👀', '❤️', '💔', '✨', '🔥', '🎉', '🎂', '🍉',
    '☕', '🌙', '⭐', '🌈', '🐱', '🐶',
  ];

  const $ = (id) => document.getElementById(id);

  /* ---------------- 工具 ---------------- */

  const pad = (n) => String(n).padStart(2, '0');

  const formatTime = (ms) => {
    const d = new Date(Number(ms) || Date.now());
    return `${pad(d.getMonth() + 1)}/${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
  };

  /** 留言内容白名单清洗（服务端返回 HTML） */
  const ALLOWED_TAGS = new Set([
    'P', 'BR', 'A', 'IMG', 'STRONG', 'B', 'EM', 'I', 'U',
    'CODE', 'PRE', 'BLOCKQUOTE', 'UL', 'OL', 'LI', 'SPAN', 'DIV',
  ]);

  const sanitize = (html) => {
    const tpl = document.createElement('template');
    tpl.innerHTML = String(html || '');
    const walk = (parent) => {
      Array.from(parent.children).forEach((el) => {
        if (!ALLOWED_TAGS.has(el.tagName)) {
          el.replaceWith(document.createTextNode(el.textContent || ''));
          return;
        }
        Array.from(el.attributes).forEach((attr) => {
          const name = attr.name.toLowerCase();
          if (name.startsWith('on') || name === 'style') {
            el.removeAttribute(attr.name);
          } else if (el.tagName === 'A' && name === 'href' && !/^(https?:|mailto:|#)/i.test(attr.value)) {
            el.removeAttribute('href');
          } else if (el.tagName === 'IMG' && name === 'src' && !/^https?:/i.test(attr.value)) {
            el.removeAttribute('src');
          }
        });
        if (el.tagName === 'A') {
          el.setAttribute('target', '_blank');
          el.setAttribute('rel', 'noopener noreferrer');
        }
        walk(el);
      });
    };
    walk(tpl.content);
    return tpl.innerHTML;
  };

  let toastTimer = null;
  const toast = (text) => {
    let el = $('msg-toast');
    if (!el) {
      el = document.createElement('div');
      el.id = 'msg-toast';
      document.body.appendChild(el);
    }
    el.textContent = text;
    el.classList.add('visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => el.classList.remove('visible'), 3000);
  };

  const apiGet = async (query) => {
    const res = await fetch(`${MSG_SERVER}/api/comment?${query}`);
    const json = await res.json();
    if (json.errno) throw new Error(typeof json.errmsg === 'string' ? json.errmsg : '请求失败');
    return json.data;
  };

  /* ---------------- 留言列表 ---------------- */

  let totalPages = 1;

  /* 头像兜底：昵称哈希 → 确定性配色，生成彩色字母头像（SVG data URI，无外链依赖） */
  const AVATAR_COLORS = [
    '#ef4444', '#f97316', '#eab308', '#84cc16', '#22c55e',
    '#14b8a6', '#3b82f6', '#8b5cf6', '#ec4899', '#f43f5e',
  ];

  const hashNick = (nick) => {
    let h = 0;
    const s = String(nick || '');
    for (let i = 0; i < s.length; i++) h = (h << 5) - h + s.charCodeAt(i);
    return Math.abs(h);
  };

  const makeLetterAvatar = (nick) => {
    const ch = (nick || '匿').trim().charAt(0).toUpperCase();
    const color = AVATAR_COLORS[hashNick(nick) % AVATAR_COLORS.length];
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80"><rect width="80" height="80" fill="${color}"/><text x="40" y="55" font-size="38" font-weight="700" fill="#fff" text-anchor="middle" font-family="system-ui,-apple-system,sans-serif">${ch}</text></svg>`;
    return 'data:image/svg+xml,' + encodeURIComponent(svg);
  };

  /**
   * 头像链接归一化：
   * 后端把无自定义头像的用户指向 Libravatar（国内几乎无人注册，全显示灰色默认图）。
   * Libravatar / Gravatar / Cravatar 共用同一套邮箱 MD5 哈希，这里统一换成
   * Cravatar（国内访问快，用户可在 cravatar.cn 用邮箱自助设置头像，未设置时自动回退 Gravatar）。
   * 加 d=404：没有头像时返回 404 → 触发 onerror → 彩色字母兜底，避免灰色占位图。
   */
  const normalizeAvatarUrl = (url) => {
    let u = String(url || '').trim();
    if (!u) return '';
    u = u
      .replace(/^https?:\/\/(seccdn\.)?libravatar\.org\/avatar\//i, 'https://cravatar.cn/avatar/')
      .replace(/^https?:\/\/(www\.)?gravatar\.com\/avatar\//i, 'https://cravatar.cn/avatar/');
    if (/cravatar\.cn\/avatar\//i.test(u)) {
      u = u.replace(/([?&])d=[^&]*/gi, '$1').replace(/([?&])&+/g, '$1').replace(/[?&]$/, '');
      u += (u.includes('?') ? '&' : '?') + 'd=404';
    }
    return u;
  };

  /**
   * Waline 账号头像索引：
   * 留言接口对未登录留言一律按邮箱 MD5 重算头像（Libravatar），不返回账号头像；
   * 而公开的 type=recent 接口会为「登录后发布」的评论（user_id 存在）返回账号头像。
   * 借助它建立 昵称 → 账号头像 映射，未登录访客也能看到这些用户的 Waline 自定义头像。
   */
  let accountAvatars = {};

  const indexAccountAvatars = (recentComments) => {
    recentComments.forEach((c) => {
      if (c && c.user_id && c.nick && c.avatar) {
        accountAvatars[c.nick.trim()] = c.avatar;
      }
    });
  };

  const buildAvatar = (src, nick) => {
    const wrap = document.createElement('span');
    wrap.className = 'msg-avatar-wrap';
    const img = document.createElement('img');
    img.className = 'msg-avatar';
    img.loading = 'lazy';
    img.alt = nick || '';
    img.onerror = () => {
      img.onerror = null; // 防止兜底图再次失败时死循环
      img.src = makeLetterAvatar(nick);
    };
    img.src = src || makeLetterAvatar(nick);
    wrap.appendChild(img);
    return wrap;
  };

  const badgeFor = (c) => {
    if (c.type === 'administrator' || c.user_id) return '站长';
    if (OWNER_NICK && c.nick === OWNER_NICK) return '主人';
    return '';
  };

  const renderCard = (c, isChild) => {
    const card = document.createElement('article');
    card.className = `msg-card${isChild ? ' msg-card-child' : ''}`;
    card.dataset.id = c.objectId;
    // 站长/主人气泡右对齐（聊天室样式）
    if (badgeFor(c)) card.classList.add('msg-card-admin');

    card.appendChild(buildAvatar(resolveAvatar(c), c.nick));

    const body = document.createElement('div');
    body.className = 'msg-card-body';

    const head = document.createElement('div');
    head.className = 'msg-card-head';

    const nick = document.createElement('span');
    nick.className = 'msg-nick';
    nick.textContent = c.nick || '匿名用户';
    head.appendChild(nick);

    const badge = badgeFor(c);
    if (badge) {
      const b = document.createElement('span');
      b.className = `msg-badge${badge === '主人' ? ' msg-badge-owner' : ''}`;
      b.textContent = badge;
      head.appendChild(b);
    }

    const time = document.createElement('span');
    time.className = 'msg-time';
    time.textContent = formatTime(c.time);
    head.appendChild(time);
    body.appendChild(head);

    if (isChild && c.reply_user?.nick) {
      const at = document.createElement('div');
      at.className = 'msg-at';
      at.textContent = `回复 @${c.reply_user.nick}`;
      body.appendChild(at);
    }

    const content = document.createElement('div');
    content.className = 'msg-card-content';
    content.innerHTML = sanitize(c.comment || c.orig || '');
    body.appendChild(content);

    const meta = document.createElement('div');
    meta.className = 'msg-card-meta';
    const device = [c.browser, c.os].filter(Boolean).join(' · ');
    if (device) {
      const d = document.createElement('span');
      d.className = 'msg-device';
      d.textContent = device;
      meta.appendChild(d);
    }
    if (c.addr) {
      const a = document.createElement('span');
      a.className = 'msg-addr';
      a.textContent = c.addr;
      meta.appendChild(a);
    }
    const replyBtn = document.createElement('button');
    replyBtn.type = 'button';
    replyBtn.className = 'msg-reply-btn';
    replyBtn.textContent = '回复';
    replyBtn.dataset.nick = c.nick || '';
    replyBtn.dataset.pid = String(c.objectId);
    replyBtn.dataset.rid = String(isChild ? (c.rid || c.objectId) : c.objectId);
    meta.appendChild(replyBtn);
    body.appendChild(meta);

    if (Array.isArray(c.children) && c.children.length) {
      const childrenWrap = document.createElement('div');
      childrenWrap.className = 'msg-children';
      c.children.forEach((child) => childrenWrap.appendChild(renderCard(child, true)));
      body.appendChild(childrenWrap);
    }

    card.appendChild(body);
    return card;
  };

  /** 顶部提示条（上滑加载 / 已到最早） */
  const ensureTopHint = () => {
    const list = $('msg-list');
    if (!list) return null;
    let hint = $('msg-top-hint');
    if (!hint) {
      hint = document.createElement('div');
      hint.id = 'msg-top-hint';
      hint.className = 'msg-top-hint';
      list.prepend(hint);
    }
    return hint;
  };

  const setTopHint = (text) => {
    const hint = ensureTopHint();
    if (hint) hint.textContent = text;
  };

  /** 已加载的最新页码（正序模式下第 1 页=最新，第 N 页=更早） */
  let loadedPage = 0;
  let loadingOlder = false;

  const scrollListToBottom = () => {
    const list = $('msg-list');
    if (!list) return;
    requestAnimationFrame(() => { list.scrollTop = list.scrollHeight; });
  };

  /**
   * 加载留言。mode:
   *  - 'replace' 首次/刷新：取最新一页，正序渲染（旧→新），滚到底部
   *  - 'prepend' 上滑加载更早：插到顶部并保持滚动位置不跳动
   */
  const loadComments = async (page = 1, mode = 'replace') => {
    const list = $('msg-list');
    if (!list) return;

    try {
      const data = await apiGet(`path=${encodeURIComponent(MSG_PATH)}&page=${page}&pageSize=${PAGE_SIZE}`);
      totalPages = data.totalPages || 1;
      loadedPage = Math.max(loadedPage, page);
      const items = (data.data || []).slice().reverse(); // 服务端倒序 → 转成正序

      if (mode === 'prepend') {
        const oldHeight = list.scrollHeight;
        const oldTop = list.scrollTop;
        const frag = document.createDocumentFragment();
        items.forEach((c) => frag.appendChild(renderCard(c, false)));
        // 插在顶部提示条之后
        const hint = $('msg-top-hint');
        if (hint && hint.nextSibling) list.insertBefore(frag, hint.nextSibling);
        else list.prepend(frag);
        list.scrollTop = list.scrollHeight - oldHeight + oldTop; // 保持视觉位置
      } else {
        list.replaceChildren();
        ensureTopHint();
        items.forEach((c) => list.appendChild(renderCard(c, false)));
        if (list.querySelectorAll(':scope > .msg-card').length === 0) {
          list.insertAdjacentHTML('beforeend', '<div class="msg-status">还没有留言，快来发表第一条留言吧！</div>');
        }
        scrollListToBottom();
      }

      // 顶部提示文案
      if (loadedPage >= totalPages) setTopHint('· 已经到最早啦 ·');
      else if (totalPages > 1) setTopHint('上滑加载更早的留言');

      const countText = $('msg-count-text');
      const syncText = $('msg-sync-text');
      if (countText) countText.textContent = `${data.count ?? list.querySelectorAll(':scope > .msg-card').length} 条留言`;
      if (syncText) syncText.textContent = `同步于 ${new Date().toLocaleTimeString('zh-CN', { hour12: false })}`;
    } catch (_) {
      if (mode === 'replace') list.innerHTML = '<div class="msg-status">留言加载失败了，请稍后再试</div>';
      else toast('加载失败了，请稍后再试');
    }
  };

  /** 滚动监听：滚到顶部附近自动加载更早一页 */
  const bindListScroll = () => {
    const list = $('msg-list');
    if (!list || list.dataset.scrollBound) return;
    list.dataset.scrollBound = '1';
    list.addEventListener('scroll', async () => {
      if (loadingOlder || loadedPage >= totalPages) return;
      if (list.scrollTop > 60) return;
      loadingOlder = true;
      setTopHint('加载更早的留言…');
      await loadComments(loadedPage + 1, 'prepend');
      loadingOlder = false;
    });
  };

  /* ---------------- 回复目标 ---------------- */

  let replyTarget = null;

  const setReplyTarget = (target) => {
    replyTarget = target;
    const tip = $('msg-reply-tip');
    if (!tip) return;
    if (target) {
      tip.hidden = false;
      tip.textContent = `回复 @${target.nick}  ×`;
    } else {
      tip.hidden = true;
      tip.textContent = '';
    }
  };

  /* ---------------- 身份状态机 ---------------- */

  /** 当前身份：{mode: 'guest'|'register'|'login', nick, mail, token?, avatar?} */
  let identity = null;

  const getIdentity = () => {
    try {
      return JSON.parse(localStorage.getItem(IDENT_KEY) || 'null');
    } catch (_) {
      return null;
    }
  };

  const saveIdentity = (ident) => {
    identity = ident;
    try {
      localStorage.setItem(IDENT_KEY, JSON.stringify(ident));
    } catch (_) { /* ignore */ }
  };

  const clearIdentity = () => {
    identity = null;
    try {
      localStorage.removeItem(IDENT_KEY);
      localStorage.removeItem(LEGACY_IDENT_KEY);
    } catch (_) { /* ignore */ }
  };

  /* ---------------- 头像 ---------------- */

  /** 头像预览：输入 URL / 身份恢复时更新面板预览图 */
  const updateAvatarPreview = () => {
    const input = $('msg-avatar');
    const preview = $('msg-avatar-preview');
    if (!input || !preview) return;
    const url = input.value.trim();
    preview.hidden = !url;
    if (url) {
      preview.style.backgroundImage = `url("${url.replace(/"/g, '')}")`;
    }
  };

  /** 发言时携带的自定义头像（本地覆盖，后端旧逻辑忽略未知字段） */
  const ownAvatar = () => identity?.avatar || $('msg-avatar')?.value.trim() || '';

  /** 留言是否属于当前身份（昵称+邮箱兜底匹配） */
  const isOwnComment = (c) => {
    if (!identity) return false;
    const sameMail = identity.mail && c.mail && identity.mail.toLowerCase() === c.mail.toLowerCase();
    const sameNick = identity.nick && c.nick === identity.nick;
    return sameMail || sameNick;
  };

  /** 展示头像：本人留言自定义头像 > Waline 账号头像（未登录访客也生效）> 后端 avatar（归一化到 Cravatar） */
  const resolveAvatar = (c) => {
    if (isOwnComment(c) && ownAvatar()) return ownAvatar();
    const account = accountAvatars[(c.nick || '').trim()];
    if (account) return account;
    return normalizeAvatarUrl(c.avatar);
  };

  /** 面板切换 */
  const showAuth = () => {
    const auth = $('msg-auth');
    const composer = $('msg-composer');
    if (auth) auth.hidden = false;
    if (composer) composer.hidden = true;
  };

  const showComposer = () => {
    const auth = $('msg-auth');
    const composer = $('msg-composer');
    if (auth) auth.hidden = true;
    if (composer) composer.hidden = false;
    const who = $('msg-who');
    if (who && identity) {
      who.textContent = identity.nick + (identity.mode === 'guest' ? '（游客）' : '');
    }
    const selfAv = $('msg-self-avatar');
    if (selfAv) {
      const av = ownAvatar();
      selfAv.onerror = () => { selfAv.hidden = true; }; // 账号头像 URL 失效时隐藏，避免裂图
      selfAv.hidden = !av;
      if (av) selfAv.src = av;
    }
    refreshSendState();
  };

  /** 切换身份面板 tab */
  const switchAuthTab = (mode) => {
    document.querySelectorAll('.msg-auth-tab').forEach((t) => {
      t.classList.toggle('active', t.dataset.mode === mode);
    });
    ['guest', 'login', 'register'].forEach((m) => {
      const form = $(`msg-auth-${m}`);
      if (form) form.hidden = m !== mode;
    });
  };

  /** 游客身份进入 */
  const enterGuest = () => {
    const nick = $('msg-nick')?.value.trim();
    const mail = $('msg-mail')?.value.trim() || '';
    if (!nick) {
      toast('先给自己起个昵称吧～');
      $('msg-nick')?.focus();
      return;
    }
    const avatar = $('msg-avatar')?.value.trim() || '';
    saveIdentity({ mode: 'guest', nick, mail, avatar });
    showComposer();
  };

  /** 注册并进入（后端注册接口已验证可用） */
  const doRegister = async () => {
    const nick = $('msg-reg-nick')?.value.trim();
    const mail = $('msg-reg-mail')?.value.trim();
    const pass = $('msg-reg-pass')?.value || '';
    const hint = $('msg-reg-hint');
    if (!nick || !mail || pass.length < 6) {
      if (hint) hint.textContent = '昵称、邮箱必填，密码至少 6 位';
      return;
    }
    if (hint) hint.textContent = '注册中…';
    try {
      const res = await fetch(`${MSG_SERVER}/api/user`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: mail, password: pass, nick }),
      });
      const json = await res.json();
      if (json.errno) {
        const errmsg = typeof json.errmsg === 'string' ? json.errmsg : '';
        if (errmsg.includes('USER_EXIST')) throw new Error('该邮箱已注册，可直接用游客身份留言');
        throw new Error(errmsg || '注册失败，请稍后再试');
      }
      const avatar = $('msg-avatar')?.value.trim() || '';
      saveIdentity({ mode: 'register', nick, mail, avatar });
      if (hint) hint.textContent = '';
      showComposer();
      toast('注册成功，欢迎～');
    } catch (e) {
      if (hint) hint.textContent = e.message || '注册失败，请稍后再试';
    }
  };

  /**
   * 登录（接口适配层）
   * 后端登录接口：POST /api/token {email, password}
   * 成功返回 {errno:0, data:{...user, token}}，密码错误/不存在返回 errno:1000
   */
  const doLogin = async () => {
    const mail = $('msg-login-mail')?.value.trim();
    const pass = $('msg-login-pass')?.value || '';
    const hint = $('msg-login-hint');
    if (!mail || !pass) {
      if (hint) hint.textContent = '请输入邮箱和密码';
      return;
    }
    if (hint) hint.textContent = '登录中…';
    try {
      const res = await fetch(`${MSG_SERVER}/api/token`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: mail, password: pass }),
      });
      const json = await res.json();
      if (json.errno) throw new Error(typeof json.errmsg === 'string' ? json.errmsg : '账号或密码错误');
      const user = json.data || {};

      // 若用户填写了自定义头像，登录后同步写入账号（后端 PUT /api/user 支持）
      const avatar = $('msg-avatar')?.value.trim() || user.avatar || '';
      if (avatar && user.token && avatar !== user.avatar) {
        try {
          await fetch(`${MSG_SERVER}/api/user`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${user.token}` },
            body: JSON.stringify({ avatar }),
          });
        } catch (_) { /* 头像同步失败不阻塞登录 */ }
      }
      saveIdentity({ mode: 'login', nick: user.display_name || user.nick || mail.split('@')[0], mail, token: user.token || '', avatar: avatar || user.avatar || '' });
      if (hint) hint.textContent = '';
      showComposer();
      toast('登录成功！');
    } catch (e) {
      if (hint) hint.textContent = e.message === '账号或密码错误'
        ? '账号或密码错误'
        : '登录失败，请检查账号密码是否正确';
    }
  };

  /* ---------------- 发表留言 ---------------- */

  const refreshSendState = () => {
    const btn = $('msg-send-btn');
    const text = $('msg-textarea');
    if (!btn || !text) return;
    btn.disabled = !identity || !text.value.trim() || text.value.length > MAX_LEN;
  };

  const submit = async () => {
    const textarea = $('msg-textarea');
    const btn = $('msg-send-btn');
    if (!textarea || !btn || !identity) return;

    const comment = textarea.value.trim();
    if (!comment) return;

    btn.disabled = true;
    btn.textContent = '发送中...';

    const body = new URLSearchParams({ url: MSG_PATH, comment, nick: identity.nick });
    if (identity.mail) body.set('mail', identity.mail);
    if (identity.token) body.set('token', identity.token);
    const avatar = ownAvatar();
    if (avatar) body.set('avatar', avatar);
    if (replyTarget) {
      body.set('pid', replyTarget.pid);
      body.set('rid', replyTarget.rid);
    }

    try {
      const res = await fetch(`${MSG_SERVER}/api/comment`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body.toString(),
      });
      const json = await res.json();
      if (json.errno) {
        const msg = typeof json.errmsg === 'string'
          ? json.errmsg
          : Object.values(json.errmsg || {}).join('；');
        throw new Error(msg || '发送失败');
      }
      textarea.value = '';
      textarea.style.height = 'auto';
      $('msg-counter').textContent = `0/${MAX_LEN}`;
      setReplyTarget(null);
      if (json.data?.status === 'approved') {
        toast('留言发表成功！');
        loadedPage = 0;
        loadComments(1);
      } else {
        toast('留言已提交，等待管理员审核后展示');
      }
    } catch (e) {
      toast(e.message || '发送失败了，请稍后再试');
    } finally {
      btn.textContent = '发送';
      refreshSendState();
    }
  };

  /* ---------------- 表情面板 ---------------- */

  const buildEmojiPanel = () => {
    const panel = $('msg-emoji-panel');
    if (!panel || panel.children.length) return;
    EMOJIS.forEach((emoji) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'msg-emoji-item';
      btn.textContent = emoji;
      btn.setAttribute('aria-label', `表情 ${emoji}`);
      panel.appendChild(btn);
    });
  };

  const insertEmoji = (emoji) => {
    const textarea = $('msg-textarea');
    if (!textarea) return;
    const start = textarea.selectionStart ?? textarea.value.length;
    const end = textarea.selectionEnd ?? textarea.value.length;
    const next = textarea.value.slice(0, start) + emoji + textarea.value.slice(end);
    if (next.length > MAX_LEN) return;
    textarea.value = next;
    const pos = start + emoji.length;
    textarea.setSelectionRange(pos, pos);
    textarea.focus();
    updateCounter();
  };

  const updateCounter = () => {
    const counter = $('msg-counter');
    const textarea = $('msg-textarea');
    if (!counter || !textarea) return;
    counter.textContent = `${textarea.value.length}/${MAX_LEN}`;
    counter.classList.toggle('over', textarea.value.length > MAX_LEN);
    refreshSendState();
  };

  /* ---------------- 聊天成员侧栏 ---------------- */

  const renderMembers = (comments) => {
    const list = $('msg-member-list');
    const countEl = $('msg-member-count');
    if (!list) return;

    const map = new Map();
    comments.forEach((c) => {
      const nick = c.nick || '匿名用户';
      const key = `${nick}|${c.link || ''}`;
      const item = map.get(key) || { nick, count: 0, avatar: '', isAdmin: false, device: '' };
      item.count += 1;
      item.avatar = resolveAvatar(c); // 含 Waline 账号头像索引，未登录也生效
      if (c.type === 'administrator') item.isAdmin = true;
      if (!item.device) item.device = [c.browser, c.os].filter(Boolean).join(' · ');
      map.set(key, item);
    });

    const members = [...map.values()].sort((a, b) => b.count - a.count);
    if (countEl) countEl.textContent = String(members.length);

    if (members.length === 0) {
      list.innerHTML = '<div class="msg-member-empty">还没有成员，快来抢沙发～</div>';
      return;
    }

    list.replaceChildren();
    members.forEach((m, i) => {
      const item = document.createElement('div');
      item.className = 'msg-member';
      item.style.animationDelay = `${i * 0.04}s`;

      item.appendChild(buildAvatar(m.avatar, m.nick));

      const info = document.createElement('div');
      info.className = 'msg-member-info';

      const nameLine = document.createElement('div');
      nameLine.className = 'msg-member-name-line';

      const name = document.createElement('span');
      name.className = 'msg-member-name';
      name.textContent = m.nick;
      nameLine.appendChild(name);

      if (m.isAdmin) {
        const badge = document.createElement('span');
        badge.className = 'msg-member-badge';
        badge.textContent = '站长';
        nameLine.appendChild(badge);
      }
      info.appendChild(nameLine);

      if (m.device) {
        const ua = document.createElement('div');
        ua.className = 'msg-member-ua';
        ua.textContent = m.device;
        info.appendChild(ua);
      }

      const points = document.createElement('span');
      points.className = 'msg-member-points';
      points.textContent = String(m.count);
      points.title = `留言 ${m.count} 条`;

      item.append(info, points);
      list.appendChild(item);
    });
  };

  const loadMembers = () =>
    apiGet('type=recent&count=50')
      .then((comments) => {
        const list = Array.isArray(comments) ? comments : [];
        indexAccountAvatars(list); // 先建账号头像索引，renderMembers/留言列表共用
        renderMembers(list);
      })
      .catch(() => {
        const list = $('msg-member-list');
        if (list) list.innerHTML = '<div class="msg-member-empty">成员列表加载失败</div>';
      });

  /* ---------------- 事件绑定 ---------------- */

  const bindOnce = () => {
    if (window.__msgBoardEventsBound) return;
    window.__msgBoardEventsBound = true;

    document.addEventListener('click', (e) => {
      const board = $('msg-board');
      if (!board) return;

      if (e.target.closest('#msg-notice-close')) {
        board.classList.add('notice-hidden');
        try { localStorage.setItem(NOTICE_KEY, '1'); } catch (_) { /* ignore */ }
        return;
      }
      if (e.target.closest('#msg-members-fab')) {
        board.classList.add('members-open');
        return;
      }
      if (e.target.closest('#msg-members-toggle')) {
        board.classList.remove('members-open');
        return;
      }
      if (e.target.closest('#msg-load-more')) {
        return; // 加载更多已废弃：改为上滑自动加载
      }
      if (e.target.closest('.msg-auth-tab')) {
        switchAuthTab(e.target.closest('.msg-auth-tab').dataset.mode);
        return;
      }
      if (e.target.closest('#msg-avatar-toggle')) {
        const row = $('msg-avatar-row');
        if (row) {
          row.hidden = !row.hidden;
          if (!row.hidden) $('msg-avatar')?.focus();
        }
        return;
      }
      if (e.target.closest('#msg-guest-enter')) {
        enterGuest();
        return;
      }
      if (e.target.closest('#msg-login-enter')) {
        doLogin();
        return;
      }
      if (e.target.closest('#msg-reg-enter')) {
        doRegister();
        return;
      }
      if (e.target.closest('#msg-mail-toggle')) {
        const mailInput = $('msg-mail');
        if (mailInput) {
          mailInput.hidden = false;
          mailInput.focus();
        }
        e.target.closest('#msg-mail-toggle').hidden = true;
        return;
      }
      if (e.target.closest('#msg-switch-identity')) {
        clearIdentity();
        showAuth();
        return;
      }
      if (e.target.closest('#msg-send-btn')) {
        submit();
        return;
      }
      if (e.target.closest('#msg-emoji-btn')) {
        const panel = $('msg-emoji-panel');
        if (panel) panel.hidden = !panel.hidden;
        return;
      }
      if (e.target.closest('#msg-reply-tip')) {
        setReplyTarget(null);
        return;
      }
      const emojiItem = e.target.closest('.msg-emoji-item');
      if (emojiItem) {
        insertEmoji(emojiItem.textContent);
        $('msg-emoji-panel').hidden = true;
        return;
      }
      const replyBtn = e.target.closest('.msg-reply-btn');
      if (replyBtn) {
        setReplyTarget({
          nick: replyBtn.dataset.nick,
          pid: replyBtn.dataset.pid,
          rid: replyBtn.dataset.rid,
        });
        $('msg-textarea')?.focus();
        return;
      }
      // 点击其他区域收起表情面板
      if (!e.target.closest('#msg-emoji-panel')) {
        const panel = $('msg-emoji-panel');
        if (panel && !panel.hidden) panel.hidden = true;
      }
    });

    document.addEventListener('input', (e) => {
      if (e.target === $('msg-textarea')) {
        // 微信风输入条：自适应高度（1~4 行）
        const el = e.target;
        el.style.height = 'auto';
        el.style.height = Math.min(el.scrollHeight, 110) + 'px';
        updateCounter();
      } else if (e.target === $('msg-avatar')) {
        updateAvatarPreview();
      }
    });

    document.addEventListener('keydown', (e) => {
      // 微信风：Enter 发送，Shift+Enter 换行
      if (e.target === $('msg-textarea') && e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        submit();
      }
    });

    document.addEventListener('pjax:complete', init);
    document.addEventListener('pjax:end', init);
  };

  const restoreState = () => {
    try {
      if (localStorage.getItem(NOTICE_KEY) === '1') {
        $('msg-board')?.classList.add('notice-hidden');
      }
    } catch (_) { /* ignore */ }

    // 身份恢复（兼容旧格式 {nick, mail} → 迁移为游客身份）
    identity = getIdentity();
    if (!identity) {
      try {
        const legacy = JSON.parse(localStorage.getItem(LEGACY_IDENT_KEY) || 'null');
        if (legacy && legacy.nick) {
          saveIdentity({ mode: 'guest', nick: legacy.nick, mail: legacy.mail || '' });
          if ($('msg-nick')) $('msg-nick').value = legacy.nick;
          if ($('msg-mail')) $('msg-mail').value = legacy.mail || '';
        }
      } catch (_) { /* ignore */ }
    }
    if (identity) {
      if ($('msg-avatar') && identity.avatar) $('msg-avatar').value = identity.avatar;
      showComposer();
    } else {
      showAuth();
    }
    updateAvatarPreview();
  };

  /* ---------------- 入口 ---------------- */

  let currentBoard = null;

  /** 真正请求数据（浮窗模式下由 messages-drawer.js 在首次打开时调用） */
  const loadData = () => {
    const board = $('msg-board');
    if (!board || board.dataset.msgLoaded) return;
    board.dataset.msgLoaded = '1';
    loadedPage = 0;
    bindListScroll();
    // 先取 recent 建立账号头像索引，再渲染留言：未登录访客也能看到 Waline 账号头像
    loadMembers().finally(() => loadComments(1));
  };
  window.__msgBoardLoad = loadData;

  const init = () => {
    const board = $('msg-board');
    if (!board) {
      currentBoard = null;
      return;
    }
    // 同一 DOM 节点不重复初始化；pjax 替换节点后正常重建
    if (board === currentBoard) return;
    currentBoard = board;
    restoreState();
    buildEmojiPanel();
    setReplyTarget(null);
    updateCounter();
    // 浮窗模式：未打开时不发请求，等首次打开再加载
    const modal = board.closest('.msg-modal');
    if (modal) {
      if (modal.classList.contains('open')) loadData();
      return;
    }
    loadData();
  };

  bindOnce();

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

/* movies.js — Personal Cinema Archive
 * 交互与渲染。ECharts 由页面 md 内联加载。
 * 兼容 pjax：init() 可重入，全局监听只绑一次。
 */
(function () {
  'use strict';

  var STATUS_LABELS = { wish: '想看', watching: '在看', watched: '看过' };
  var TYPE_LABELS = { movie: '电影', tv: '剧集', anime: '番剧', doc: '纪录/综艺' };

  var root = null;   // 每次 init() 重新解析当前页面的 .movies-page
  var state = {
    items: [],
    stats: null,
    status: 'all',
    type: '',
    q: '',
    openYears: Object.create(null)
  };
  var byId = Object.create(null);

  var $ = function (sel, ctx) { return (ctx || root).querySelector(sel); };
  var $$ = function (sel, ctx) { return Array.prototype.slice.call((ctx || root).querySelectorAll(sel)); };

  function fmtNum(n) { return (n || 0).toLocaleString(); }
  function fmtHours(mins) {
    var h = (mins || 0) / 60;
    return h >= 100 ? Math.round(h).toLocaleString() : h.toFixed(1);
  }

  function esc(s) {
    if (s == null) return '';
    return String(s).replace(/[&<>"']/g, function (c) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c];
    });
  }

  function starsHTML(rating) {
    var r = Number(rating) || 0;
    if (r <= 0) return '';
    var pct = Math.max(0, Math.min(100, (r / 5) * 100));
    return (
      '<span class="mv-card__stars" aria-label="' + r + ' / 5">' +
      '<span class="mv-star">★★★★★' +
      '<span class="mv-star__fill" style="clip-path:inset(0 ' + (100 - pct) + '% 0 0)">★★★★★</span>' +
      '</span></span>'
    );
  }

  function passFilter(item) {
    if (state.status !== 'all' && item.status !== state.status) return false;
    if (state.type && item.type !== state.type) return false;
    if (state.q) {
      var q = state.q.toLowerCase();
      var hay = [
        item.title_cn, item.title_original,
        (item.director || []).join(' '),
        (item.cast || []).join(' '),
        (item.tags || []).join(' '),
        (item.genres || []).join(' ')
      ].join(' ').toLowerCase();
      if (hay.indexOf(q) === -1) return false;
    }
    return true;
  }

  function cardHTML(i) {
    var poster = i.poster
      ? '<img class="mv-card__poster" src="' + esc(i.poster) + '" alt="' + esc(i.title_cn) + '" loading="lazy" decoding="async" onerror="this.replaceWith(Object.assign(document.createElement(\'div\'),{className:\'mv-card__poster mv-card__poster--placeholder\',textContent:\'' + esc((i.title_cn || '?').slice(0, 6)) + '\'}));">'
      : '<div class="mv-card__poster mv-card__poster--placeholder">' + esc((i.title_cn || '?').slice(0, 6)) + '</div>';

    var ratingVal = Number(i.my_rating) > 0 ? (Number(i.my_rating) * 2).toFixed(0) : '';
    var ratingHtml = ratingVal ? '<div class="mv-card__rating">' + ratingVal + '</div>' : '';
    var statusTag = '<div class="mv-card__status" data-status="' + esc(i.status) + '">' + esc(STATUS_LABELS[i.status] || '') + '</div>';
    var typeLabel = TYPE_LABELS[i.type] || '其他';

    return (
      '<div class="mv-card" data-id="' + esc(i.id) + '" tabindex="0" role="button" aria-label="' + esc(i.title_cn) + '">' +
        poster + ratingHtml + statusTag +
        '<div class="mv-card__overlay">' +
          '<h3 class="mv-card__title">' + esc(i.title_cn) + '</h3>' +
          '<div class="mv-card__type">' + esc(typeLabel) + '</div>' +
        '</div>' +
      '</div>'
    );
  }

  function renderHero() {
    var s = state.stats || {};
    var totalHours = Math.round((s.totalMinutes || 0) / 60);
    setStat('thisYear', fmtNum(s.thisYearCount));
    setStat('totalHours', fmtNum(totalHours));
    setStat('avgRating', (s.avgRating || 0).toFixed(1));
    setStat('topDirector', s.topDirector || '—');
    setStat('topCountry', s.topCountry || '—');
  }
  function setStat(key, val) {
    var el = $('.mv-stat[data-stat="' + key + '"] .mv-stat__num');
    if (el) el.textContent = val;
  }

  function renderTabs() {
    var items = state.items;
    var counts = { all: items.length, wish: 0, watching: 0, watched: 0 };
    items.forEach(function (i) { if (counts[i.status] !== undefined) counts[i.status]++; });
    $$('.mv-tab').forEach(function (t) {
      var s = t.getAttribute('data-status');
      var n = t.querySelector('.mv-tab__n');
      if (n) n.textContent = counts[s] != null ? counts[s] : '';
      t.classList.toggle('is-active', s === state.status);
    });
  }

  function renderGrid() {
    var host = $('#mv-grid');
    var pHost = $('#mv-pagination');
    if (!host) return;
    var visible = state.items.filter(passFilter);
    if (!visible.length) {
      host.innerHTML = '<div class="mv-empty" style="display:block;grid-column:1/-1">没有符合条件的记录</div>';
      pHost.hidden = true;
      return;
    }

    var totalPages = Math.ceil(visible.length / state.pageSize);
    if (state.page > totalPages) state.page = totalPages;
    if (state.page < 1) state.page = 1;

    var start = (state.page - 1) * state.pageSize;
    var end = start + state.pageSize;
    var pageItems = visible.slice(start, end);

    host.innerHTML = pageItems.map(cardHTML).join('');
    renderPagination(totalPages);
  }

  function renderPagination(totalPages) {
    var pHost = $('#mv-pagination');
    if (totalPages <= 1) {
      pHost.hidden = true;
      return;
    }
    pHost.hidden = false;
    var html = '';
    html += '<button class="mv-page-btn" data-page="' + (state.page - 1) + '" ' + (state.page === 1 ? 'disabled' : '') + '>‹</button>';

    var startPage = Math.max(1, state.page - 2);
    var endPage = Math.min(totalPages, startPage + 4);
    if (endPage - startPage < 4) {
      startPage = Math.max(1, endPage - 4);
    }

    for (var p = startPage; p <= endPage; p++) {
      html += '<button class="mv-page-btn ' + (p === state.page ? 'is-active' : '') + '" data-page="' + p + '">' + p + '</button>';
    }

    html += '<button class="mv-page-btn" data-page="' + (state.page + 1) + '" ' + (state.page === totalPages ? 'disabled' : '') + '>›</button>';
    pHost.innerHTML = html;
  }

  var gridObserver = null;
  function bindGridResize() {
    var container = $('.mv-list-container');
    if (!container || typeof ResizeObserver === 'undefined') return;
    if (gridObserver) gridObserver.disconnect();
    gridObserver = new ResizeObserver(debounce(function() {
      var w = container.clientWidth;
      var gap = window.innerWidth <= 768 ? 16 : 28;
      var cols = Math.floor((w + gap) / (156 + gap));
      cols = Math.max(2, cols);
      var newSize = cols * 2;
      if (state.pageSize !== newSize) {
        state.pageSize = newSize;
        state.page = 1;
        renderGrid();
      }
    }, 150));
    gridObserver.observe(container);
  }

  function bindGrid() {
    root.addEventListener('click', function(e) {
      var card = e.target.closest('.mv-card');
      if (card) {
        openModal(card.getAttribute('data-id'));
        return;
      }
      var btn = e.target.closest('.mv-page-btn');
      if (btn && !btn.disabled) {
        state.page = parseInt(btn.getAttribute('data-page'), 10);
        renderGrid();
        var container = $('.mv-list-container');
        if (container) container.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });

    root.addEventListener('keydown', function(e) {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      var card = e.target.closest('.mv-card');
      if (card) { e.preventDefault(); openModal(card.getAttribute('data-id')); }
    });
  }

  function bindTabs() {
    $$('.mv-tab').forEach(function (t) {
      t.addEventListener('click', function () {
        state.status = t.getAttribute('data-status');
        state.page = 1;
        renderTabs();
        renderGrid();
      });
    });
    $$('.mv-filter').forEach(function (f) {
      var evt = f.tagName === 'SELECT' ? 'change' : 'input';
      f.addEventListener(evt, debounce(function () {
        var key = f.getAttribute('data-filter');
        state[key] = f.value;
        state.page = 1;
        renderGrid();
      }, 180));
    });
  }

  function debounce(fn, ms) {
    var t; return function () {
      var ctx = this, args = arguments;
      clearTimeout(t);
      t = setTimeout(function () { fn.apply(ctx, args); }, ms);
    };
  }

  /* ------ MODAL ------ */
  function openModal(id) {
    var i = byId[id];
    if (!i) return;
    var modal = $('.mv-modal');
    modal.innerHTML = modalHTML(i);
    modal.hidden = false;
    requestAnimationFrame(function () { modal.classList.add('is-open'); });
    document.body.style.overflow = 'hidden';
    var closeBtn = modal.querySelector('.mv-modal__close');
    if (closeBtn) closeBtn.focus();
    if (location.hash !== '#m/' + id) history.replaceState(null, '', '#m/' + id);
  }

  function closeModal() {
    var modal = $('.mv-modal');
    if (!modal || modal.hidden) return;
    modal.classList.remove('is-open');
    setTimeout(function () {
      modal.hidden = true;
      modal.innerHTML = '';
    }, 250);
    document.body.style.overflow = '';
    if (location.hash.indexOf('#m/') === 0) history.replaceState(null, '', location.pathname);
  }

  function modalHTML(i) {
    var backdrop = i.backdrop || i.poster || '';
    var poster = i.poster
      ? '<img class="mv-modal__poster" src="' + esc(i.poster) + '" alt="' + esc(i.title_cn) + '">'
      : '<div class="mv-modal__poster mv-card__poster--placeholder">' + esc((i.title_cn || '?').slice(0, 6)) + '</div>';
    var runtime = i.runtime ? esc(i.runtime) + ' 分钟' : '—';
    var meta = [
      { l: '导演', v: (i.director || []).join(' / ') || '—' },
      { l: '主演', v: (i.cast || []).slice(0, 3).join(' / ') || '—' },
      { l: '国家', v: (i.countries || []).join(' / ') || '—' },
      { l: '类型', v: (i.genres || []).join(' · ') || '—' },
      { l: '时长', v: runtime },
      { l: '首映', v: i.year || '—' },
      { l: '观看', v: i.watched_date || '—' },
      { l: '平台', v: i.platform || '—' },
      { l: '我的评分', v: Number(i.my_rating) > 0 ? Number(i.my_rating).toFixed(1) + ' / 5' : '未评' },
      { l: '豆瓣', v: i.douban_rating != null ? i.douban_rating : '—' }
    ];
    var quotesHTML = (i.quotes && i.quotes.length)
      ? '<div class="mv-modal__quotes">' + i.quotes.map(function (q) {
          return '<div class="mv-modal__quote">' + esc(q) + '</div>';
        }).join('') + '</div>'
      : '';
    var reviewText = i.long_review_md && i.long_review_md.trim()
      ? i.long_review_md
      : (i.short_review || '');
    var reviewHTML = reviewText
      ? '<div class="mv-modal__review">' + esc(reviewText).replace(/\n/g, '<br>') + '</div>'
      : '';
    var aiHTML = i.ai_summary
      ? '<div class="mv-modal__review" style="opacity:.75;font-style:italic">AI · ' + esc(i.ai_summary) + '</div>'
      : '';
    var tagsHTML = (i.tags && i.tags.length)
      ? '<div class="mv-modal__tags">' + i.tags.map(function (t) {
          return '<span class="mv-modal__tag">' + esc(t) + '</span>';
        }).join('') + '</div>'
      : '';

    return (
      '<div class="mv-modal__card" role="document">' +
        '<button class="mv-modal__close" aria-label="关闭">×</button>' +
        '<div class="mv-modal__backdrop" style="background-image:url(' + esc(backdrop) + ')"></div>' +
        '<div class="mv-modal__body">' +
          '<div>' + poster + '</div>' +
          '<div class="mv-modal__meta">' +
            '<h2>' + esc(i.title_cn) + '</h2>' +
            '<div class="mv-modal__orig">' + esc(i.title_original || '') + '</div>' +
            tagsHTML +
            '<div class="mv-modal__row">' +
              meta.map(function (m) {
                return '<div><div class="mv-modal__label">' + m.l + '</div><div class="mv-modal__value">' + esc(m.v) + '</div></div>';
              }).join('') +
            '</div>' +
            reviewHTML +
            aiHTML +
            quotesHTML +
          '</div>' +
        '</div>' +
      '</div>'
    );
  }

  function bindModal() {
    var modal = $('.mv-modal');
    if (!modal || modal.dataset.bound) return;
    modal.dataset.bound = '1';
    modal.addEventListener('click', function (e) {
      if (e.target === modal || e.target.closest('.mv-modal__close')) closeModal();
    });
  }

  // document/window 级监听只绑一次（window 跨 pjax 存活）。
  // pjax 会整段重跑本脚本 → 每次 init 刷新 window.__mvActive 指向最新闭包，
  // 一次性监听器据此调用当前页面的 open/closeModal，避免调用已失效的旧闭包。
  function bindGlobalOnce() {
    window.__mvActive = { openModal: openModal, closeModal: closeModal };
    if (window.__mvGlobalBound) return;
    window.__mvGlobalBound = true;
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && window.__mvActive) window.__mvActive.closeModal();
    });
    window.addEventListener('hashchange', function () {
      if (!document.querySelector('.movies-page') || !window.__mvActive) return;
      var m = location.hash.match(/^#m\/(.+)$/);
      if (m) window.__mvActive.openModal(m[1]); else window.__mvActive.closeModal();
    });
  }

  /* ------ CHARTS ------ */
  var charts = {};
  var chartsInit = false;
  var chartsObserver = null;
  function initChartsIfReady() {
    if (chartsInit) return;
    var viz = $('.mv-viz');
    if (!viz) return;
    if (chartsObserver) chartsObserver.disconnect();
    chartsObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (ent) {
        if (ent.isIntersecting) {
          if (!chartsInit && typeof echarts !== 'undefined') drawCharts();
          if (chartsInit && chartsObserver) chartsObserver.disconnect();
        }
      });
    }, { rootMargin: '200px' });
    chartsObserver.observe(viz);
  }

  function drawCharts() {
    chartsInit = true;
    var s = state.stats || {};
    var baseText = { color: '#8a8a92', fontFamily: '-apple-system, "PingFang SC", sans-serif' };
    var gridBase = { left: '3%', right: '4%', bottom: '10%', top: '10%', containLabel: true };
    var lineColor = 'rgba(255,255,255,0.06)';

    charts.trend = echarts.init($('#mv-chart-trend'));
    var trend = s.yearlyTrend || [];
    charts.trend.setOption({
      textStyle: baseText,
      grid: gridBase,
      tooltip: { trigger: 'axis', backgroundColor: 'rgba(15,15,20,0.95)', borderColor: 'rgba(255,255,255,.06)', textStyle: { color: '#ececee' } },
