          var dur = audio.duration || 0;
          if (slider && dur) slider.value = (audio.currentTime / dur) * 100;
          if (curEl) curEl.textContent = fmt(audio.currentTime);
          if (totEl) totEl.textContent = fmt(dur);
          var playBtn = ctrl.querySelector('[data-act=play]');
          if (playBtn) playBtn.textContent = audio.paused ? '▶' : '⏸';
        }
      }

      renderer.render(scene, camera);
    }

    ctrl.querySelector('.mt-slider').addEventListener('input', function () {
      var audio = ap && ap.audio;
      if (audio && isFinite(audio.duration) && audio.duration) {
        audio.currentTime = (this.value / 100) * audio.duration;
      }
    });

    ctrl.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-act]');
      if (!btn || !ap) return;
      var act = btn.dataset.act;
      if (act === 'play') {
        if (ap.toggle) ap.toggle(); else if (ap.audio) ap.audio.paused ? ap.audio.play() : ap.audio.pause();
      } else if (act === 'prev') {
        if (ap.skipBack) ap.skipBack(); else if (ap.list) ap.list.switch((ap.list.index || 0) - 1);
      } else if (act === 'next') {
        if (ap.skipForward) ap.skipForward(); else if (ap.list) ap.list.switch((ap.list.index || 0) + 1);
      } else if (act === 'mode') {
        if (ap.list && ap.list.loop) {
          var modes = ['all', 'one', 'none'];
          var cur = modes.indexOf(ap.list.loop);
          ap.list.loop = modes[(cur + 1) % 3];
          btn.textContent = ap.list.loop === 'one' ? '🔂' : (ap.list.loop === 'none' ? '⏭' : '🔁');
        }
      } else if (act === 'volume') {
        if (ap.volume) ap.volume(ap.audio && ap.audio.volume > 0 ? 0 : 0.7);
      }
      analyzer.resume();
    });

    function resize() {
      var w = container.clientWidth || window.innerWidth;
      var h = container.clientHeight || window.innerHeight - 52;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    }
    window.addEventListener('resize', resize);
    var ro = null;
    if (typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver(function () { resize(); });
      ro.observe(container);
    }

    function destroy() {
      cancelAnimationFrame(raf);
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerup', onPointerUp);
      window.removeEventListener('resize', resize);
      if (ro) ro.disconnect();
      canvas.removeEventListener('pointerdown', onPointerDown);
      canvas.removeEventListener('wheel', onWheel);
      canvas.removeEventListener('click', onCanvasClick);
      geo.dispose(); mat.dispose();
      meteorGeo.dispose(); meteorMat.dispose();
      sparkGeo.dispose(); sparkMat.dispose();
      renderer.dispose();
      if (canvas.parentNode) canvas.parentNode.removeChild(canvas);
      if (ctrl.parentNode) ctrl.parentNode.removeChild(ctrl);
      if (pl.parentNode) pl.parentNode.removeChild(pl);
      if (lyr.parentNode) lyr.parentNode.removeChild(lyr);
    }

    var api = {
      getCanvas: function () { return canvas; },
      setAudio: function (audioEl) {
        analyzer.attach(audioEl);
        if (audioEl) audioEl.addEventListener('play', function () { analyzer.resume(); });
      },
      attachPlayer: function (player) {
        ap = player;
        if (player && player.audio) {
          analyzer.attach(player.audio);
          player.audio.addEventListener('play', function () { analyzer.resume(); });
        }
        syncTrack(true);
        syncPlaylist();
      },
      resize: resize,
      destroy: destroy,
      setPalette: function (p) {
        p = p || {};
        if (p.coolCore) uniforms.uCoolCore.value.set(p.coolCore);
        if (p.coolEdge) uniforms.uCoolEdge.value.set(p.coolEdge);
        if (p.warmCore) uniforms.uWarmCore.value.set(p.warmCore);
        if (p.warmEdge) uniforms.uWarmEdge.value.set(p.warmEdge);
        if (p.ripple) uniforms.uRippleColor.value.set(p.ripple);
        if (p.bg) { scene.background.set(p.bg); scene.fog.color.set(p.bg); }
      }
    };

    resize();
    raf = requestAnimationFrame(frame);
    return api;
  }

  window.MusicTerrain = { create: create };
})();

/* ============================================
 * Live2D 智能场景对话系统（增强版）
 * 功能：
 *   1. 打字机效果逐字输出
 *   2. 场景感知：滚动底部、停留时长、深夜、页面类型
 *   3. 对话框星空魔法样式
 *   4. 守护精灵模式 — 根据博客更新频率改变态度
 * ============================================ */

(() => {
  'use strict';

  const TYPING_SPEED = 60;
  const COOLDOWN = 800;
  const SCENE_PRIORITY = 50;

  let typing = false;
  let locked = false;
  let currentTimer = null;
  let lastText = '';
  let sceneTimer = null;
  let stayTimer = null;

  /* ----- 打字机核心 ----- */
  const typewrite = (el, text) => {
    if (currentTimer) clearInterval(currentTimer);
    typing = true;
    locked = true;
    el.textContent = '';
    let i = 0;
    currentTimer = setInterval(() => {
      el.textContent += text[i];
      i++;
      if (i >= text.length) {
        clearInterval(currentTimer);
        currentTimer = null;
        typing = false;
        setTimeout(() => { locked = false; }, COOLDOWN);
      }
    }, TYPING_SPEED);
  };

  const unlock = () => { locked = false; };

  const scene = {
    say(text, timeout = 6000) {
      const el = document.getElementById('live2d-tips');
      if (!el) return;
      sessionStorage.setItem('live2d-priority', SCENE_PRIORITY);
      el.innerHTML = text;
      el.classList.add('live2d-tips-active');
      if (sceneTimer) clearTimeout(sceneTimer);
      sceneTimer = setTimeout(() => {
        sessionStorage.removeItem('live2d-priority');
        el.classList.remove('live2d-tips-active');
        sceneTimer = null;
      }, timeout);
    },
  };

  /* ----- 守护精灵模式 ----- */
  let guardianState = null; // 'happy' | 'sad' | 'angry'

  const getGuardianState = (days) => {
    if (days <= 3) return { mood: 'happy', icon: '🕺', msg: '最近更新了！好开心～要一起努力哦！', face: '正常' };
    if (days <= 7) return { mood: 'normal', icon: '😊', msg: '主人最近还好吗？', face: '正常' };
    if (days <= 14) return { mood: 'worried', icon: '😟', msg: '已经一周没更新了...主人是不是太忙了？', face: '正常' };
    if (days <= 30) return { mood: 'sad', icon: '😞', msg: '快半个月了…主人不要我了吗？', face: '伤心' };
    return { mood: 'angry', icon: '😤', msg: '一个月不更新！太过分了！哼！', face: '生气' };
  };

  const initGuardian = () => {
    fetch('/site-meta.json')
      .then(r => r.json())
      .then(data => {
        const state = getGuardianState(data.daysSinceLastUpdate);
        guardianState = state.mood;

        // 侧边栏或 footer 显示博客状态
        const badge = document.createElement('div');
        badge.id = 'guardian-badge';
        badge.style.cssText =
          'margin-top:8px;padding:8px 12px;border-radius:8px;font-size:12px;' +
          'text-align:center;line-height:1.5;';

        if (state.mood === 'happy') {
          badge.style.background = 'rgba(76,175,80,0.1)';
          badge.style.border = '1px solid rgba(76,175,80,0.3)';
          badge.style.color = '#4caf50';
          badge.innerHTML = `🕺 Miku：主人最近很勤快呢！`;
        } else if (state.mood === 'sad') {
          badge.style.background = 'rgba(255,152,0,0.1)';
          badge.style.border = '1px solid rgba(255,152,0,0.3)';
          badge.style.color = '#ff9800';
          badge.innerHTML = `😞 Miku：好久没更新了…`;
        } else if (state.mood === 'angry') {
          badge.style.background = 'rgba(244,67,54,0.1)';
          badge.style.border = '1px solid rgba(244,67,54,0.3)';
          badge.style.color = '#f44336';
          badge.innerHTML = `😤 Miku：已经 ${data.daysSinceLastUpdate} 天没更新了！！`;
        } else {
          badge.style.opacity = '0.6';
          badge.innerHTML = `📝 上次更新：${data.daysSinceLastUpdate} 天前`;
        }

        // 注入到侧边栏
        const injectBadge = () => {
          if (document.getElementById('guardian-badge')) return;
          const sidebar = document.querySelector('aside#sidebar');
          if (!sidebar) { setTimeout(injectBadge, 500); return; }
          const gameWidget = document.getElementById('miku-game-widget');
          if (gameWidget && gameWidget.parentNode) {
            gameWidget.parentNode.insertBefore(badge, gameWidget.nextSibling);
          } else {
            const wa = sidebar.querySelector('.sidebar-widget');
            if (wa) wa.appendChild(badge);
            else sidebar.appendChild(badge);
          }
        };
        setTimeout(injectBadge, 1500);

        // 非 happy 状态，Miku 在首页会多说一句
        if (state.mood !== 'happy' && window.location.pathname === '/') {
          setTimeout(() => scene.say(state.msg, 6000), 4000);
        }
      })
      .catch(() => {});
  };

  /* ----- 原场景 ---- */
  const initScrollTrigger = () => {
    let hasTriggered = false;
    window.addEventListener('scroll', () => {
      if (hasTriggered) return;
      const scrollPercent = window.scrollY / (document.documentElement.scrollHeight - window.innerHeight);
      if (scrollPercent > 0.85) {
        hasTriggered = true;
        const msgs = guardianState === 'sad' ? ['居然看完了…谢谢你来看我','虽然主人不更新，但还有你在'] : ['居然全部看完了…给你点赞 👍','看完了！要不要翻翻其他文章？'];
        scene.say(msgs[Math.floor(Math.random() * msgs.length)]);
      }
    }, { passive: true });
  };

  const initPageGreeting = () => {
    const path = window.location.pathname;
    let msg = '';
    if (path === '/' || path === '/index.html') {
      if (guardianState === 'angry') msg = '哼！你来了，但主人不更新有什么用…';
      else if (guardianState === 'sad') msg = '欢迎回家…虽然这里好久没变化了';
      else msg = '欢迎回家～ 看看主人最近写了什么吧';
    } else if (path.startsWith('/about')) msg = '想了解主人吗？他是个很有趣的人呢～';
    else if (path.startsWith('/friend')) msg = '来认识主人的朋友们吧！';
    else if (path.startsWith('/gallery')) msg = '来看看主人拍的照片！';
    else if (path.startsWith('/diary')) msg = '主人的碎碎念都在这里啦～';
    else if (path.match(/^\/(\d{4})\//)) msg = guardianState === 'angry' ? '又来看旧文章吗…' : '又有新文章可以看啦～';
    if (msg) setTimeout(() => scene.say(msg, 5000), 800);
  };

  const initNightCheck = () => {
    const hour = new Date().getHours();
    if (hour >= 23 || hour < 5) {
      setTimeout(() => { scene.say('这么晚了还不睡！要注意身体呀 ⚠️', 5000); }, 5000);
    }
  };

  const initStayTimer = () => {
    stayTimer = setTimeout(() => { scene.say('看了好一会儿了呢，要喝杯水休息下吗～', 5000); }, 120000);
  };

  /* ----- MutationObserver ----- */
  const initObserver = () => {
    const target = document.getElementById('live2d-tips');
    if (!target) { setTimeout(initObserver, 500); return; }

    const observer = new MutationObserver(() => {
      if (typing) return;
      const text = target.textContent.trim();
      if (!text || text === lastText) return;
      if (locked) { target.textContent = lastText; return; }
      lastText = text;
      typewrite(target, text);
    });

    observer.observe(target, { childList: true, subtree: true, characterData: true });

    const waifu = document.getElementById('waifu') || document.getElementById('live2d-plugin');
    if (waifu) { waifu.addEventListener('click', unlock); waifu.addEventListener('mouseenter', unlock); }
    target.addEventListener('click', unlock);
    console.log('[Live2D Scene] 智能对话系统已启动 ✨');
  };

  const boot = () => {
    initObserver();
    initScrollTrigger();
    initNightCheck();
    initStayTimer();
    initGuardian();
    setTimeout(initPageGreeting, 2000);
  };

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();

/* novels.js — Personal Reading Archive (书架)
 * 交互与渲染。ECharts 由页面 md 内联加载。
 * 兼容 pjax：init() 可重入，全局监听只绑一次。
 */
(function () {
  'use strict';

  var STATUS_LABELS = { wish: '想读', reading: '在读', finished: '读完' };

  var root = null;   // 每次 init() 重新解析当前页面的 .novels-page
  var state = {
    items: [],
    stats: null,
    status: 'all',
    q: ''
  };
  var byId = Object.create(null);

  var $ = function (sel, ctx) { return (ctx || root).querySelector(sel); };
  var $$ = function (sel, ctx) { return Array.prototype.slice.call((ctx || root).querySelectorAll(sel)); };

  function fmtNum(n) { return (n || 0).toLocaleString(); }
  function fmtWords(w) {
    var n = Number(w) || 0;
    if (n <= 0) return '';
    if (n < 1) return Math.round(n * 10000).toLocaleString() + ' 字';
    return (n >= 100 ? n.toFixed(0) : n.toFixed(1)) + ' 万字';
  }

  function esc(s) {
    if (s == null) return '';
    return String(s).replace(/[&<>"']/g, function (c) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c];
    });
  }

  function starsHTML(rating) {
    var r = Number(rating) || 0;
    if (r <= 0) return '';
    var pct = Math.max(0, Math.min(100, (r / 5) * 100));
    return (
      '<span class="nv-card__stars" aria-label="' + r + ' / 5">' +
      '<span class="nv-star">★★★★★' +
      '<span class="nv-star__fill" style="clip-path:inset(0 ' + (100 - pct) + '% 0 0)">★★★★★</span>' +
      '</span></span>'
    );
  }

  function passFilter(item) {
    if (state.status !== 'all' && item.status !== state.status) return false;
    if (state.q) {
      var q = state.q.toLowerCase();
      var hay = [
        item.title, item.author,
        (item.categories || []).join(' '),
        (item.tags || []).join(' '),
        item.notes
      ].join(' ').toLowerCase();
      if (hay.indexOf(q) === -1) return false;
    }
    return true;
  }

  function progressHTML(i) {
    var pct = Number(i.progress_pct);
    if (Number.isFinite(pct) && pct > 0 && pct <= 100) {
      return (
        '<div class="nv-card__progress">' +
          '<div class="nv-card__progress-track"><div class="nv-card__progress-fill" style="width:' + Math.min(100, pct) + '%"></div></div>' +
          '<span class="nv-card__progress-text">' + esc(i.progress || pct + '%') + '</span>' +
        '</div>'
      );
    }
    return i.progress ? '<div class="nv-card__progress nv-card__progress--text">' + esc(i.progress) + '</div>' : '';
  }

  function cardHTML(i) {
    var cover = i.cover
      ? '<img class="nv-card__cover" src="' + esc(i.cover) + '" alt="' + esc(i.title) + '" loading="lazy" decoding="async" onerror="this.replaceWith(Object.assign(document.createElement(\'div\'),{className:\'nv-card__cover nv-card__cover--placeholder\',textContent:\'' + esc((i.title || '?').slice(0, 6)) + '\'}));">'
      : '<div class="nv-card__cover nv-card__cover--placeholder">' + esc((i.title || '?').slice(0, 6)) + '</div>';

    var ratingVal = Number(i.my_rating) > 0 ? (Number(i.my_rating) * 2).toFixed(0) : '';
    var ratingHtml = ratingVal ? '<div class="nv-card__rating">' + ratingVal + '</div>' : '';
    var statusTag = '<div class="nv-card__status" data-status="' + esc(i.status) + '">' + esc(STATUS_LABELS[i.status] || '') + '</div>';
    var cat = (i.categories && i.categories[0]) || i.category || '';

    return (
      '<div class="nv-card" data-id="' + esc(i.id) + '" tabindex="0" role="button" aria-label="' + esc(i.title) + '">' +
        cover + ratingHtml + statusTag +
        '<div class="nv-card__overlay">' +
          '<h3 class="nv-card__title">' + esc(i.title) + '</h3>' +
          '<div class="nv-card__author">' + esc(i.author || '佚名') + '</div>' +
          progressHTML(i) +
          (cat ? '<div class="nv-card__cat">' + esc(cat) + '</div>' : '') +
        '</div>' +
      '</div>'
    );
  }

  function renderHero() {
    var s = state.stats || {};
    setStat('reading', fmtNum(s.reading));
    setStat('finished', fmtNum(s.finished));
    setStat('words', (s.totalWordsW || 0) >= 100 ? (s.totalWordsW || 0).toFixed(0) : (s.totalWordsW || 0).toFixed(1));
    setStat('avgRating', (s.avgRating || 0).toFixed(1));
    setStat('topAuthor', s.topAuthor || '—');
  }
  function setStat(key, val) {
    var el = $('.nv-stat[data-stat="' + key + '"] .nv-stat__num');
    if (el) {
      el.childNodes[0].textContent = val; // 保留 unit span
    }
  }

  function renderTabs() {
    var items = state.items;
    var counts = { all: items.length, wish: 0, reading: 0, finished: 0 };
    items.forEach(function (i) { if (counts[i.status] !== undefined) counts[i.status]++; });
    $$('.nv-tab').forEach(function (t) {
      var s = t.getAttribute('data-status');
      var n = t.querySelector('.nv-tab__n');
      if (n) n.textContent = counts[s] != null ? counts[s] : '';
      t.classList.toggle('is-active', s === state.status);
    });
  }

  function renderGrid() {
    var host = $('#nv-grid');
    var pHost = $('#nv-pagination');
    if (!host) return;
    var visible = state.items.filter(passFilter);
    if (!visible.length) {
      host.innerHTML = '<div class="nv-empty" style="display:block;grid-column:1/-1">没有符合条件的记录</div>';
      pHost.hidden = true;
      return;
    }

    var totalPages = Math.ceil(visible.length / state.pageSize);
    if (state.page > totalPages) state.page = totalPages;
    if (state.page < 1) state.page = 1;

    var start = (state.page - 1) * state.pageSize;
    var end = start + state.pageSize;
    var pageItems = visible.slice(start, end);

    host.innerHTML = pageItems.map(cardHTML).join('');
    renderPagination(totalPages);
  }

  function renderPagination(totalPages) {
    var pHost = $('#nv-pagination');
    if (totalPages <= 1) {
      pHost.hidden = true;
      return;
    }
    pHost.hidden = false;
    var html = '';
    html += '<button class="nv-page-btn" data-page="' + (state.page - 1) + '" ' + (state.page === 1 ? 'disabled' : '') + '>‹</button>';

    var startPage = Math.max(1, state.page - 2);
    var endPage = Math.min(totalPages, startPage + 4);
    if (endPage - startPage < 4) {
      startPage = Math.max(1, endPage - 4);
    }

    for (var p = startPage; p <= endPage; p++) {
      html += '<button class="nv-page-btn ' + (p === state.page ? 'is-active' : '') + '" data-page="' + p + '">' + p + '</button>';
    }

    html += '<button class="nv-page-btn" data-page="' + (state.page + 1) + '" ' + (state.page === totalPages ? 'disabled' : '') + '>›</button>';
    pHost.innerHTML = html;
  }

  var gridObserver = null;
  function bindGridResize() {
    var container = $('.nv-list-container');
    if (!container || typeof ResizeObserver === 'undefined') return;
    if (gridObserver) gridObserver.disconnect();
    gridObserver = new ResizeObserver(debounce(function () {
      var w = container.clientWidth;
      var gap = window.innerWidth <= 768 ? 16 : 28;
      var cols = Math.floor((w + gap) / (156 + gap));
      cols = Math.max(2, cols);
      var newSize = cols * 2;
      if (state.pageSize !== newSize) {
        state.pageSize = newSize;
        state.page = 1;
        renderGrid();
      }
    }, 150));
    gridObserver.observe(container);
  }

  function bindGrid() {
    root.addEventListener('click', function (e) {
      var card = e.target.closest('.nv-card');
      if (card) {
        openModal(card.getAttribute('data-id'));
        return;
      }
      var btn = e.target.closest('.nv-page-btn');
      if (btn && !btn.disabled) {
        state.page = parseInt(btn.getAttribute('data-page'), 10);
        renderGrid();
        var container = $('.nv-list-container');
        if (container) container.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });

    root.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      var card = e.target.closest('.nv-card');
      if (card) { e.preventDefault(); openModal(card.getAttribute('data-id')); }
    });
  }

  function bindTabs() {
    $$('.nv-tab').forEach(function (t) {
      t.addEventListener('click', function () {
        state.status = t.getAttribute('data-status');
        state.page = 1;
        renderTabs();
        renderGrid();
      });
    });
    $$('.nv-filter').forEach(function (f) {
      f.addEventListener('input', debounce(function () {
        state[f.getAttribute('data-filter')] = f.value;
        state.page = 1;
        renderGrid();
      }, 180));
    });
  }

  function debounce(fn, ms) {
    var t; return function () {
      var ctx = this, args = arguments;
      clearTimeout(t);
      t = setTimeout(function () { fn.apply(ctx, args); }, ms);
    };
  }

  /* ------ MODAL ------ */
  function openModal(id) {
    var i = byId[id];
    if (!i) return;
    var modal = $('.nv-modal');
    modal.innerHTML = modalHTML(i);
    modal.hidden = false;
    requestAnimationFrame(function () { modal.classList.add('is-open'); });
    document.body.style.overflow = 'hidden';
    var closeBtn = modal.querySelector('.nv-modal__close');
    if (closeBtn) closeBtn.focus();
    if (location.hash !== '#b/' + id) history.replaceState(null, '', '#b/' + id);
  }

  function closeModal() {
    var modal = $('.nv-modal');
    if (!modal || modal.hidden) return;
    modal.classList.remove('is-open');
    setTimeout(function () {
      modal.hidden = true;
      modal.innerHTML = '';
    }, 250);
    document.body.style.overflow = '';
    if (location.hash.indexOf('#b/') === 0) history.replaceState(null, '', location.pathname);
  }

  function modalHTML(i) {
    var backdrop = i.cover || '';
    var cover = i.cover
      ? '<img class="nv-modal__cover" src="' + esc(i.cover) + '" alt="' + esc(i.title) + '">'
      : '<div class="nv-modal__cover nv-card__cover--placeholder">' + esc((i.title || '?').slice(0, 6)) + '</div>';
    var words = fmtWords(i.word_count_w) || '—';
    var meta = [
      { l: '作者', v: i.author || '—' },
      { l: '分类', v: (i.categories || []).join(' · ') || i.category || '—' },
      { l: '字数', v: words },
      { l: '连载', v: i.serial_status || '—' },
