  /* ------ INIT (可重入，兼容 pjax) ------ */
  function init() {
    var el = document.querySelector('.novels-page');
    if (!el) return;               // 当前页面不是书架，退出
    if (el.dataset.nvReady) return; // 已初始化过（同一 DOM 节点），跳过
    el.dataset.nvReady = '1';
    root = el;

    // 重置每次进入页面的状态（pjax 会给全新 DOM）
    state = { items: [], stats: null, status: 'all', q: '', page: 1, pageSize: 12 };
    byId = Object.create(null);
    charts = {};
    chartsInit = false;
    if (chartsObserver) { chartsObserver.disconnect(); chartsObserver = null; }
    if (gridObserver) { gridObserver.disconnect(); gridObserver = null; }

    var src = root.getAttribute('data-src') || '/novels/data.json';
    fetch(src)
      .then(function (r) { return r.json(); })
      .then(function (payload) {
        if (!document.body.contains(root)) return; // pjax 已切走，放弃渲染
        state.items = payload.items || [];
        state.stats = payload.stats || {};
        state.items.forEach(function (i) { byId[i.id] = i; });

        preloadTopCovers();

        renderHero();
        renderTabs();

        // Initial setup for grid size
        var container = $('.nv-list-container');
        if (container) {
          var w = container.clientWidth;
          var gap = window.innerWidth <= 768 ? 16 : 28;
          var cols = Math.max(2, Math.floor((w + gap) / (156 + gap)));
          state.pageSize = cols * 2;
        }

        renderGrid();
        bindTabs();
        bindGrid();
        bindGridResize();
        bindModal();
        bindGlobalOnce();
        initChartsIfReady();

        var m = location.hash.match(/^#b\/(.+)$/);
        if (m) openModal(m[1]);
      })
      .catch(function (err) {
        console.error('Books page error:', err);
        var host = $('.nv-list-container') || root;
        if (host) host.innerHTML = '<div class="nv-empty" style="display:block">数据加载失败：' + esc(err.message) + '</div>';
      });
  }

  function preloadTopCovers() {
    var top = state.items.filter(passFilter).slice(0, 8);
    top.forEach(function (i) {
      if (!i.cover) return;
      var l = document.createElement('link');
      l.rel = 'preload'; l.as = 'image'; l.href = i.cover;
      document.head.appendChild(l);
    });
  }

  // pjax 机制：主题在 pjax:success 时会重新执行所有 script[data-pjax]
  // （见 themes/reimu/source/js/pjax.js），即整段 IIFE 会重跑一次。
  // 因此这里只需直接 init()，不要再自行注册 pjax 监听（否则每次访问都会叠加）。
  if (document.readyState !== 'loading') init();
  else document.addEventListener('DOMContentLoaded', init, { once: true });
})();

/* Nebula Music Space / 深空星云音乐终端
 * ---------------------------------------------------------------
 * 播放引擎（useMetingPlayer）、歌单数据、PJAX 生命周期、歌词解析
 * 均保持原有逻辑不变；本文件在其上叠加：
 *   - NebulaRenderer  深空粒子星云 Canvas（播放状态响应）
 *   - simulateLevels  模拟频谱律动（跨域音源无法安全接入 Web Audio，
 *                     createMediaElementSource 会令无 CORS 的网易云
 *                     音源静音或输出全零数据，故用播放状态驱动，零副作用）
 *   - Listening Journey  星轨记忆（localStorage，不动后台）
