  const DEFAULT_TRACK = {
    id: 'midnight-demo',
    title: 'Midnight Radio',
    artist: 'Music Space',
    album: 'Digital Garden',
    cover: '',
    duration: 0,
    lrc: '[00:00.00]这里不仅收藏音乐\n[00:05.00]也收藏一段人生\n[00:11.00]第一次听它，是凌晨两点\n[00:18.00]世界安静得只剩下耳机里的光\n[00:25.00]把歌单，单独留一盏灯'
  };

  const SCENES = [
    { id: 'sakura', label: '夜樱' },
    { id: 'ink', label: '墨夜' },
    { id: 'lantern', label: '灯火' }
  ];

  const MODES = [
    { id: 'deep', label: '深空' },
    { id: 'focus', label: '专注' },
    { id: 'dream', label: '梦境' }
  ];

  /* 三主题星云色板：星点色 / 星云团色 / 高亮色 */
  const NEBULA_PALETTES = {
    sakura: {
      stars: ['139,233,255', '181,140,255', '235,235,255'],
      clouds: ['124,108,255', '181,108,255'],
      glow: '139,233,255'
    },
    ink: {
      stars: ['140,190,255', '57,197,255', '215,225,255'],
      clouds: ['57,140,255', '79,141,255'],
      glow: '57,197,255'
    },
    lantern: {
      stars: ['255,209,102', '255,179,92', '255,236,210'],
      clouds: ['255,140,66', '178,92,255'],
      glow: '255,209,102'
    }
  };

  const JOURNEY_KEY = 'ms-journey-v1';
  const JOURNEY_LIMIT = 60;

  function cx() {
    return Array.from(arguments).filter(Boolean).join(' ');
  }

  function clamp(number, min, max) {
    return Math.max(min, Math.min(max, number));
  }

  function fmtTime(seconds) {
    if (!Number.isFinite(seconds) || seconds <= 0) return '0:00';
    const minutes = Math.floor(seconds / 60);
    const remain = Math.floor(seconds % 60).toString().padStart(2, '0');
    return minutes + ':' + remain;
  }

  function parseLrc(raw) {
    if (!raw || typeof raw !== 'string') return [];
    const lines = [];
    raw.split(/\r?\n/).forEach(function (line) {
      const times = Array.from(line.matchAll(/\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?\]/g));
      const text = line.replace(/\[[^\]]+\]/g, '').trim();
      if (!times.length || !text) return;
      times.forEach(function (time) {
        const milliseconds = Number((time[3] || '0').padEnd(3, '0').slice(0, 3));
        lines.push({
          time: Number(time[1]) * 60 + Number(time[2]) + milliseconds / 1000,
          text: text
        });
      });
    });
    return lines.sort(function (a, b) { return a.time - b.time; });
  }

  function normalizeAudio(audio, index) {
    if (!audio) return Object.assign({}, DEFAULT_TRACK, { id: 'fallback-' + index });
    const title = audio.name || audio.title || audio.song || DEFAULT_TRACK.title;
    const artist = Array.isArray(audio.artist)
      ? audio.artist.join(' / ')
      : (audio.artist || audio.author || audio.singer || DEFAULT_TRACK.artist);
    const album = audio.album || audio.al || audio.source || '';
    const cover = audio.cover || audio.pic || audio.picture || audio.image || '';
    const id = String(audio.id || audio.song_id || audio.neteaseId || audio.url || title + '-' + artist || index);
    return {
      id: id,
      sourceId: String(audio.id || audio.song_id || audio.neteaseId || ''),
      title: title,
      artist: artist,
      album: album,
      cover: cover,
      url: audio.url,
      lrc: audio.lrc || audio.lyric || '',
      duration: Number(audio.duration) || 0,
      raw: audio
    };
  }

  /* ---------------- 星轨记忆（localStorage） ---------------- */

  function readJourney() {
    try {
      const parsed = JSON.parse(localStorage.getItem(JOURNEY_KEY) || '[]');
      return Array.isArray(parsed) ? parsed : [];
    } catch (error) {
      return [];
    }
  }

  function recordJourney(track, scene) {
    if (!track || !track.id || track.id.indexOf('fallback-') === 0) return;
    const now = new Date();
    const stamp = now.getFullYear() + '-' + (now.getMonth() + 1) + '-' + now.getDate();
    const entry = {
      id: track.id,
      title: track.title,
      artist: track.artist,
      cover: track.cover || '',
      date: stamp,
      time: now.toISOString(),
      scene: scene
    };
    try {
      const list = readJourney().filter(function (item) {
        return !(item.id === entry.id && item.date === entry.date);
      });
      list.unshift(entry);
      localStorage.setItem(JOURNEY_KEY, JSON.stringify(list.slice(0, JOURNEY_LIMIT)));
    } catch (error) { /* 存储不可用时静默跳过 */ }
  }

  /* ---------------- 模拟频谱律动 ----------------
   * 低频 bass：星云呼吸 / 唱片光环
   * 高频 treble：星点闪烁
   * 由播放时长驱动的多频正弦叠加，近似真实频谱包络。
   */
  function simulateLevels(timeSec, isPlaying, mode) {
    if (!isPlaying) return { beat: 0, shimmer: 0 };
    const t = timeSec || (Date.now() / 1000);
    let bass = 0.5
      + 0.28 * Math.sin(t * 2.1)
      + 0.16 * Math.sin(t * 0.53 + 1.3)
      + 0.1 * Math.sin(t * 3.7 + 0.5);
    let treble = 0.5
      + 0.3 * Math.sin(t * 6.3 + 0.7)
      + 0.2 * Math.sin(t * 11.7 + 2.1);
    if (mode === 'dream') { bass *= 0.55; treble *= 0.5; }
    if (mode === 'focus') { bass *= 0.7; treble *= 0.7; }
    return { beat: clamp(bass, 0, 1), shimmer: clamp(treble, 0, 1) };
  }

  /* ---------------- NebulaRenderer 星云系统 ---------------- */

  function NebulaRenderer(canvas, options) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.scene = options.scene;
    this.mode = options.mode;
    this.isPlaying = options.isPlaying;
    this.levels = { beat: 0, shimmer: 0 };
    this.running = false;
    this.raf = 0;
    this.last = 0;
    this.elapsed = 0;
    this.particles = [];
    this.clouds = [];
    this.onVisibility = this.onVisibility.bind(this);
    document.addEventListener('visibilitychange', this.onVisibility);
    this.resize();
    this.seed();
    this.start();
  }

  NebulaRenderer.prototype.onVisibility = function () {
    if (document.hidden) this.stop();
    else this.start();
  };

  NebulaRenderer.prototype.isMobile = function () {
    return window.innerWidth < 768;
  };

  NebulaRenderer.prototype.resize = function () {
    const parent = this.canvas.parentElement;
    const rect = parent ? parent.getBoundingClientRect() : { width: window.innerWidth, height: window.innerHeight };
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.width = Math.max(1, rect.width);
    this.height = Math.max(1, rect.height);
    this.canvas.width = this.width * dpr;
    this.canvas.height = this.height * dpr;
    this.canvas.style.width = this.width + 'px';
    this.canvas.style.height = this.height + 'px';
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  };

  NebulaRenderer.prototype.seed = function () {
