    if (this.mode === 'dream') count = Math.round(count * 0.45);
    if (this.scene === 'ink') count = Math.round(count * 0.7);

    const palette = NEBULA_PALETTES[this.scene] || NEBULA_PALETTES.sakura;
    this.particles = [];
    for (let i = 0; i < count; i++) {
      this.particles.push({
        x: Math.random() * this.width,
        y: Math.random() * this.height,
        r: 0.4 + Math.random() * 1.5,
        vx: (Math.random() - 0.5) * 0.08,
        vy: (Math.random() - 0.5) * 0.05,
        phase: Math.random() * Math.PI * 2,
        twinkleSpeed: 0.3 + Math.random() * 1.2,
        color: palette.stars[i % palette.stars.length]
      });
    }
    this.clouds = [];
    for (let i = 0; i < cloudCount; i++) {
      this.clouds.push({
        x: (0.2 + 0.6 * Math.random()) * this.width,
        y: (0.15 + 0.6 * Math.random()) * this.height,
        radius: Math.max(this.width, this.height) * (0.28 + Math.random() * 0.18),
        phase: Math.random() * Math.PI * 2,
