    ctx.clearRect(0, 0, this.width, this.height);

    const speedBoost = this.isPlaying ? (this.mode === 'dream' ? 1.05 : 1.2) : 0.5;
    const brightness = this.isPlaying ? 1.15 : 0.85;
    const beat = this.levels.beat;
    const shimmer = this.levels.shimmer;
    const t = this.elapsed;

    /* 星云团：低频驱动的呼吸光雾 */
