        + beat * 0.05
        + 0.02 * Math.sin(t * 0.22 + cloud.phase);
      cloud.x += Math.sin(t * 0.05 + cloud.phase) * cloud.drift * dt * 6;
      cloud.y += Math.cos(t * 0.04 + cloud.phase) * cloud.drift * dt * 4;
      if (cloud.x < -radius) cloud.x = this.width + radius * 0.5;
      if (cloud.x > this.width + radius) cloud.x = -radius * 0.5;
      if (cloud.y < -radius) cloud.y = this.height + radius * 0.5;
      if (cloud.y > this.height + radius) cloud.y = -radius * 0.5;
      const gradient = ctx.createRadialGradient(cloud.x, cloud.y, 0, cloud.x, cloud.y, radius);
      gradient.addColorStop(0, 'rgba(' + cloud.color + ',' + alpha.toFixed(3) + ')');
      gradient.addColorStop(1, 'rgba(' + cloud.color + ',0)');
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(cloud.x, cloud.y, radius, 0, Math.PI * 2);
      ctx.fill();
    });

    /* 星点：高频驱动的闪烁 */
    this.particles.forEach((star) => {
      star.x += star.vx * dt * 60 * speedBoost;
      star.y += star.vy * dt * 60 * speedBoost;
      if (star.x < -2) star.x = this.width + 2;
      if (star.x > this.width + 2) star.x = -2;
      if (star.y < -2) star.y = this.height + 2;
      if (star.y > this.height + 2) star.y = -2;
      const twinkle = 0.4 + 0.6 * (0.5 + 0.5 * Math.sin(t * star.twinkleSpeed + star.phase));
      const alpha = clamp(twinkle * brightness * (0.55 + shimmer * 0.45), 0, 1);
      ctx.beginPath();
      ctx.fillStyle = 'rgba(' + star.color + ',' + alpha.toFixed(3) + ')';
      ctx.arc(star.x, star.y, star.r, 0, Math.PI * 2);
      ctx.fill();
      if (star.r > 1.4 && alpha > 0.72) {
        ctx.beginPath();
        ctx.fillStyle = 'rgba(' + star.color + ',' + (alpha * 0.16).toFixed(3) + ')';
        ctx.arc(star.x, star.y, star.r * 3.4, 0, Math.PI * 2);
        ctx.fill();
      }
    });
  };

