        const fromWindow = Array.isArray(window.aplayers)
          ? window.aplayers[window.aplayers.length - 1]
          : null;
        if (fromWindow) candidates.push(fromWindow);
        return candidates.find(function (candidate) {
          return candidate && (candidate.audio || candidate.list || candidate.container);
        }) || null;
