        const audios = instance && instance.list && Array.isArray(instance.list.audios)
          ? instance.list.audios
          : [];
        if (audios.length) setTracks(audios.map(normalizeAudio));
        const audio = instance && instance.audio;
        const index = instance && instance.list && Number.isFinite(instance.list.index)
          ? instance.list.index
          : 0;
        const fallbackTrack = normalizeAudio(audios[index], index);
        setPlayer(function (previous) {
          return Object.assign({}, previous, {
            status: audio ? (audio.paused ? 'paused' : 'playing') : previous.status,
            currentIndex: index,
            currentTime: audio ? audio.currentTime || 0 : previous.currentTime,
            duration: audio ? (audio.duration || fallbackTrack.duration || 0) : previous.duration,
            volume: audio ? audio.volume : previous.volume,
            muted: audio ? audio.muted : previous.muted,
            speed: audio ? audio.playbackRate : previous.speed
