  function MusicSpaceApp(props) {
    const playerData = useMetingPlayer(props.root);
    const tracks = playerData.tracks;
    const player = playerData.player;
    const api = playerData.api;
    const currentTrack = tracks[player.currentIndex] || tracks[0] || DEFAULT_TRACK;
    const isPlaying = player.status === 'playing';

    const validScenes = SCENES.map(function (scene) { return scene.id; });
    const storedScene = localStorage.getItem('ms-scene-v5');
    const sceneState = React.useState(validScenes.includes(storedScene) ? storedScene : 'sakura');
    const scene = sceneState[0];
    const setSceneState = sceneState[1];

    const validModes = MODES.map(function (mode) { return mode.id; });
    const storedMode = localStorage.getItem('ms-mode-v1');
    const modeState = React.useState(validModes.includes(storedMode) ? storedMode : 'deep');
    const playMode = modeState[0];
    const setModeState = modeState[1];

    const journeyState = React.useState(readJourney);
    const journey = journeyState[0];
    const setJourney = journeyState[1];

    const title = props.root.dataset.title || '夜樱留声机';
    const subtitle = props.root.dataset.subtitle || '记录旋律经过的轨迹。';

    function setScene(nextScene) {
      setSceneState(nextScene);
      localStorage.setItem('ms-scene-v5', nextScene);
    }

    function setMode(nextMode) {
      setModeState(nextMode);
      localStorage.setItem('ms-mode-v1', nextMode);
    }

    /* 播放状态驱动模拟频谱 */
    const levels = simulateLevels(player.currentTime, isPlaying, playMode);

    /* 星轨记录：切歌即留痕（同曲同日去重） */
    React.useEffect(function () {
      if (!isPlaying) return;
      recordJourney(currentTrack, scene);
      setJourney(readJourney());
    }, [player.currentIndex, isPlaying]);

    /* 音乐统计 */
    const stats = React.useMemo(function () {
      const songCount = tracks.length;
      const totalSeconds = tracks.reduce(function (sum, track) { return sum + (track.duration || 0); }, 0);
      const hours = totalSeconds ? Math.round(totalSeconds / 3600) : 0;
      return { songs: songCount, hours: hours, memories: journey.length };
    }, [tracks, journey]);

    return h(React.Fragment, null,
      h(BackgroundRenderer, {
        mode: scene,
        playMode: playMode,
        cover: currentTrack.cover,
        isPlaying: isPlaying,
        levels: levels
      }),
      h('div', { className: cx('ms-stage', 'mode-' + playMode) },
        h('header', { className: 'ms-hero' },
          h('div', { className: 'ms-hero-mark', 'aria-hidden': 'true' }, h('span', null, '音')),
          h('div', { className: 'ms-hero-copy' },
            h('span', { className: 'ms-kicker' }, 'NEBULA MUSIC SPACE'),
            h('h1', null, title),
            h('p', null, subtitle)
          ),
          h('div', { className: 'ms-hero-stats' },
            h('div', { className: 'ms-hero-stat' }, h('strong', null, stats.songs), h('span', null, 'Songs')),
            h('div', { className: 'ms-hero-stat' }, h('strong', null, stats.hours || '—'), h('span', null, 'Hours')),
            h('div', { className: 'ms-hero-stat' }, h('strong', null, stats.memories), h('span', null, 'Memories'))
          )
        ),
        h('div', { className: 'ms-mode-switcher', 'aria-label': '聆听模式' },
          MODES.map(function (mode) {
            return h('button', {
              type: 'button',
              key: mode.id,
              className: cx('ms-mode-button', playMode === mode.id && 'is-active'),
              onClick: function () { setMode(mode.id); },
              title: mode.id === 'deep' ? '星云全开，默认体验' : (mode.id === 'focus' ? '降低动画与亮度，适合学习' : '粒子稀疏、节奏放缓，适合入睡前')
            }, mode.label);
          })
        ),
        h('main', { className: 'ms-deck' },
          h(Turntable, { track: currentTrack, player: player, api: api }),
          h(Library, {
            tracks: tracks,
            currentIndex: player.currentIndex,
            player: player,
            track: currentTrack,
            api: api,
            scene: scene,
            setScene: setScene,
            journey: journey
          })
        ),
        h(MobileDock, { track: currentTrack, player: player, api: api })
      )
    );
  }

  function initMusicSpace() {
    const root = document.getElementById('music-space-root');
    if (!root || root.dataset.mounted === 'true') return;
    if (!window.React || !window.ReactDOM) {
      window.setTimeout(initMusicSpace, 120);
      return;
    }
    root.dataset.mounted = 'true';
    const reactRoot = window.ReactDOM.createRoot(root);
    root.__musicSpaceRoot = reactRoot;
    reactRoot.render(h(MusicSpaceApp, { root: root }));
  }

  function destroyMusicSpace() {
    const root = document.getElementById('music-space-root');
    if (root && root.__musicSpaceRoot) {
      root.__musicSpaceRoot.unmount();
      delete root.__musicSpaceRoot;
      delete root.dataset.mounted;
    }
  }

  window.initMusicSpace = initMusicSpace;
  window.destroyMusicSpace = destroyMusicSpace;

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initMusicSpace);
  else initMusicSpace();
  document.addEventListener('pjax:complete', initMusicSpace);
  document.addEventListener('pjax:send', destroyMusicSpace);
})();

/* ============================================================
   Music Universe — a 3D lyric cosmos (Three.js, no build step)
   Starfield · galaxy spiral · nebula · dust · meteors ·
