      // core glow follows album + energy (Bloom breathing) + mid-freq
      core.m.color.copy(uColorA.value);
      core.m.opacity = 0.16 + uEnergy.value * 0.12 + hover.on * 0.06 + uMid.value * 0.1;
      core.sp.scale.set(520 + hover.on * 60 + uMid.value * 40, 340 + hover.on * 40 + uMid.value * 26, 1);

      // lyric planes: keep facing camera-ish (billboard yaw only), choreograph depth
      layoutLyrics();
      lyricGroup.rotation.y = lerp(lyricGroup.rotation.y, orbit.yaw * 0.12, 0.1);   // tiny parallax, "几乎保持稳定"
      lyricGroup.position.x = -pointer.x * 3;
      lyricGroup.position.y = pointer.y * 2;

      // album planet: slow self-spin + rim glow follows album color + treble shimmer
      planet.mesh.rotation.y += dt * 0.15;
      planet.glowMat.color.copy(uColorA.value);
      planet.glowMat.opacity = 0.4 + uMid.value * 0.2 + uTreble.value * 0.15;

      // meteors
      if (!reduced) {
        meteors.next -= dt;
        if (meteors.next <= 0) { launchMeteor(meteors); meteors.next = 5 + Math.random() * 7; }
        meteors.pool.forEach(function (sp) {
          if (!sp.userData.active) return;
          sp.userData.life += dt;
          sp.position.x += sp.userData.vx * dt;
          sp.position.y += sp.userData.vy * dt;
          var l = sp.userData.life;
          sp.material.opacity = l < 0.25 ? l / 0.25 * 0.7 : Math.max(0, 0.7 - (l - 0.25) * 0.5);
          if (sp.material.opacity <= 0.01 && l > 0.3) { sp.userData.active = false; sp.material.opacity = 0; }
        });
      }

      // report zoom (for lyric scaling in DOM)
      if (zoomCb) {
        var z = (CAM_DEFAULT - cam.z) / (CAM_DEFAULT - CAM_MIN); // 0 default .. 1 closest, negative when far
        z = clamp(z, -0.6, 1);
        if (Math.abs(z - lastZoomReport) > 0.01) { lastZoomReport = z; zoomCb(z); }
      }

      renderer.render(scene, camera);
      raf = requestAnimationFrame(frame);
    }
    var raf = requestAnimationFrame(frame);

    // ============================================================
    //  Public API
    // ============================================================
    function hexToColor(hex) { try { return new THREE.Color(hex); } catch (e) { return null; } }

    var api = {
      setAlbumColors: function (a, b) {
        var ca = hexToColor(a), cb = hexToColor(b);
        if (ca) targetA = ca;
        if (cb) targetB = cb;
      },
      setPlaying: function (v) {
        playing = !!v;
        // browsers require a user gesture to start AudioContext — resume on play
        if (v && audioG.ctx && audioG.ctx.state === 'suspended') audioG.ctx.resume().catch(function () {});
      },
      setHover: function (v) { hover.target = v ? 1 : 0; },
      onLyricHover: function (cb) { lyricHoverCb = cb; },
      // live visual knobs from the console
      setVisualParams: function (p) {
        p = p || {};
        if (p.starBrightness != null) uStarBright.value = clamp(p.starBrightness, 0, 1);
        if (p.starDensity != null) uStarCut.value = clamp(1.15 - p.starDensity, 0, 0.85);  // density 1.15+→show all, 0.3→~85% culled
        if (p.reactivity != null) vparam.react = clamp(p.reactivity, 0, 2);
        if (p.depth != null) vparam.depth = clamp(p.depth, 0, 2);
        if (p.cinematic != null) {
          vparam.cine = clamp(p.cinematic, 0, 1);
          try { if (interactionEl && interactionEl.closest) { var host = interactionEl.closest('.music-space'); if (host) host.style.setProperty('--ms-cine', String(vparam.cine)); } } catch (e) {}
        }
      },
      // full parsed lyric lines: [{time, text}]
      setLyrics: function (lines) {
        lyricLines = Array.isArray(lines) ? lines : [];
        lyricCurrent = -1;   // force refresh on next state
      },
      // called when playback line/progress changes
      setLyricState: function (currentIndex, progress) {
        var changed = currentIndex !== lyricCurrent;
        lyricCurrent = currentIndex;
        lyricProgress = clamp(progress || 0, 0, 1);
        if (changed) refreshLyricSlots();
      },
      setLyricStyle: function (colorHex, glow) {
        if (colorHex) lyricColorHex = colorHex;
        if (glow != null) lyricGlow = glow;
      },
      // album cover → planet texture (crossOrigin; falls back to color on taint)
      setCover: function (url, colorHex) {
        if (colorHex) { try { planet.mat.color.set(colorHex); } catch (e) {} }
        if (!url) return;
        texLoader.load(url, function (tex) {
          tex.colorSpace = THREE.SRGBColorSpace || tex.colorSpace;
          if (planet.tex) planet.tex.dispose();
          planet.tex = tex;
          planet.mat.map = tex; planet.mat.color.set('#ffffff'); planet.mat.needsUpdate = true;
        }, undefined, function () { /* keep color-sphere fallback */ });
      },
      attachAudio: attachAudio,
      reset: onDbl,
      resize: resize,
      onZoom: function (cb) { zoomCb = cb; },
      pause: function () { running = false; if (raf) cancelAnimationFrame(raf); },
      resume: function () { if (!running) { running = true; clock.getDelta(); raf = requestAnimationFrame(frame); } },
      dispose: function () {
        running = false;
        if (raf) cancelAnimationFrame(raf);
        interactionEl.removeEventListener('pointerdown', onDown);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
        interactionEl.removeEventListener('wheel', onWheel);
        interactionEl.removeEventListener('dblclick', onDbl);
        window.removeEventListener('resize', resize);
        [stars, galaxy, dust].forEach(function (o) { if (o.g) o.g.dispose(); if (o.m) o.m.dispose(); });
        nebula.clouds.forEach(function (s) { s.material.dispose(); });
        nebula.tex.dispose(); core.m.dispose(); if (core.m.map) core.m.map.dispose();
        meteors.pool.forEach(function (s) { s.material.dispose(); }); meteors.tex.dispose();
        lyricSlots.forEach(function (m) { if (m.material.uniforms.uMap.value) m.material.uniforms.uMap.value.dispose(); m.geometry.dispose(); m.material.dispose(); });
        planet.mesh.geometry.dispose(); planet.mat.dispose();
        if (planet.tex) planet.tex.dispose(); planet.glowMat.dispose(); planet.glowTex.dispose();
        // NOTE: leave window.__msAudioGraph (ctx + sourced elements) alive across pjax —
        // an <audio> can only be source-d once per AudioContext; re-mount reuses it.
        scene.traverse(function () {});
        try { renderer.dispose(); } catch (e) {}
      }
    };
    return api;
  }

  window.MusicUniverse = { create: create };
})();

(() => {
  'use strict';

  const VIS_NETWORK_SRC = 'https://unpkg.com/vis-network@9.1.6/standalone/umd/vis-network.min.js';
  let visLoader = null;

  const loadVisNetwork = () => {
    if (window.vis?.Network) return Promise.resolve();
    if (visLoader) return visLoader;

    visLoader = new Promise((resolve, reject) => {
      const existing = document.querySelector(`script[src="${VIS_NETWORK_SRC}"]`);
      if (existing) {
        existing.addEventListener('load', resolve, { once: true });
        existing.addEventListener('error', reject, { once: true });
        return;
      }

      const script = document.createElement('script');
      script.src = VIS_NETWORK_SRC;
      script.async = true;
      script.onload = resolve;
      script.onerror = reject;
      document.head.appendChild(script);
    });

    return visLoader;
  };

  const showError = (container) => {
    container.replaceChildren();
    const error = document.createElement('div');
    error.className = 'tag-network-error';
    error.textContent = '标签网络加载失败，请稍后再试。';
    container.appendChild(error);
  };

  const initTagNetwork = async () => {
    const container = document.getElementById('tag-network');
    if (!container || container.dataset.tagNetworkLoading === 'true') return;

    container.dataset.tagNetworkLoading = 'true';
    if (container.__tagNetworkInstance) {
      container.__tagNetworkInstance.destroy();
      container.__tagNetworkInstance = null;
    }

    try {
      await loadVisNetwork();

      const response = await fetch('/tag-network.json', { cache: 'no-store' });
      if (!response.ok) throw new Error(`tag-network.json ${response.status}`);

      const data = await response.json();
      const nodes = (data.nodes || []).map((node) => ({
        id: node.id,
        label: `${node.name} (${node.count})`,
        value: node.count,
        title: `${node.name}: ${node.count} 篇文章`,
        shape: 'dot',
        size: Math.max(20, Math.min(60, Number(node.count || 0) * 12)),
        color: {
          background: '#ff7c7c',
          border: '#ff5252',
          highlight: { background: '#ff5252', border: '#d32f2f' },
        },
        font: { color: '#666', size: 13, face: 'sans-serif' },
        borderWidth: 2,
      }));

      const edges = (data.edges || []).map((edge) => ({
        from: edge.source,
        to: edge.target,
        width: Math.max(1, Number(edge.weight || 1)),
        color: { color: 'rgba(255, 130, 130, 0.3)', highlight: '#ff5252', hover: '#ff5252' },
        smooth: { type: 'continuous' },
      }));

      container.replaceChildren();
      const network = new window.vis.Network(container, { nodes, edges }, {
        physics: {
          solver: 'forceAtlas2Based',
          forceAtlas2Based: {
            gravitationalConstant: -40,
            centralGravity: 0.005,
            springLength: 150,
            springConstant: 0.02,
          },
          stabilization: { iterations: 200 },
        },
        interaction: { hover: true, tooltipDelay: 100 },
        edges: { smooth: { type: 'continuous' } },
      });

      network.on('click', (params) => {
        if (!params.nodes.length) return;
        location.href = `/tags/${encodeURIComponent(params.nodes[0])}/`;
      });

      container.__tagNetworkInstance = network;
    } catch (error) {
      console.error('[tag-network] init failed:', error);
      showError(container);
    } finally {
      delete container.dataset.tagNetworkLoading;
    }
  };

  if (!window.__tagNetworkEventsBound) {
    window.__tagNetworkEventsBound = true;
    document.addEventListener('pjax:complete', initTagNetwork);
    document.addEventListener('pjax:end', initTagNetwork);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initTagNetwork, { once: true });
  } else {
    initTagNetwork();
  }
})();

/* ============================================
 * 统一侧边栏（side-panel）控制器
 * - 折叠/展开切换（localStorage 记忆）
 * - AI 中枢 / 搜索 / 音乐 三个新图标的入口绑定
 * - 与现有 anomaly-center.js / theme-switcher.js / 等协同工作
 * ============================================ */

(() => {
  'use strict';

  const STATE_KEY = 'side-panel-state';

  const $ = (id) => document.getElementById(id);

  const expand = () => {
    const panel = $('side-panel');
    if (!panel || !panel.classList.contains('collapsed')) return;
    panel.classList.remove('collapsed');
    try { localStorage.setItem(STATE_KEY, 'expanded'); } catch (_) {}
  };

  const collapse = () => {
    const panel = $('side-panel');
    if (!panel || panel.classList.contains('collapsed')) return;
    panel.classList.add('collapsed');
    try { localStorage.setItem(STATE_KEY, 'collapsed'); } catch (_) {}
  };

  const toggle = () => {
    const panel = $('side-panel');
    if (!panel) return;
    if (panel.classList.contains('collapsed')) expand(); else collapse();
  };

  /** 打开 AI 中枢面板（沿用现有 ai-chat.js 逻辑：模拟 toggle 按钮点击） */
  const openAI = () => {
    const aiToggle = document.getElementById('blog-ai-toggle');
    if (aiToggle) aiToggle.click();
  };

  /** 打开站内搜索（generator_search.js 暴露了 window 钩子；找不到时用弹窗模板 .reimu-popup） */
  const openSearch = () => {
    // 1. 优先使用 algolia/generator 提供的钩子
    if (typeof window.openReimuSearch === 'function') {
      window.openReimuSearch();
      return;
    }
    // 2. 备用方案：直接显示搜索弹窗
    const popup = document.querySelector('.site-search .reimu-popup');
    const mask = document.getElementById('mask');
    if (popup) {
      popup.classList.add('popup-show');
      popup.style.display = '';
    }
    if (mask) mask.classList.remove('hide');
    const input = document.getElementById('reimu-search-input');
    if (input) setTimeout(() => input.focus(), 50);
  };

  /** 切换音乐播放（查找 aplayer 实例并触发 play/pause） */
  const toggleMusic = () => {
    const fixedPlayer = document.querySelector('.aplayer.aplayer-fixed');
    if (!fixedPlayer) return;
    const btn = fixedPlayer.querySelector('.aplayer-play') || fixedPlayer.querySelector('.aplayer-pause');
    if (btn) btn.click();
  };

  // 事件委托：侧边栏内按钮统一监听
  if (!window.__sidePanelBound) {
    window.__sidePanelBound = true;

    document.addEventListener('click', (e) => {
      // 折叠手柄展开
      if (e.target.closest('#side-panel-tab')) {
        e.preventDefault();
        expand();
        return;
      }
      // 收起按钮
      if (e.target.closest('#side-panel-collapse')) {
        e.preventDefault();
        collapse();
        return;
      }
      // AI 中枢
      if (e.target.closest('#btn-ai-open')) {
        e.preventDefault();
        e.stopPropagation();
        openAI();
        return;
      }
      // 搜索
      if (e.target.closest('#btn-search-open')) {
        e.preventDefault();
        e.stopPropagation();
        openSearch();
        return;
      }
      // 音乐
      if (e.target.closest('#btn-music-toggle')) {
        e.preventDefault();
        e.stopPropagation();
        toggleMusic();
        return;
      }
      // 音乐可视化
      if (e.target.closest('#btn-music-visualizer')) {
        e.preventDefault();
        e.stopPropagation();
        window.open('/music/', '_blank');
        return;
      }
    });

    // 键盘快捷：Shift+` 反向折叠（避免与终端冲突，` 单独留给终端）
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const panel = $('side-panel');
        if (panel && !panel.classList.contains('collapsed')) collapse();
      }
    });
  }

  // 自动 hover 展开：鼠标进入 .side-panel 区域（收起态下）自动展开
  document.addEventListener('mouseover', (e) => {
    const panel = $('side-panel');
    if (!panel || !panel.classList.contains('collapsed')) return;
    if (e.target.closest('#side-panel')) {
      // 不自动展开，避免干扰；保留手动控制
    }
  });

  window.SidePanel = { expand, collapse, toggle };
})();

