<script>
  // 省份识别（兼容中文与英文写法）
  var PROVINCE_MAP = {
    '北京': '北京', '北京市': '北京', 'Beijing': '北京',
    '天津': '天津', '天津市': '天津', 'Tianjin': '天津',
    '河北': '河北', 'Hebei': '河北',
    '山西': '山西', 'Shanxi': '山西',
    '内蒙古': '内蒙古', 'Inner Mongolia': '内蒙古',
    '辽宁': '辽宁', 'Liaoning': '辽宁',
    '吉林': '吉林', 'Jilin': '吉林',
    '黑龙江': '黑龙江', 'Heilongjiang': '黑龙江',
    '上海': '上海', '上海市': '上海', 'Shanghai': '上海',
    '江苏': '江苏', 'Jiangsu': '江苏',
    '浙江': '浙江', 'Zhejiang': '浙江',
    '安徽': '安徽', 'Anhui': '安徽',
    '福建': '福建', 'Fujian': '福建',
    '江西': '江西', 'Jiangxi': '江西',
    '山东': '山东', 'Shandong': '山东',
    '河南': '河南', 'Henan': '河南',
    '湖北': '湖北', 'Hubei': '湖北',
    '湖南': '湖南', 'Hunan': '湖南',
    '广东': '广东', 'Guangdong': '广东',
    '广西': '广西', 'Guangxi': '广西',
    '海南': '海南', 'Hainan': '海南',
    '重庆': '重庆', '重庆市': '重庆', 'Chongqing': '重庆',
    '四川': '四川', 'Sichuan': '四川',
    '贵州': '贵州', 'Guizhou': '贵州',
    '云南': '云南', 'Yunnan': '云南',
    '西藏': '西藏', 'Tibet': '西藏',
    '陕西': '陕西', 'Shaanxi': '陕西',
    '甘肃': '甘肃', 'Gansu': '甘肃',
    '青海': '青海', 'Qinghai': '青海',
    '宁夏': '宁夏', 'Ningxia': '宁夏',
    '新疆': '新疆', 'Xinjiang': '新疆',
    '台湾': '台湾', 'Taiwan': '台湾',
    '香港': '香港', 'Hong Kong': '香港',
    '澳门': '澳门', 'Macau': '澳门'
  };

  function matchProvince(loc) {
    if (!loc) return null;
    for (var key in PROVINCE_MAP) {
      if (loc.indexOf(key) >= 0) return PROVINCE_MAP[key];
    }
    return null;
  }

  // 统计卡片
  function renderStats(points) {
    var locSet = {};
    var provSet = {};
    var dates = [];
    points.forEach(function (p) {
      locSet[p.lat.toFixed(4) + ',' + p.lng.toFixed(4)] = true;
      var prov = matchProvince(p.location);
      if (prov) provSet[prov] = true;
      if (p.date) dates.push(p.date);
    });
    dates.sort();
    document.getElementById('stat-places').textContent = Object.keys(locSet).length;
    document.getElementById('stat-posts').textContent = points.length;
    document.getElementById('stat-provs').textContent = Object.keys(provSet).length;
    document.getElementById('stat-earliest').textContent = dates[0] || '--';
  }

  // 时间线列表（按年份倒序）
  function renderTimeline(points) {
    var sorted = points.slice().sort(function (a, b) {
      return String(b.date || '').localeCompare(String(a.date || ''));
    });
    var byYear = {};
    sorted.forEach(function (p) {
      var y = (p.date || '').slice(0, 4) || '未知';
      (byYear[y] = byYear[y] || []).push(p);
    });
    var years = Object.keys(byYear).sort(function (a, b) { return b.localeCompare(a); });
    var wrap = document.getElementById('travel-timeline');
    wrap.innerHTML = '';
    years.forEach(function (y) {
      var yearEl = document.createElement('div');
      yearEl.className = 'timeline-year';
      yearEl.textContent = y + ' 年';
      wrap.appendChild(yearEl);
      byYear[y].forEach(function (p) {
        var item = document.createElement('div');
        item.className = 'timeline-item';
        var cover = p.cover
          ? '<img src="' + p.cover + '" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">'
          : '';
        item.innerHTML =
          '<div class="timeline-cover">' + (cover || '<span>' + ((p.title || '?').charAt(0)) + '</span>') + '</div>' +
          '<div class="timeline-body">' +
            '<div class="timeline-date">' + (p.date || '') + '</div>' +
            '<a class="timeline-title" href="' + p.url + '">' + (p.title || '未命名游记') + '</a>' +
            '<div class="timeline-loc">📍 ' + (p.location || '') + '</div>' +
          '</div>';
        wrap.appendChild(item);
      });
    });
  }

  // 当前位置定位（浏览器定位优先，失败回退 IP 定位）
  function locateMe(AMap, map) {
    var locEl = document.getElementById('stat-loc');
    if (!locEl) return;
    var markerAdded = false;
    AMap.plugin('AMap.Geolocation', function () {
      var geolocation;
      try {
        geolocation = new AMap.Geolocation({
          enableHighAccuracy: true,
          timeout: 8000,
          maximumAge: 300000,
          zoomToAccuracy: false,
          GeoLocationFirst: true
        });
      } catch (e) {
        locEl.textContent = '定位失败';
        return;
      }
      var showLocation = function (text, position) {
        locEl.textContent = text || '已定位';
        if (position && !markerAdded) {
          markerAdded = true;
          var marker = new AMap.Marker({
            position: position,
            content: '<div class="current-loc-marker"></div>',
            offset: new AMap.Pixel(-11, -11),
            title: '我在这里'
          });
          marker.setLabel({
            content: '<div class="loc-label">我在这里</div>',
            direction: 'top',
            offset: new AMap.Pixel(0, -6)
          });
          map.add(marker);
        }
      };
      // 浏览器定位
      try {
        geolocation.getCurrentPosition(function (status, result) {
          if (status === 'complete' && result && result.position) {
            var comp = result.addressComponent || {};
            var addr = result.formattedAddress || comp.city || comp.province || '';
            showLocation(addr, result.position);
          } else {
            // 回退 IP 定位（仅城市级别）
            geolocation.getCityInfo(function (status2, info) {
              var data = status2 === 'complete' ? info : status2;
              if (data && data.city) {
                var c = data.center;
                var pos = null;
                if (c) {
                  if (typeof AMap.LngLat !== 'undefined' && c instanceof AMap.LngLat) pos = c;
                  else if (c.lng != null) pos = [c.lng, c.lat];
                  else if (Array.isArray(c)) pos = c;
                }
                showLocation(data.city + (pos ? '' : '（IP 定位）'), pos);
              } else {
                locEl.textContent = '定位失败';
              }
            });
          }
        });
      } catch (e) {
        locEl.textContent = '定位失败';
      }
    });
  }

  function initTravelMap(AMap) {
      document.getElementById('travel-map-container').innerHTML = '';

      // 使用 2D 视图，强制降级，避免任何由于 WebGL/显卡 导致的渲染黑屏问题
      const map = new AMap.Map('travel-map-container', {
        zoom: 4,
        center: [104.397394, 31.258866],
        viewMode: '2D'
      });

      fetch('/travel-map-data.json')
        .then(r => r.json())
        .then(points => {
          if (!points || points.length === 0) {
            console.log("JSON 数据为空");
            return;
          }

          // 统计卡片 & 时间线
          renderStats(points);
          renderTimeline(points);

          // 轨迹连线（按时间顺序）
          const sorted = points.slice().sort((a, b) =>
            String(a.date || '').localeCompare(String(b.date || ''))
          );
          const polyline = new AMap.Polyline({
            path: sorted.map(p => [p.lng, p.lat]),
            strokeColor: '#ff5252',
            strokeWeight: 3,
            strokeOpacity: 0.7,
            strokeStyle: 'dashed',
            lineJoin: 'round'
          });
          map.add(polyline);

          // 足迹聚合点
          const clusterData = points.map(p => {
            return {
              lnglat: [p.lng, p.lat],
              _raw: p
            }
          });

          const infoWindow = new AMap.InfoWindow({
              isCustom: true,
              offset: new AMap.Pixel(0, -35)
          });

          let cluster = new AMap.MarkerCluster(map, clusterData, {
              gridSize: 80,
              renderClusterMarker: function(context) {
                  const div = document.createElement('div');
                  div.className = 'cluster-marker';
                  div.innerHTML = context.count;
                  context.marker.setOffset(new AMap.Pixel(-18, -18));
                  context.marker.setContent(div);
              },
              renderMarker: function(context) {
                  const p = context.data[0]._raw;
                  const marker = context.marker;

                  marker.on('click', () => {
                    const coverHtml = p.cover ? `<img src="${p.cover}" onerror="this.style.display='none'" />` : '';
                    const locHtml = p.location ? `<div>📍 ${p.location}</div>` : '';
                    const dateHtml = p.date ? `<div>📅 ${p.date}</div>` : '';

                    const content = `
                      <div class="custom-info-window">
                        ${coverHtml}
                        <div class="title">${p.title}</div>
                        <div class="meta">${locHtml}${dateHtml}</div>
                        <a href="${p.url}" class="btn">阅读游记 →</a>
                      </div>
                    `;
                    infoWindow.setContent(content);
                    infoWindow.open(map, marker.getPosition());
                  });
              }
          });

          map.setFitView();
          locateMe(AMap, map);
        })
        .catch(err => {
          console.error('获取足迹数据失败:', err);
        });
  }

  function loadAMap() {
      try {
          if (window.AMap && window.AMap.MarkerCluster) {
              initTravelMap(window.AMap);
          } else if (window.AMapLoader) {
              window.AMapLoader.load({
                  key: '675f761a79ef4cfbdb279d5c05543039',
                  version: "2.0",
                  plugins: ['AMap.MarkerCluster', 'AMap.Geolocation']
              }).then(initTravelMap).catch(showError);
          } else {
              const script = document.createElement('script');
              script.src = 'https://webapi.amap.com/loader.js';
              script.onload = () => {
                  window.AMapLoader.load({
                      key: '675f761a79ef4cfbdb279d5c05543039',
                      version: "2.0",
                      plugins: ['AMap.MarkerCluster', 'AMap.Geolocation']
                  }).then(initTravelMap).catch(showError);
              };
              script.onerror = () => showError("高德地图加载脚本网络请求失败");
              document.head.appendChild(script);
          }
      } catch (e) {
          showError(e);
      }
  }

  function showError(e) {
      console.error(e);
      document.getElementById('travel-map-container').innerHTML = `<div style="text-align:center;padding:100px 20px;color:#ff5252;background:#1a1a1a;height:100%;">地图加载失败: ${e.message || e}</div>`;
  }

  loadAMap();
</script>

